public void Initialize(IncrementalGeneratorInitializationContext context) {
        IncrementalValuesProvider<ParseResult> projectionResults = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                "Hexalith.FrontComposer.Contracts.Attributes.ProjectionAttribute",
                predicate: static (node, _) => node is TypeDeclarationSyntax,
                transform: static (ctx, ct) => AttributeParser.Parse(ctx, ct))
            .Where(static result => result.Model is not null || result.Diagnostics.Count > 0)
            .WithTrackingName("Parse");

        IncrementalValuesProvider<CommandParseResult> commandResults = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                "Hexalith.FrontComposer.Contracts.Attributes.CommandAttribute",
                predicate: static (node, _) => node is TypeDeclarationSyntax,
                transform: static (ctx, ct) => CommandParser.Parse(ctx, ct))
            .Where(static result => result.Model is not null || result.Diagnostics.Count > 0)
            .WithTrackingName("ParseCommand");

        // Story 6-2 T3 — incremental discovery of [ProjectionTemplate] markers.
        IncrementalValuesProvider<ProjectionTemplateMarkerResult> templateResults = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                ProjectionTemplateMarkerParser.ProjectionTemplateAttributeName,
                predicate: static (node, _) => node is ClassDeclarationSyntax,
                transform: static (ctx, ct) => ProjectionTemplateMarkerParser.Parse(ctx, ct))
            .Where(static result => result.Marker is not null || result.Diagnostics.Count > 0)
            .WithTrackingName("ParseProjectionTemplate");

        IncrementalValueProvider<ImmutableArray<ProjectionTemplateMarkerResult>> collectedTemplates = templateResults.Collect();

        IncrementalValueProvider<ImmutableArray<ParseResult>> collectedProjections = projectionResults.Collect();
        IncrementalValueProvider<ImmutableArray<CommandParseResult>> collectedCommands = commandResults.Collect();
        IncrementalValueProvider<DriftOptionsResult> driftOptions = context.AnalyzerConfigOptionsProvider
            .Select(static (provider, _) => DriftOptions.Bind(provider));
        IncrementalValuesProvider<DriftBaselineInput> driftBaselineInputs = context.AdditionalTextsProvider
            .Where(static text => DriftBaselineInput.IsCandidate(text.Path))
            .Select(static (text, ct) => DriftBaselineInput.FromAdditionalText(text, ct))
            .WithTrackingName("LoadDriftBaselines");
        IncrementalValueProvider<ImmutableArray<DriftBaselineInput>> collectedDriftBaselines = driftBaselineInputs.Collect();

        // Story 9-1 review P12 (AC10): drift comparison no longer depends on the compilation.
        // Source locations come from parsed declaration models, so combining CompilationProvider
        // here was invalidating drift output on every unrelated compilation change.
        context.RegisterSourceOutput(
            collectedProjections.Combine(collectedCommands).Combine(collectedDriftBaselines.Combine(driftOptions)),
            static (spc, source) => {
                ImmutableArray<ParseResult> projections = source.Left.Left;
                ImmutableArray<CommandParseResult> commands = source.Left.Right;
                ImmutableArray<DriftBaselineInput> baselineInputs = source.Right.Left;
                DriftOptionsResult optionsResult = source.Right.Right;

                foreach (DriftDiagnosticFact diagnostic in optionsResult.Diagnostics) {
                    spc.ReportDiagnostic(diagnostic.ToDiagnostic());
                }

                // Story 9-1 review P4: drift detection is opt-in. Don't load or compare unless
                // the adopter explicitly set HfcDriftDetectionEnabled — a stray *.json
                // AdditionalText must not produce HFC1060/HFC1064 noise.
                if (!optionsResult.Options.Enabled) {
                    return;
                }

                DriftBaselineLoadResult baseline = DriftBaselineLoader.Load(baselineInputs, optionsResult.Options);
                foreach (DriftDiagnosticFact diagnostic in baseline.Diagnostics) {
                    spc.ReportDiagnostic(diagnostic.ToDiagnostic());
                }

                // Story 9-1 review P3 (AC2): a baseline-with-no-current-source run must still
                // emit RemovedDeclaration / RemovedProperty drift. Don't gate on hasContracts.
                if (!baseline.ComparisonEnabled) {
                    return;
                }

                var current = DriftCurrentSnapshot.From(projections, commands);
                DriftComparisonResult comparison = DriftComparisonService.Compare(
                    current,
                    baseline.Baseline,
                    optionsResult.Options.MaxDiagnostics,
                    optionsResult.Options.DriftSeverity);
                foreach (DriftDiagnosticFact diagnostic in comparison.Diagnostics) {
                    spc.ReportDiagnostic(diagnostic.ToDiagnostic());
                }
            });

        // Story 9-1 review P-D1 (AC14): trim/AOT diagnostic requires looking at the compilation
        // for adopter-supplied IActionQueueProjectionCatalog evidence. Run as a separate
        // RegisterSourceOutput so the compilation dependency does not leak into drift comparison.
        // The advisory is independent of HfcDriftDetectionEnabled — trim/AOT safety advice
        // applies whether or not drift detection is opted in.
        context.RegisterSourceOutput(
            context.CompilationProvider.Combine(driftOptions).Combine(collectedProjections.Combine(collectedCommands)),
            static (spc, source) => {
                Compilation compilation = source.Left.Left;
                DriftOptionsResult optionsResult = source.Left.Right;
                ImmutableArray<ParseResult> projections = source.Right.Left;
                ImmutableArray<CommandParseResult> commands = source.Right.Right;

                if (!optionsResult.Options.TrimOrAotAdvisoryEnabled) {
                    return;
                }

                bool hasContracts = projections.Any(static p => p.Model is not null)
                    || commands.Any(static c => c.Model is not null);
                if (!hasContracts) {
                    return;
                }

                if (HasActionQueueProjectionCatalogOverride(compilation)) {
                    return;
                }

                spc.ReportDiagnostic(DriftDiagnosticFact.TrimAot().ToDiagnostic());
            });

        context.RegisterSourceOutput(
            collectedProjections.Combine(collectedCommands).Combine(collectedTemplates),
            static (spc, source) => {
                ImmutableArray<ParseResult> projections = source.Left.Left;
                ImmutableArray<CommandParseResult> commands = source.Left.Right;
                ImmutableArray<ProjectionTemplateMarkerResult> templates = source.Right;
                // Story 6-2 — Razor/Web compilations may carry only [ProjectionTemplate] markers
                // (templates) and reference projections from a separate domain assembly. Suppress
                // HFC1001 when at least one marker was discovered so adopters do not see a
                // misleading "no types found" warning on template-only projects.
                if (projections.Length == 0 && commands.Length == 0 && templates.Length == 0) {
                    spc.ReportDiagnostic(Diagnostic.Create(
                        DiagnosticDescriptors.NoAnnotatedTypesFound,
                        Location.None,
                        "No [Command] or [Projection] types found in compilation"));
                }
            });

        context.RegisterSourceOutput(
            collectedProjections.Combine(collectedCommands),
            static (spc, source) => {
                ImmutableArray<DomainModel>.Builder projectionBuilder = ImmutableArray.CreateBuilder<DomainModel>();
                foreach (ParseResult projection in source.Left) {
                    if (projection.Model is not null) {
                        projectionBuilder.Add(projection.Model);
                    }
                }

                ImmutableArray<CommandModel>.Builder commandBuilder = ImmutableArray.CreateBuilder<CommandModel>();
                foreach (CommandParseResult command in source.Right) {
                    if (command.Model is not null) {
                        commandBuilder.Add(command.Model);
                    }
                }

                if (projectionBuilder.Count == 0 && commandBuilder.Count == 0) {
                    return;
                }

                spc.AddSource(
                    McpManifestEmitter.GeneratedHintName,
                    McpManifestEmitter.Emit(commandBuilder.ToImmutable(), projectionBuilder.ToImmutable()));
            });

        context.RegisterSourceOutput(projectionResults, static (spc, result) => {
            foreach (DiagnosticInfo diagInfo in result.Diagnostics) {
                spc.ReportDiagnostic(Diagnostic.Create(
                    GetDescriptor(diagInfo.Id, diagInfo.Severity),
                    diagInfo.ToLocation(),
                    diagInfo.Message));
            }

            if (result.Model is not null) {
                // Story 4-1 T2.5 — Transform-stage diagnostics (HFC1023 Dashboard fallback)
                // travel through the same per-projection reporter.
                List<DiagnosticInfo> transformDiagnostics = [];
                RazorModel razorModel = RazorModelTransform.Transform(result.Model, transformDiagnostics);
                foreach (DiagnosticInfo diagInfo in transformDiagnostics) {
                    spc.ReportDiagnostic(Diagnostic.Create(
                        GetDescriptor(diagInfo.Id, diagInfo.Severity),
                        diagInfo.ToLocation(),
                        diagInfo.Message));
                }

                FluxorModel fluxorModel = FluxorModelTransform.Transform(result.Model);
                RegistrationModel registrationModel = RegistrationModelTransform.Transform(result.Model);

                string hintPrefix = GetQualifiedHintPrefix(result.Model.Namespace, result.Model.TypeName);
                spc.AddSource(hintPrefix + ".g.razor.cs", RazorEmitter.Emit(razorModel));
                spc.AddSource(hintPrefix + "Feature.g.cs", FluxorFeatureEmitter.Emit(fluxorModel));
                spc.AddSource(hintPrefix + "Actions.g.cs", FluxorActionsEmitter.EmitActions(fluxorModel));
                spc.AddSource(hintPrefix + "Reducers.g.cs", FluxorActionsEmitter.EmitReducers(fluxorModel));
                spc.AddSource(hintPrefix + "Registration.g.cs", RegistrationEmitter.Emit(registrationModel));
            }
        });

        // Story 6-2 T3 — per-marker diagnostics (parser-level: HFC1033/HFC1034/HFC1035/HFC1036).
        context.RegisterSourceOutput(templateResults, static (spc, result) => {
            foreach (DiagnosticInfo diagInfo in result.Diagnostics) {
                spc.ReportDiagnostic(Diagnostic.Create(
                    GetDescriptor(diagInfo.Id, diagInfo.Severity),
                    diagInfo.ToLocation(),
                    diagInfo.Message));
            }
        });

        // Story 6-2 T3 — emit the consolidated template manifest plus duplicate diagnostics
        // (HFC1037). Driven from collectedTemplates so the manifest source is regenerated
        // only when a marker actually changes.
        context.RegisterSourceOutput(collectedTemplates, static (spc, results) => {
            ImmutableArray<ProjectionTemplateMarkerInfo>.Builder builder = ImmutableArray.CreateBuilder<ProjectionTemplateMarkerInfo>();
            foreach (ProjectionTemplateMarkerResult result in results) {
                // Story 6-2 T7 — exclude markers whose major contract version is incompatible.
                // The marker still keeps its HFC1035 warning (already emitted in the per-marker
                // pass above); but the descriptor is suppressed so runtime selection cannot
                // run a template against a mismatched context shape.
                if (result.Marker is null) {
                    continue;
                }

                int markerMajor = result.Marker.ExpectedContractVersion / 1_000_000;
                if (markerMajor != ProjectionTemplateMarkerParser.CurrentContractMajor) {
                    continue;
                }

                builder.Add(result.Marker);
            }

            ProjectionTemplateManifestEmitter.ManifestEmissionResult emission =
                ProjectionTemplateManifestEmitter.Emit(builder.ToImmutable());

            foreach (DiagnosticInfo diagInfo in emission.DuplicateDiagnostics) {
                spc.ReportDiagnostic(Diagnostic.Create(
                    GetDescriptor(diagInfo.Id, diagInfo.Severity),
                    diagInfo.ToLocation(),
                    diagInfo.Message));
            }

            spc.AddSource(ProjectionTemplateManifestEmitter.GeneratedHintName, emission.Source);
        });

        IncrementalValueProvider<bool> asyncValidationSupport = context.CompilationProvider.Select(static (compilation, _) =>
            compilation.GetTypeByMetadataName("Microsoft.AspNetCore.Components.Forms.EditContext")?
                .GetMembers("ValidateAsync").OfType<IMethodSymbol>().Any(method => !method.IsStatic) == true);
        context.RegisterSourceOutput(commandResults.Combine(asyncValidationSupport), static (spc, pair) => {
            var (result, useAsyncValidation) = pair;
            foreach (DiagnosticInfo diagInfo in result.Diagnostics) {
                spc.ReportDiagnostic(Diagnostic.Create(
                    GetDescriptor(diagInfo.Id, diagInfo.Severity),
                    diagInfo.ToLocation(),
                    diagInfo.Message));
            }

            if (result.Model is not null) {
                CommandFluxorModel fluxorModel = CommandFluxorTransform.Transform(result.Model);
                CommandFormModel formModel = CommandFormTransform.Transform(result.Model);
                RegistrationModel registrationModel = RegistrationModelTransform.TransformCommand(result.Model);
                CommandRendererModel rendererModel = CommandRendererTransform.Transform(result.Model, fluxorModel);

                // Suffix with ".Command" segment so command-pipeline hints never collide with
                // projection-pipeline hints when a type carries both attributes.
                // (See code-review 2026-04-15, patch P6.)
                string hintPrefix = GetQualifiedHintPrefix(result.Model.Namespace, result.Model.TypeName) + ".Command";
                spc.AddSource(hintPrefix + "Form.g.razor.cs", CommandFormEmitter.Emit(formModel, fluxorModel, useAsyncValidation));
                spc.AddSource(hintPrefix + "Actions.g.cs", CommandFluxorActionsEmitter.Emit(fluxorModel));
                spc.AddSource(hintPrefix + "LifecycleFeature.g.cs", CommandFluxorFeatureEmitter.Emit(fluxorModel));
                spc.AddSource(hintPrefix + "Registration.g.cs", RegistrationEmitter.Emit(registrationModel));

                // Story 2-2 Task 8: density-driven renderer + per-command LastUsed subscriber +
                // (conditional) routable FullPage page.
                spc.AddSource(hintPrefix + "Renderer.g.razor.cs", CommandRendererEmitter.Emit(rendererModel));
                spc.AddSource(hintPrefix + "LastUsedSubscriber.g.cs", LastUsedSubscriberEmitter.Emit(fluxorModel));
                if (result.Model.Density == Hexalith.FrontComposer.SourceTools.Parsing.CommandDensity.FullPage) {
                    spc.AddSource(hintPrefix + "Page.g.razor.cs", CommandPageEmitter.Emit(rendererModel));
                }

                // Story 2-3 Decision D4/D16: per-command lifecycle bridge — forwards Fluxor actions
                // to ILifecycleStateService so cross-command correlation-keyed consumers (Story 2-4
                // FcLifecycleWrapper) can subscribe to a single service instead of reflecting over
                // N generated features.
                spc.AddSource(hintPrefix + "LifecycleBridge.g.cs", CommandLifecycleBridgeEmitter.Emit(fluxorModel));
            }
        });
    }

private static bool HasActionQueueProjectionCatalogOverride(Compilation compilation) {
        const string interfaceMetadataName = "Hexalith.FrontComposer.Contracts.Badges.IActionQueueProjectionCatalog";
        const string defaultImplName = "ReflectionActionQueueProjectionCatalog";
        INamedTypeSymbol? interfaceSymbol = compilation.GetTypeByMetadataName(interfaceMetadataName);
        if (interfaceSymbol is null) {
            return true;
        }

        foreach (SyntaxTree tree in compilation.SyntaxTrees) {
            SemanticModel semanticModel = compilation.GetSemanticModel(tree);
            foreach (SyntaxNode node in tree.GetRoot().DescendantNodes()) {
                if (node is not TypeDeclarationSyntax typeDecl) {
                    continue;
                }

                if (semanticModel.GetDeclaredSymbol(typeDecl) is not INamedTypeSymbol typeSymbol) {
                    continue;
                }

                if (typeSymbol.IsAbstract || typeSymbol.TypeKind != TypeKind.Class) {
                    continue;
                }

                if (string.Equals(typeSymbol.Name, defaultImplName, StringComparison.Ordinal)) {
                    continue;
                }

                if (typeSymbol.AllInterfaces.Contains(interfaceSymbol, SymbolEqualityComparer.Default)) {
                    return true;
                }
            }
        }

        return false;
    }

public GeneratedSchemaFingerprint(string algorithmId, string value, string canonicalizerVersion, string testVectorId) {
        AlgorithmId = algorithmId;
        Value = value;
        CanonicalizerVersion = canonicalizerVersion;
        TestVectorId = testVectorId;
    }

public GeneratedSchemaPayload(string json, GeneratedSchemaFingerprint fingerprint) {
        Json = json;
        Fingerprint = fingerprint;
    }

private static readonly HashSet<string> RuntimeCorrelationFieldNames = new(StringComparer.OrdinalIgnoreCase) {
        "MessageId",
        "TenantId",
        "CorrelationId",
        "UserId",
        "Principal",
        "Claims",
        "Token",
    };

public static GeneratedSchemaPayload CreateLifecycleResultPayload()
        => Payload(
            "LifecycleResult",
            "frontcomposer.lifecycle.result",
            LifecycleResultSchemaVersion,
            "",
            "Hexalith.FrontComposer.Mcp.Invocation.McpLifecycleResult",
            "frontcomposer://lifecycle/result",
            CreateLifecycleFieldLines(),
            new Dictionary<string, string>(StringComparer.Ordinal) {
                ["compatibilityPolicy"] = "no-client-timestamps",
            });

private static IReadOnlyList<string> CreateLifecycleFieldLines()
        => [
            "Category|string|string|required|not-null",
            "CorrelationId|string|string|required|not-null",
            "MessageId|string|string|required|not-null",
            "State|string|string|required|not-null|Accepted,Confirmed,Failed,Rejected,Running",
        ];

private static GeneratedSchemaPayload Payload(
        string family,
        string contractId,
        string schemaVersion,
        string boundedContext,
        string fullyQualifiedName,
        string protocolIdentifier,
        IEnumerable<string> fields,
        IReadOnlyDictionary<string, string> metadata) {
        // P-1: every user-controlled scalar that crosses the canonical-blob delimiters
        // (`=`, `|`, `\n`) is escaped so an attacker- or user-controlled string (XML doc,
        // attribute Description, etc.) cannot synthesize a fake `metadata.X=...\n` line and
        // collide with a different schema. Backslash escapes are reversible: `\\` → `\`,
        // `\n` → newline, `\=` → equals, `\|` → pipe, `\:` → colon. Field lines pre-escape
        // their cells inside FieldLine; static identifiers (family/protocol/family-keys) are
        // author-controlled and do not require escaping.
        var sb = new StringBuilder(1024);
        _ = sb.Append("root=frontcomposer.schema.contract.v1\n");
        _ = sb.Append("family=").Append(EscapeDelimited(Normalize(family))).Append('\n');
        _ = sb.Append("contractId=").Append(EscapeDelimited(Normalize(contractId))).Append('\n');
        _ = sb.Append("schemaVersion=").Append(EscapeDelimited(Normalize(schemaVersion))).Append('\n');
        _ = sb.Append("boundedContext=").Append(EscapeDelimited(Normalize(boundedContext))).Append('\n');
        _ = sb.Append("fqn=").Append(EscapeDelimited(Normalize(fullyQualifiedName))).Append('\n');
        _ = sb.Append("protocol=").Append(EscapeDelimited(Normalize(protocolIdentifier))).Append('\n');
        _ = sb.Append("collections=fields:non-structural-sorted:name\n");
        foreach (string field in fields.OrderBy(f => f, StringComparer.Ordinal)) {
            // Field lines are pre-escaped per cell inside FieldLine (commands/resources); for
            // hand-authored static field strings (lifecycle/markdown/skill-corpus), the
            // surface here is author-controlled, so newline normalization is sufficient.
            _ = sb.Append("field=").Append(Normalize(field)).Append('\n');
        }

        foreach (KeyValuePair<string, string> pair in metadata.OrderBy(p => p.Key, StringComparer.Ordinal)) {
            _ = sb.Append("metadata.")
                .Append(EscapeDelimited(Normalize(pair.Key)))
                .Append('=')
                .Append(EscapeDelimited(Normalize(pair.Value)))
                .Append('\n');
        }

        string json = sb.ToString();
        return new GeneratedSchemaPayload(
            json,
            new GeneratedSchemaFingerprint(AlgorithmId, Sha256Hex(json), CanonicalizerVersion, TestVectorId));
    }

private static string FieldLine(McpParameterDescriptorModel parameter)
        // Pipe-delimited record. EscapeDelimited per cell prevents a `|` inside a parameter
        // name/description from synthesizing additional positional fields and colliding with
        // an unrelated parameter.
        => string.Join("|", [
            EscapeDelimited(parameter.Name),
            EscapeDelimited(parameter.TypeName),
            EscapeDelimited(parameter.JsonType),
            parameter.IsRequired ? "required" : "optional",
            parameter.IsNullable ? "nullable" : "not-null",
            EscapeDelimited(parameter.Title),
            EscapeDelimited(OptionalScalar(parameter.Description)),
            string.Join(",", parameter.EnumValues.OrderBy(v => v, StringComparer.Ordinal).Select(EscapeDelimited)),
            parameter.IsUnsupported ? "unsupported" : "supported",
            string.Join(",", parameter.BadgeMappings.OrderBy(p => p.Key, StringComparer.Ordinal).Select(p => EscapeDelimited(p.Key) + ":" + EscapeDelimited(p.Value))),
            EscapeDelimited(parameter.DisplayFormat),
        ]);

private static string Normalize(string value)
        // 8-6a chunk-3 review: AC11 EOL-invariance applies to LF, CRLF, CR, U+2028 LINE SEPARATOR,
        // and U+2029 PARAGRAPH SEPARATOR. Other Unicode line-break code points (U+0085 NEL, U+000B
        // VT, U+000C FF) are not normalized \u2014 sources do not produce them in practice (Roslyn
        // syntax trees + attribute string literals + XML doc comments), and AC11 determinism tests
        // do not parameterize over them. EscapeDelimited (`'\n'`/`'\u2028'`/`'\u2029'` -> `\\n`)
        // collapses any surviving in-cell line breaks to a literal escape so they cannot synthesize
        // a row split inside the canonical blob even when Normalize runs after cell escaping.
        => (value ?? string.Empty)
            .Replace("\r\n", "\n")
            .Replace('\r', '\n')
            .Replace('\u2028', '\n')
            .Replace('\u2029', '\n')
            .Trim();

private static string EscapeDelimited(string value) {
        if (string.IsNullOrEmpty(value)) {
            return string.Empty;
        }

        // Collapse CRLF to LF before per-char escape so the switch handles all line-break flavors
        // uniformly: a `\r\n` pair would otherwise emit `\\n\\n` (two escapes) where `\n` alone
        // emits `\\n` (one), breaking AC11 EOL-invariance for FieldLine cells.
        if (value.IndexOf('\r') >= 0) {
            value = value.Replace("\r\n", "\n");
        }

        var sb = new StringBuilder(value.Length);
        foreach (char c in value) {
            _ = c switch {
                '\\' => sb.Append("\\\\"),
                '=' => sb.Append("\\="),
                '|' => sb.Append("\\|"),
                ':' => sb.Append("\\:"),
                '\n' or '\r' or '\u2028' or '\u2029' => sb.Append("\\n"),
                _ => sb.Append(c),
            };
        }

        return sb.ToString();
    }

private static string Sha256Hex(string value) {
        using var sha = SHA256.Create();
        byte[] bytes = sha.ComputeHash(Encoding.UTF8.GetBytes(value));
        char[] chars = new char[bytes.Length * 2];
        const string Hex = "0123456789abcdef";
        for (int i = 0; i < bytes.Length; i++) {
            chars[i * 2] = Hex[bytes[i] >> 4];
            chars[(i * 2) + 1] = Hex[bytes[i] & 0xF];
        }

        return new string(chars);
    }

public static RegistrationModel Transform(DomainModel model) {
        // BoundedContext from attribute, or fallback to namespace last segment
        string boundedContext = model.BoundedContext
            ?? GetNamespaceLastSegment(model.Namespace);

        return new RegistrationModel(
            boundedContext,
            model.TypeName,
            model.Namespace,
            model.BoundedContextDisplayLabel);
    }

public static RegistrationModel TransformCommand(CommandModel model) {
        string boundedContext = string.IsNullOrEmpty(model.BoundedContext)
            ? "Default"
            : model.BoundedContext!;

        return new RegistrationModel(
            boundedContext,
            model.TypeName,
            model.Namespace,
            model.BoundedContextDisplayLabel,
            isCommand: true,
            authorizationPolicyName: model.AuthorizationPolicyName,
            hasFullPageRoute: model.Density == CommandDensity.FullPage);
    }

private static string GetNamespaceLastSegment(string @namespace) {
        if (string.IsNullOrEmpty(@namespace)) {
            return "Global";
        }

        int lastDot = @namespace.LastIndexOf('.');
        return lastDot >= 0 ? @namespace.Substring(lastDot + 1) : @namespace;
    }

public RegistrationModel(
        string boundedContext,
        string typeName,
        string @namespace,
        string? displayLabel,
        bool isCommand = false,
        string? authorizationPolicyName = null,
        bool hasFullPageRoute = false) {
        BoundedContext = boundedContext;
        TypeName = typeName;
        Namespace = @namespace;
        DisplayLabel = displayLabel;
        IsCommand = isCommand;
        AuthorizationPolicyName = authorizationPolicyName;
        HasFullPageRoute = hasFullPageRoute;
    }

public bool Equals(RegistrationModel? other) {
        if (other is null) {
            return false;
        }

        if (ReferenceEquals(this, other)) {
            return true;
        }

        return BoundedContext == other.BoundedContext
            && TypeName == other.TypeName
            && Namespace == other.Namespace
            && DisplayLabel == other.DisplayLabel
            && IsCommand == other.IsCommand
            && AuthorizationPolicyName == other.AuthorizationPolicyName
            && HasFullPageRoute == other.HasFullPageRoute;
    }

public override int GetHashCode() {
        unchecked {
            int hash = 17;
            hash = (hash * 31) + (BoundedContext?.GetHashCode() ?? 0);
            hash = (hash * 31) + (TypeName?.GetHashCode() ?? 0);
            hash = (hash * 31) + (Namespace?.GetHashCode() ?? 0);
            hash = (hash * 31) + (DisplayLabel?.GetHashCode() ?? 0);
            hash = (hash * 31) + IsCommand.GetHashCode();
            hash = (hash * 31) + (AuthorizationPolicyName?.GetHashCode() ?? 0);
            hash = (hash * 31) + HasFullPageRoute.GetHashCode();
            return hash;
        }
    }

public static RazorModel Transform(DomainModel model, List<DiagnosticInfo> diagnostics) {
        ImmutableArray<ColumnModel>.Builder columnsBuilder = ImmutableArray.CreateBuilder<ColumnModel>();

        foreach (PropertyModel property in model.Properties) {
            TypeCategory category = MapTypeCategory(property.TypeName);
            string? formatHint = GetFormatHint(property);
            string header = ResolveHeader(property);

            columnsBuilder.Add(new ColumnModel(
                property.Name,
                header,
                category,
                formatHint,
                property.IsNullable,
                property.BadgeMappings,
                property.EnumMemberNames,
                property.ColumnPriority,
                property.FieldGroup,
                property.Description,
                property.UnsupportedTypeFullyQualifiedName,
                property.DisplayFormat,
                property.RelativeTimeWindowDays));
        }

        // Story 4-4 T6.4 / D17 — stable sort by (Priority ?? int.MaxValue, DeclarationOrder)
        // ONLY when at least one column declares a non-null priority. NO-OP preserves the
        // pre-4-4 declaration-order baseline byte-for-byte (CounterProjectionApprovalTests gate).
        ImmutableArray<ColumnModel> columnsArray = columnsBuilder.ToImmutable();
        bool anyPriority = false;
        for (int i = 0; i < columnsArray.Length; i++) {
            if (columnsArray[i].Priority is not null) {
                anyPriority = true;
                break;
            }
        }

        if (anyPriority) {
            var buffer = new ColumnModel[columnsArray.Length];
            int[] declarationOrder = new int[columnsArray.Length];
            for (int i = 0; i < columnsArray.Length; i++) {
                buffer[i] = columnsArray[i];
                declarationOrder[i] = i;
            }

            // Array.Sort with IComparer<int> on the index array keeps the sort stable via the
            // original index — .NET's Array.Sort on a single array is NOT guaranteed stable,
            // so we sort indices.
            Array.Sort(declarationOrder, (left, right) => {
                int lp = buffer[left].Priority ?? int.MaxValue;
                int rp = buffer[right].Priority ?? int.MaxValue;
                int cmp = lp.CompareTo(rp);
                return cmp != 0 ? cmp : left.CompareTo(right);
            });

            ImmutableArray<ColumnModel>.Builder sortedBuilder = ImmutableArray.CreateBuilder<ColumnModel>(buffer.Length);
            for (int i = 0; i < declarationOrder.Length; i++) {
                sortedBuilder.Add(buffer[declarationOrder[i]]);
            }

            columnsArray = sortedBuilder.ToImmutable();
        }

        EquatableArray<ColumnModel> columns = new(columnsArray);
        ProjectionRenderStrategy strategy = MapStrategy(model, diagnostics);
        EquatableArray<string> whenStates = SplitWhenStates(model.ProjectionRoleWhenState);
        EmitFallbackDiagnostics(model, strategy, columns, whenStates, diagnostics);

        // Story 4-4 T6.4 / D15 — HFC1029 Information emit-stage when Columns.Count > 15
        // (strict > per D6 — exactly 15 does NOT trigger). Per-projection deduped via
        // IIncrementalGenerator's per-input invocation.
        if (columns.Count > 15) {
            List<string> hiddenByDefault = new(columns.Count - 10);
            for (int i = 10; i < columns.Count; i++) {
                hiddenByDefault.Add(columns[i].PropertyName);
            }

            diagnostics.Add(CreateTransformDiagnostic(
                model,
                "HFC1029",
                string.Format(
                    "Projection {0} has {1} columns (>15); FcColumnPrioritizer activates — {2} columns hidden by default: [{3}].",
                    model.TypeName,
                    columns.Count,
                    hiddenByDefault.Count,
                    string.Join(", ", hiddenByDefault)),
                "Info"));
        }
        string entityLabel = ResolveEntityLabel(model);
        string entityPluralLabel = ResolveEntityPluralLabel(model, entityLabel);

        return new RazorModel(
            model.TypeName,
            model.Namespace,
            model.BoundedContext,
            columns,
            strategy,
            whenStates,
            entityLabel,
            entityPluralLabel,
            model.EmptyStateCtaCommandTypeName);
    }

public static RazorModel Transform(DomainModel model) {
        List<DiagnosticInfo> scratch = [];
        return Transform(model, scratch);
    }

private static ProjectionRenderStrategy MapStrategy(DomainModel model, List<DiagnosticInfo> diagnostics) {
        string? role = model.ProjectionRole;

        ProjectionRenderStrategy strategy = role switch {
            null => ProjectionRenderStrategy.Default,
            "" => ProjectionRenderStrategy.Default,
            "ActionQueue" => ProjectionRenderStrategy.ActionQueue,
            "StatusOverview" => ProjectionRenderStrategy.StatusOverview,
            "DetailRecord" => ProjectionRenderStrategy.DetailRecord,
            "Timeline" => ProjectionRenderStrategy.Timeline,
            "Dashboard" => ProjectionRenderStrategy.Dashboard,
            _ => ProjectionRenderStrategy.Default,
        };

        if (strategy == ProjectionRenderStrategy.Dashboard) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1023",
                string.Format(
                    "Dashboard projection rendering is deferred to Story 6-3 - {0} falls back to Default DataGrid rendering in v1.",
                    model.TypeName),
                "Info",
                string.Empty,
                0,
                0));
        }

        return strategy;
    }

private static void EmitFallbackDiagnostics(
        DomainModel model,
        ProjectionRenderStrategy strategy,
        EquatableArray<ColumnModel> columns,
        EquatableArray<string> whenStates,
        List<DiagnosticInfo> diagnostics) {
        if (strategy == ProjectionRenderStrategy.ActionQueue
            && whenStates.Count > 0
            && ResolveStatusEnumColumn(columns) is null) {
            diagnostics.Add(CreateTransformDiagnostic(
                model,
                "HFC1022",
                string.Format(
                    "ProjectionRole.WhenState on {0} requires an enum status property - ActionQueue filtering falls back to the unfiltered item list at runtime.",
                    model.TypeName),
                "Warning"));
        }

        if (strategy == ProjectionRenderStrategy.Timeline
            && ResolveFirstDateTimeColumn(columns) is null) {
            diagnostics.Add(CreateTransformDiagnostic(
                model,
                "HFC1022",
                string.Format(
                    "ProjectionRole Timeline on {0} requires a DateTime/DateTimeOffset/DateOnly/TimeOnly property - timeline ordering falls back to declaration order.",
                    model.TypeName),
                "Warning"));
        }

        // Story 4-2 D6 / AC3 — emit HFC1025 once per enum column that carries partial
        // [ProjectionBadge] coverage on the projection. One diagnostic per (projection,
        // column) pair; the IIncrementalGenerator per-type invocation model provides the
        // "once per projection type per compile" guarantee natively.
        foreach (ColumnModel column in columns) {
            if (column.TypeCategory != TypeCategory.Enum) {
                continue;
            }

            int annotated = column.BadgeMappings.Count;
            int total = column.EnumMemberNames.Count;
            if (annotated == 0 || total == 0 || annotated >= total) {
                continue;
            }

            List<string> unannotated = new(total - annotated);
            HashSet<string> annotatedNames = new(StringComparer.Ordinal);
            foreach (BadgeMappingEntry mapping in column.BadgeMappings) {
                _ = annotatedNames.Add(mapping.EnumMemberName);
            }

            foreach (string memberName in column.EnumMemberNames) {
                if (!annotatedNames.Contains(memberName)) {
                    unannotated.Add(memberName);
                }
            }

            diagnostics.Add(CreateTransformDiagnostic(
                model,
                "HFC1025",
                string.Format(
                    "Enum property '{0}' on projection {1} has {2} of {3} members annotated with [ProjectionBadge] - unannotated members ({4}) render as plain text. Annotate every member or none for visual consistency.",
                    column.PropertyName,
                    model.TypeName,
                    annotated,
                    total,
                    string.Join(", ", unannotated)),
                "Info"));
        }

        // Story 4-3 D14 / D20 — emit HFC1027 once per projection type when it carries any
        // Collection-typed column. Per-projection deduped (one entry regardless of how many
        // Collection columns the projection declares).
        List<string>? collectionColumnNames = null;
        foreach (ColumnModel column in columns) {
            if (column.TypeCategory == TypeCategory.Collection) {
                (collectionColumnNames ??= []).Add(column.PropertyName);
            }
        }

        if (collectionColumnNames is not null) {
            diagnostics.Add(CreateTransformDiagnostic(
                model,
                "HFC1027",
                string.Format(
                    "Projection {0} has collection column(s) {1} which do not support automatic filtering. Filter affordance is omitted. Annotate with a slot-level override (Epic 6) for custom filter logic.",
                    model.TypeName,
                    string.Join(", ", collectionColumnNames)),
                "Info"));
        }

        // Story 4-5 T6.3 / D17 — emit HFC1031 once per projection whose role is Timeline AND
        // declares any [ProjectionFieldGroup] annotation. Timeline has no detail surface, so
        // the grouping is silently unused. Per-projection deduped.
        if (strategy == ProjectionRenderStrategy.Timeline) {
            int ignoredGroupCount = 0;
            foreach (ColumnModel column in columns) {
                if (column.FieldGroup is not null) {
                    ignoredGroupCount++;
                }
            }

            if (ignoredGroupCount > 0) {
                diagnostics.Add(CreateTransformDiagnostic(
                    model,
                    "HFC1031",
                    string.Format(
                        "[ProjectionFieldGroup] on {0} is ignored because the projection role is Timeline (no detail surface). {1} group annotation(s) have no effect; remove them or change the role to Default / DetailRecord / ActionQueue / StatusOverview / Dashboard to surface the grouped detail body.",
                        model.TypeName,
                        ignoredGroupCount),
                    "Info"));
            }
        }
    }

private static EquatableArray<string> SplitWhenStates(string? raw) {
        if (string.IsNullOrWhiteSpace(raw)) {
            return new EquatableArray<string>(ImmutableArray<string>.Empty);
        }

        string[] tokens = raw!.Split(WhenStateSeparator, StringSplitOptions.RemoveEmptyEntries);
        ImmutableArray<string>.Builder builder = ImmutableArray.CreateBuilder<string>();
        foreach (string token in tokens) {
            string trimmed = token.Trim();
            if (trimmed.Length > 0) {
                builder.Add(trimmed);
            }
        }

        return new EquatableArray<string>(builder.ToImmutable());
    }

private static TypeCategory MapTypeCategory(string typeName) => typeName switch {
        "String" or "Guid" => TypeCategory.Text,
        "Int32" or "Int64" or "Decimal" or "Double" or "Single" => TypeCategory.Numeric,
        "Boolean" => TypeCategory.Boolean,
        "DateTime" or "DateTimeOffset" or "DateOnly" or "TimeOnly" => TypeCategory.DateTime,
        "Enum" => TypeCategory.Enum,
        "Collection" => TypeCategory.Collection,
        _ => TypeCategory.Unsupported,
    };

private static string? GetFormatHint(PropertyModel property) {
        if (property.DisplayFormat == FieldDisplayFormat.Currency) {
            return "C";
        }

        if (property.DisplayFormat == FieldDisplayFormat.RelativeTime) {
            return "RelativeTime";
        }

        return property.TypeName switch {
            "Int32" or "Int64" => "N0",
            "Decimal" or "Double" or "Single" => "N2",
            "Boolean" => "Yes/No",
            "DateTime" or "DateTimeOffset" or "DateOnly" => "d",
            "TimeOnly" => "t",
            "Enum" => "Humanize:30",
            "Guid" => "Truncate:8",
            "Collection" => "Count",
            _ => null,
        };
    }

private static string ResolveHeader(PropertyModel property) {
        // Priority 1: [Display(Name)] attribute value
        if (!string.IsNullOrEmpty(property.DisplayName)) {
            return property.DisplayName!;
        }

        // Priority 2: Humanized CamelCase
        string? humanized = CamelCaseHumanizer.Humanize(property.Name);
        if (!string.IsNullOrEmpty(humanized)) {
            return humanized!;
        }

        // Priority 3: Raw property name (fallback)
        return property.Name;
    }

private static string ResolveEntityLabel(DomainModel model) {
        if (!string.IsNullOrWhiteSpace(model.DisplayName)) {
            return model.DisplayName!;
        }

        string baseName = StripProjectionSuffix(model.TypeName);
        string? humanized = CamelCaseHumanizer.Humanize(baseName);
        return string.IsNullOrWhiteSpace(humanized) ? baseName : humanized!;
    }

private static string ResolveEntityPluralLabel(DomainModel model, string entityLabel) {
        if (!string.IsNullOrWhiteSpace(model.DisplayGroupName)) {
            return model.DisplayGroupName!;
        }

        string plural = entityLabel.ToLowerInvariant();
        return plural.EndsWith("s", StringComparison.Ordinal) ? plural : plural + "s";
    }

private static string StripProjectionSuffix(string typeName)
        => typeName.EndsWith("Projection", StringComparison.Ordinal)
            ? typeName.Substring(0, typeName.Length - "Projection".Length)
            : typeName;

private static ColumnModel? ResolveStatusEnumColumn(EquatableArray<ColumnModel> columns) {
        ColumnModel? badgedEnum = null;
        ColumnModel? firstEnum = null;

        foreach (ColumnModel column in columns) {
            if (column.TypeCategory != TypeCategory.Enum) {
                continue;
            }

            firstEnum ??= column;
            if (badgedEnum is null && column.BadgeMappings.Count > 0) {
                badgedEnum = column;
            }
        }

        return badgedEnum ?? firstEnum;
    }

private static ColumnModel? ResolveFirstDateTimeColumn(EquatableArray<ColumnModel> columns) {
        foreach (ColumnModel column in columns) {
            if (column.TypeCategory == TypeCategory.DateTime) {
                return column;
            }
        }

        return null;
    }

