        ChangeKind = changeKind;
        ViewKey = viewKey;
        ExpectedStatus = expectedStatus;
    }

public override int GetHashCode() {
        unchecked {
            int hash = 17;
            hash = (hash * 31) + ProjectionFullyQualifiedName.GetHashCode();
            hash = (hash * 31) + (ProjectionViewKey?.GetHashCode() ?? 0);
            hash = (hash * 31) + ResolutionMode.GetHashCode();
            hash = (hash * 31) + ChangeKind.GetHashCode();
            hash = (hash * 31) + (ViewKey?.GetHashCode() ?? 0);
            hash = (hash * 31) + (ExpectedStatus?.GetHashCode() ?? 0);
            return hash;
        }
    }

private static readonly HashSet<string> WellKnownDerivablePropertyNames = new(StringComparer.Ordinal) {
        "MessageId",
        "CommandId",
        "CorrelationId",
        "TenantId",
        "UserId",
        "Timestamp",
        "CreatedAt",
        "ModifiedAt",
    };

private static readonly System.Text.RegularExpressions.Regex DestructiveNamePattern =
        new(
            @"^(Delete|Remove|Purge|Erase|Drop|Truncate|Wipe)(?:[A-Z]|Command$)",
            System.Text.RegularExpressions.RegexOptions.CultureInvariant | System.Text.RegularExpressions.RegexOptions.Compiled);

public static CommandParseResult Parse(GeneratorAttributeSyntaxContext context, CancellationToken ct) {
        if (context.TargetSymbol is not INamedTypeSymbol typeSymbol) {
            return EmptyResult;
        }

        return Parse(typeSymbol, context.TargetNode, context.SemanticModel.Compilation, ct);
    }

public static CommandParseResult Parse(
        INamedTypeSymbol typeSymbol,
        SyntaxNode targetNode,
        Compilation compilation,
        CancellationToken ct) {
        if (ct.IsCancellationRequested) {
            return EmptyResult;
        }

        List<DiagnosticInfo> diagnostics = [];
        string filePath = targetNode.SyntaxTree.FilePath ?? string.Empty;
        Microsoft.CodeAnalysis.Text.LinePosition linePos = targetNode.GetLocation().GetLineSpan().StartLinePosition;

        ValidateTypeKind(typeSymbol, targetNode, diagnostics, filePath, linePos);

        // HFC1014: nested [Command] types are unsupported (Story 2-2 Task 1.3b). A command's ContainingSymbol
        // must be a namespace, not a class/struct/record. Emit early and halt parsing — nested generation would
        // break the route-emission invariant {namespace.{CommandTypeName}Page} if the class lived inside another.
        if (typeSymbol.ContainingType is not null) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1014",
                string.Format(
                    "[Command] type '{0}' is nested inside '{1}'. Command types must be top-level within a namespace.",
                    typeSymbol.Name,
                    typeSymbol.ContainingType.ToDisplayString()),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));

            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        // HFC1017 (Story 2-3 Hindsight H9): generic [Command] types are unsupported. The per-command
        // lifecycle bridge emits one hint per command type; a generic command would collide on hint-name
        // across specialisations and cannot be uniformly subscribed via IActionSubscriber.SubscribeToAction<T>.
        if (typeSymbol.IsGenericType && typeSymbol.TypeParameters.Length > 0) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1017",
                string.Format(
                    "[Command] type '{0}' is generic (arity {1}). Command types must not be generic; specialize or remove the type parameters.",
                    typeSymbol.Name,
                    typeSymbol.TypeParameters.Length),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));

            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        if (ct.IsCancellationRequested) {
            return EmptyResult;
        }

        // HFC1009: emitted form body uses `_model = new()`; commands without a public parameterless
        // ctor (positional records, classes with only parameterised ctors) would generate uncompilable
        // code. Surface a build error so the adopter fixes the command shape. (Patch P1.)
        if (!HasPublicParameterlessConstructor(typeSymbol)) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1009",
                string.Format(
                    "[Command] type '{0}' has no public parameterless constructor. The generated form requires 'new {0}()' to build the form model. Add a parameterless constructor, or give every positional parameter a default value.",
                    typeSymbol.Name),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));

            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        string typeName = typeSymbol.Name;
        string ns = typeSymbol.ContainingNamespace?.IsGlobalNamespace == true
            ? string.Empty
            : typeSymbol.ContainingNamespace?.ToDisplayString() ?? string.Empty;

        string? boundedContext = ParseBoundedContext(typeSymbol, out string? boundedContextDisplayLabel);
        string? displayName = ParseDisplayAttribute(typeSymbol);
        string? iconName = ParseIconAttribute(typeSymbol);
        string? authorizationPolicyName = ParseRequiresPolicyAttribute(typeSymbol, diagnostics, filePath, linePos);
        CommandTargetModel? commandTarget = ParseCommandTarget(typeSymbol, diagnostics, filePath, linePos);
        if (diagnostics.Any(d => d.Id is "HFC1056" or "HFC1057")) {
            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        // Story 2-5 Task 2.2 — parse [Destructive] opt-in marker + optional confirmation copy overrides.
        bool isDestructive = ParseDestructiveAttribute(
            typeSymbol,
            out string? destructiveConfirmTitle,
            out string? destructiveConfirmBody);

        // Story 2-5 D20 / HFC1020 (Info) — name-heuristic guardrail: command matches destructive verb pattern
        // but lacks [Destructive]. Info severity in v0.1 to prevent Day-1 adoption blockers (promotion to
        // Warning + [SuppressHFC1020] ship in Story 9-4).
        if (!isDestructive && DestructiveNamePattern.IsMatch(typeSymbol.Name)) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1020",
                string.Format(
                    "Command '{0}' appears destructive by name but is missing [Destructive] attribute. Add [Destructive] or rename the command.",
                    typeSymbol.Name),
                "Info",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        if (ct.IsCancellationRequested) {
            return EmptyResult;
        }

        // Collect public, non-static, non-indexer properties, including inherited ones (e.g., MessageId on a base record).
        ImmutableArray<PropertyModel>.Builder allBuilder = ImmutableArray.CreateBuilder<PropertyModel>();
        ImmutableArray<PropertyModel>.Builder derivableBuilder = ImmutableArray.CreateBuilder<PropertyModel>();
        ImmutableArray<PropertyModel>.Builder nonDerivableBuilder = ImmutableArray.CreateBuilder<PropertyModel>();

        // Case-insensitive dedup + MessageId lookup (patch 2026-04-16 P-02): a property named
        // `messageId` satisfies the runtime MessageId contract, so HFC1006 must not fire on casing alone.
        HashSet<string> seenNames = new(StringComparer.Ordinal);
        List<IPropertySymbol> assignmentTargetSymbols = [];
        INamedTypeSymbol? currentType = typeSymbol;
        while (currentType is not null && currentType.SpecialType != SpecialType.System_Object) {
            foreach (ISymbol member in currentType.GetMembers()) {
                if (ct.IsCancellationRequested) {
                    return EmptyResult;
                }

                if (member is not IPropertySymbol propertySymbol
                    || propertySymbol.DeclaredAccessibility != Accessibility.Public
                    || propertySymbol.IsStatic
                    || propertySymbol.IsIndexer) {
                    continue;
                }

                // Skip record synthetic EqualityContract property.
                if (propertySymbol.Name == "EqualityContract") {
                    continue;
                }

                // Inherited override: keep the most-derived declaration only.
                if (!seenNames.Add(propertySymbol.Name)) {
                    continue;
                }

                PropertyModel property = AttributeParser.ParsePropertyForCommand(
                    propertySymbol,
                    typeName,
                    diagnostics,
                    filePath,
                    compilation);
                ValidateDefaultValueType(propertySymbol, diagnostics, filePath);
                allBuilder.Add(property);
                assignmentTargetSymbols.Add(propertySymbol);

                bool isDerivable = IsDerivableProperty(propertySymbol);
                if (isDerivable) {
                    derivableBuilder.Add(property);
                }
                else {
                    nonDerivableBuilder.Add(property);
                }
            }

            currentType = currentType.BaseType;
        }

        // Check MessageId presence (HFC1006). Also walk AllInterfaces so an interface-declared
        // `MessageId` (potentially with a default implementation) satisfies the contract (patch 2026-04-16 P-03).
        bool hasMessageId = seenNames.Contains("MessageId");
        if (!hasMessageId) {
            foreach (INamedTypeSymbol iface in typeSymbol.AllInterfaces) {
                foreach (ISymbol interfaceMember in iface.GetMembers("MessageId")) {
                    if (interfaceMember is IPropertySymbol { IsStatic: false, IsIndexer: false }) {
                        hasMessageId = true;
                        break;
                    }
                }

                if (hasMessageId) {
                    break;
                }
            }
        }

        if (!hasMessageId) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1006",
                string.Format("[Command] type '{0}' is missing a 'MessageId' property. Add a string MessageId property (or inherit from a base record that provides it) so commands can be correlated end-to-end.", typeName),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        // HFC1016: every generated assignment target follows one uniform command-shape policy.
        // This includes derivable properties, even when their type requires a type-free soft-fail
        // renderer arm, so a command cannot move between assignment paths with an incompatible setter.
        bool hasInvalidAssignmentTarget = false;
        foreach (IPropertySymbol prop in assignmentTargetSymbols) {
            IMethodSymbol? setter = prop.SetMethod;
            bool isWritable = setter is { DeclaredAccessibility: Accessibility.Public, IsInitOnly: false };
            if (!isWritable) {
                hasInvalidAssignmentTarget = true;
                string kind = setter is null
                    ? "has no public setter"
                    : setter.IsInitOnly
                        ? "is declared with an 'init' accessor"
                        : "has a non-public setter";
                Location? sourceLocation = prop.Locations.FirstOrDefault(static location => location.IsInSource);
                Microsoft.CodeAnalysis.Text.LinePosition diagnosticLine = sourceLocation is null
                    ? linePos
                    : sourceLocation.GetLineSpan().StartLinePosition;
                string diagnosticFilePath = sourceLocation?.SourceTree?.FilePath ?? filePath;

                diagnostics.Add(new DiagnosticInfo(
                    "HFC1016",
                    string.Format(
                        "[Command] type '{0}' property '{1}' {2}. FrontComposer command generation requires every command property to declare a public non-init setter. Change the property to '{{ get; set; }}'.",
                        typeName,
                        prop.Name,
                        kind),
                    "Error",
                    diagnosticFilePath,
                    diagnosticLine.Line,
                    diagnosticLine.Character));
            }
        }

        // HFC1011: hard error when total (derivable + non-derivable) public property count exceeds 200 — Story 2-2 Task 1.3a, Red-team RT-5.
        int totalCount = allBuilder.Count;
        if (totalCount > TotalPropertyHardLimit) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1011",
                string.Format(
                    "[Command] type '{0}' has {1} total public properties, exceeding the hard limit of {2}. Split the command into smaller aggregates.",
                    typeName,
                    totalCount,
                    TotalPropertyHardLimit),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        int nonDerivableCount = nonDerivableBuilder.Count;

        // Story 2-5 D1 / AC4 / HFC1021 — [Destructive] commands must have at least one non-derivable field
        // so the emitted renderer can open the destructive confirmation dialog (destructive never renders as
        // 0-field Inline button per UX-DR36).
        if (isDestructive && nonDerivableCount == 0) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1021",
                string.Format(
                    "Destructive command '{0}' must have at least one non-derivable property (destructive commands cannot render as inline buttons).",
                    typeName),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));

            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        if (nonDerivableCount > NonDerivableErrorThreshold) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1007",
                string.Format("[Command] type '{0}' has {1} non-derivable properties, exceeding the hard limit of {2}. Split the command into smaller aggregates.", typeName, nonDerivableCount, NonDerivableErrorThreshold),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));
        }
        else if (nonDerivableCount > NonDerivableWarningThreshold) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1007",
                string.Format("[Command] type '{0}' has {1} non-derivable properties, above the recommended limit of {2}. Consider splitting the command for better form ergonomics.", typeName, nonDerivableCount, NonDerivableWarningThreshold),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        if (hasInvalidAssignmentTarget) {
            return new CommandParseResult(null, new EquatableArray<DiagnosticInfo>([.. diagnostics]));
        }

        var model = new CommandModel(
            typeName,
            ns,
            boundedContext,
            boundedContextDisplayLabel,
            displayName,
            new EquatableArray<PropertyModel>(allBuilder.ToImmutable()),
            new EquatableArray<PropertyModel>(derivableBuilder.ToImmutable()),
            new EquatableArray<PropertyModel>(nonDerivableBuilder.ToImmutable()),
            iconName,
            isDestructive,
            destructiveConfirmTitle,
            destructiveConfirmBody,
            authorizationPolicyName,
            filePath,
            linePos.Line,
            linePos.Character,
            commandTarget);

        return new CommandParseResult(
            model,
            new EquatableArray<DiagnosticInfo>(diagnostics.ToImmutableArray()));
    }

private static CommandTargetModel? ParseCommandTarget(
        INamedTypeSymbol typeSymbol,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        AttributeData? attribute = typeSymbol.GetAttributes().FirstOrDefault(
            candidate => candidate.AttributeClass?.ToDisplayString() == CommandTargetAttributeName);
        if (attribute is null) {
            return null;
        }

        if (attribute.ConstructorArguments.Length != 3
            || attribute.ConstructorArguments[0].Value is not INamedTypeSymbol projectionType
            || attribute.ConstructorArguments[1].Value is not int resolutionValue
            || attribute.ConstructorArguments[2].Value is not int changeValue
            || !Enum.IsDefined(typeof(CommandTargetResolutionMode), resolutionValue)
            || !Enum.IsDefined(typeof(CommandTargetChangeKind), changeValue)
            || !projectionType.GetAttributes().Any(
                candidate => candidate.AttributeClass?.ToDisplayString() == ProjectionAttributeName)) {
            AddInvalidCommandTargetDiagnostic(typeSymbol, diagnostics, filePath, linePos);
            return null;
        }

        var resolutionMode = (CommandTargetResolutionMode)resolutionValue;
        var changeKind = (CommandTargetChangeKind)changeValue;
        if (resolutionMode == CommandTargetResolutionMode.SameAsSource
            && changeKind != CommandTargetChangeKind.Update) {
            AddInvalidCommandTargetDiagnostic(typeSymbol, diagnostics, filePath, linePos);
            return null;
        }

        string? viewKey = NormalizeNamedString(attribute, nameof(CommandTargetAttribute.ViewKey));
        string? expectedStatus = NormalizeNamedString(attribute, nameof(CommandTargetAttribute.ExpectedStatus));
        string projectionViewKey = ResolveProjectionViewKey(projectionType);
        if (viewKey is not null
            && !string.Equals(viewKey, projectionViewKey, StringComparison.Ordinal)) {
            AddInvalidCommandTargetDiagnostic(typeSymbol, diagnostics, filePath, linePos);
            return null;
        }

        return new CommandTargetModel(
            projectionType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat),
            resolutionMode,
            changeKind,
            viewKey,
            expectedStatus,
            projectionViewKey);
    }

private static string ResolveProjectionViewKey(INamedTypeSymbol projectionType) {
        string projectionName = projectionType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
        const string GlobalPrefix = "global::";
        if (projectionName.StartsWith(GlobalPrefix, StringComparison.Ordinal)) {
            projectionName = projectionName.Substring(GlobalPrefix.Length);
        }

        string? boundedContext = ParseBoundedContext(projectionType, out _);
        string namespaceName = projectionType.ContainingNamespace?.IsGlobalNamespace == false
            ? projectionType.ContainingNamespace.ToDisplayString()
            : string.Empty;
        return (boundedContext ?? namespaceName) + ":" + projectionName;
    }

private static string? NormalizeNamedString(AttributeData attribute, string name) {
        foreach (KeyValuePair<string, TypedConstant> argument in attribute.NamedArguments) {
            if (argument.Key == name && argument.Value.Value is string value) {
                return string.IsNullOrWhiteSpace(value) ? null : value.Trim();
            }
        }

        return null;
    }

private static bool HasPublicParameterlessConstructor(INamedTypeSymbol typeSymbol) {
        foreach (IMethodSymbol ctor in typeSymbol.InstanceConstructors) {
            if (ctor.DeclaredAccessibility != Accessibility.Public) {
                continue;
            }

            if (ctor.Parameters.Length == 0) {
                return true;
            }

            // A ctor whose parameters all have default values (including positional record
            // primary ctors like `record Foo(string A = "", int B = 0)`) is callable as `new Foo()`.
            bool allOptional = true;
            foreach (IParameterSymbol parameter in ctor.Parameters) {
                if (!parameter.HasExplicitDefaultValue) {
                    allOptional = false;
                    break;
                }
            }

            if (allOptional) {
                return true;
            }
        }

        return false;
    }

private static bool IsDerivableProperty(IPropertySymbol propertySymbol) {
        // Walk the property's inheritance chain (override / shadow / base positional params):
        // attributes placed on a base declaration must still be discoverable when a derived
        // record shadows the property (see code-review 2026-04-15, patch P15).
        IPropertySymbol? current = propertySymbol;
        while (current is not null) {
            foreach (AttributeData attr in current.GetAttributes()) {
                if (attr.AttributeClass?.ToDisplayString() == DerivedFromAttributeName) {
                    return true;
                }
            }

            current = current.OverriddenProperty ?? FindShadowedProperty(current);
        }

        return WellKnownDerivablePropertyNames.Contains(propertySymbol.Name);
    }

private static IPropertySymbol? FindShadowedProperty(IPropertySymbol propertySymbol) {
        INamedTypeSymbol? baseType = propertySymbol.ContainingType?.BaseType;
        while (baseType is not null && baseType.SpecialType != SpecialType.System_Object) {
            foreach (ISymbol member in baseType.GetMembers(propertySymbol.Name)) {
                if (member is IPropertySymbol basePropertySymbol
                    && basePropertySymbol.DeclaredAccessibility == Accessibility.Public
                    && !basePropertySymbol.IsStatic
                    && !basePropertySymbol.IsIndexer) {
                    return basePropertySymbol;
                }
            }

            baseType = baseType.BaseType;
        }

        return null;
    }

private static void ValidateTypeKind(
        INamedTypeSymbol typeSymbol,
        SyntaxNode targetNode,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        if (typeSymbol.TypeKind == TypeKind.Struct) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Command] attribute on '{0}' is not supported: structs are not supported. Only non-abstract, non-generic classes and records are supported.", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        if (typeSymbol.IsAbstract) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Command] attribute on '{0}' is not supported: abstract types are not supported.", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        if (typeSymbol.IsGenericType) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Command] attribute on '{0}' is not supported: generic types are not supported.", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        if (typeSymbol.ContainingNamespace?.ToDisplayString().StartsWith("System", StringComparison.Ordinal) == true) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Command] attribute on '{0}' is not supported: command types must not live in the 'System' namespace.", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }
    }

private static string? ParseBoundedContext(INamedTypeSymbol typeSymbol, out string? displayLabel) {
        displayLabel = null;
        INamedTypeSymbol? current = typeSymbol;
        while (current is not null) {
            foreach (AttributeData attr in current.GetAttributes()) {
                if (attr.AttributeClass?.ToDisplayString() == BoundedContextAttributeName) {
                    foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                        if (namedArg.Key == "DisplayLabel"
                            && namedArg.Value.Value is string label
                            && !string.IsNullOrWhiteSpace(label)) {
                            displayLabel = label;
                        }
                    }

                    if (attr.ConstructorArguments.Length > 0
                        && attr.ConstructorArguments[0].Value is string name
                        && !string.IsNullOrWhiteSpace(name)) {
                        return name.Trim();
                    }

                    return null;
                }
            }

            current = current.ContainingType;
        }

        return null;
    }

private static string? ParseDisplayAttribute(INamedTypeSymbol typeSymbol) {
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == DisplayAttributeName) {
                foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                    if (namedArg.Key == "Name" && namedArg.Value.Value is string name) {
                        return name;
                    }
                }
            }
        }

        return null;
    }

private static string? ParseRequiresPolicyAttribute(
        INamedTypeSymbol typeSymbol,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        List<AttributeData> attributes = [];
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == RequiresPolicyAttributeName) {
                attributes.Add(attr);
            }
        }

        if (attributes.Count == 0) {
            return null;
        }

        if (attributes.Count > 1) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1057",
                string.Format(
                    "Command '{0}' declares [RequiresPolicy] more than once. Expected at most one policy per command in v1.",
                    typeSymbol.Name),
                "Error",
                filePath,
                linePos.Line,
                linePos.Character));
            return null;
        }

        AttributeData policyAttribute = attributes[0];
        string? value = null;
        if (policyAttribute.ConstructorArguments.Length > 0) {
            TypedConstant ctorArg = policyAttribute.ConstructorArguments[0];
            // Defensive: typeof(...) / array constants surface as non-Primitive Kinds. The cast to
            // string then yields null and would silently drop policy metadata. Reject as HFC1056.
            if (ctorArg.Kind == TypedConstantKind.Primitive) {
                value = ctorArg.Value as string;
            }
        }

        if (string.IsNullOrWhiteSpace(value) || !IsPolicyNameWellFormed(value!)) {
            Microsoft.CodeAnalysis.Text.LinePosition attrLine = (policyAttribute.ApplicationSyntaxReference?.GetSyntax() as AttributeSyntax)
                ?.GetLocation()
                .GetLineSpan()
                .StartLinePosition ?? linePos;

            // Pass 3 — echo the (escaped, truncated) offending value so authors can see WHICH character
            // failed without having to count chars in the source. Keeps message length bounded.
            string offending = FormatOffendingPolicyValue(value);
            diagnostics.Add(new DiagnosticInfo(
                "HFC1056",
                string.Format(
                    "Command '{0}' has an invalid [RequiresPolicy] value. Expected a non-empty policy name using letters, digits, '.', ':', '_', or '-' with at least one alphanumeric character. Got: {1}",
                    typeSymbol.Name,
                    offending),
                "Error",
                filePath,
                attrLine.Line,
                attrLine.Character));
            return null;
        }

        return value!.Trim();
    }

private static bool IsPolicyNameWellFormed(string value) {
        string trimmed = value.Trim();
        if (trimmed.Length == 0) {
            return false;
        }

        bool hasAlphanumeric = false;
        foreach (char c in trimmed) {
            if (char.IsLetterOrDigit(c)) {
                hasAlphanumeric = true;
                continue;
            }

            if (c is not ('.' or ':' or '_' or '-')) {
                return false;
            }
        }

        // Pass 3 — punctuation-only names like "-", ".", ":", or "::" pass the per-character check
        // but produce no meaningful policy lookup. Mirror RequiresPolicyAttribute.IsWellFormed.
        return hasAlphanumeric;
    }

private static string FormatOffendingPolicyValue(string? raw) {
        if (raw is null) {
            return "<null>";
        }

        const int MaxEcho = 64;
        string truncated = raw.Length > MaxEcho ? raw.Substring(0, MaxEcho) + "..." : raw;

        // Escape control characters so log readers see "\\t" / "\\n" rather than embedded whitespace.
        var sb = new System.Text.StringBuilder(truncated.Length + 2);
        _ = sb.Append('\'');
        foreach (char c in truncated) {
            switch (c) {
                case '\t': _ = sb.Append("\\t"); break;
                case '\r': _ = sb.Append("\\r"); break;
                case '\n': _ = sb.Append("\\n"); break;
                case '\\': _ = sb.Append("\\\\"); break;
                default:
                    if (char.IsControl(c)) {
                        _ = sb.Append("\\u").Append(((int)c).ToString("X4", System.Globalization.CultureInfo.InvariantCulture));
                    }
                    else {
                        _ = sb.Append(c);
                    }

                    break;
            }
        }

        _ = sb.Append('\'');
        return sb.ToString();
    }

private static bool ParseDestructiveAttribute(
        INamedTypeSymbol typeSymbol,
        out string? confirmationTitle,
        out string? confirmationBody) {
        confirmationTitle = null;
        confirmationBody = null;

        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() != DestructiveAttributeName) {
                continue;
            }

            foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                if (namedArg.Key == "ConfirmationTitle"
                    && namedArg.Value.Value is string title
                    && !string.IsNullOrWhiteSpace(title)) {
                    confirmationTitle = title;
                }
                else if (namedArg.Key == "ConfirmationBody"
                    && namedArg.Value.Value is string body
                    && !string.IsNullOrWhiteSpace(body)) {
                    confirmationBody = body;
                }
            }

            return true;
        }

        return false;
    }

private static string? ParseIconAttribute(INamedTypeSymbol typeSymbol) {
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == IconAttributeName
                && attr.ConstructorArguments.Length > 0
                && attr.ConstructorArguments[0].Value is string iconName
                && !string.IsNullOrWhiteSpace(iconName)) {
                return iconName;
            }
        }

        return null;
    }

private static void ValidateDefaultValueType(IPropertySymbol propertySymbol, List<DiagnosticInfo> diagnostics, string filePath) {
        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() != DefaultValueAttributeName) {
                continue;
            }

            if (attr.ConstructorArguments.Length == 0) {
                continue;
            }

            ITypeSymbol propertyType = propertySymbol.Type;
            // Unwrap Nullable<T> for comparison.
            if (propertyType is INamedTypeSymbol named && named.IsGenericType && named.ConstructedFrom.SpecialType == SpecialType.System_Nullable_T) {
                propertyType = named.TypeArguments[0];
            }

            bool assignable;
            string actualTypeDisplay;
            if (attr.AttributeConstructor?.Parameters is { Length: 2 } parameters
                && parameters[0].Type.ToDisplayString() == "System.Type"
                && parameters[1].Type.SpecialType == SpecialType.System_String
                && attr.ConstructorArguments[0].Value is ITypeSymbol declaredDefaultType) {
                assignable = IsDefaultValueTypeAssignable(declaredDefaultType, propertyType);
                actualTypeDisplay = declaredDefaultType.ToDisplayString();
            }
            else {
                TypedConstant arg = attr.ConstructorArguments[0];

                // Null is always assignable (reference / nullable types); skip the check.
                if (arg.IsNull) {
                    continue;
                }

                ITypeSymbol? argType = arg.Type;
                if (argType is null) {
                    continue;
                }

                assignable = IsDefaultValueTypeAssignable(argType, propertyType);
                actualTypeDisplay = argType.ToDisplayString();
            }

            if (!assignable) {
                var attrSyntax = attr.ApplicationSyntaxReference?.GetSyntax() as AttributeSyntax;
                Microsoft.CodeAnalysis.Text.LinePosition linePos = attrSyntax?.GetLocation().GetLineSpan().StartLinePosition ?? default;
                diagnostics.Add(new DiagnosticInfo(
                    "HFC1012",
                    string.Format(
                        "Property '{0}.{1}' has [DefaultValue] of type '{2}' which is not assignable to the property type '{3}'.",
                        propertySymbol.ContainingType?.Name ?? "?",
                        propertySymbol.Name,
                        actualTypeDisplay,
                        propertySymbol.Type.ToDisplayString()),
                    "Error",
                    filePath,
                    linePos.Line,
                    linePos.Character));
            }
        }
    }

private static bool IsDefaultValueTypeAssignable(ITypeSymbol candidateType, ITypeSymbol propertyType) {
        if (SymbolEqualityComparer.Default.Equals(candidateType, propertyType)) {
            return true;
        }

        SpecialType from = candidateType.SpecialType;
        SpecialType to = propertyType.SpecialType;
        return (from, to) switch {
            (SpecialType.System_SByte, SpecialType.System_Int16 or SpecialType.System_Int32 or SpecialType.System_Int64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Byte, SpecialType.System_Int16 or SpecialType.System_UInt16 or SpecialType.System_Int32 or SpecialType.System_UInt32
                or SpecialType.System_Int64 or SpecialType.System_UInt64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Int16, SpecialType.System_Int32 or SpecialType.System_Int64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_UInt16, SpecialType.System_Int32 or SpecialType.System_UInt32 or SpecialType.System_Int64 or SpecialType.System_UInt64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Int32, SpecialType.System_Int64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_UInt32, SpecialType.System_Int64 or SpecialType.System_UInt64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Int64 or SpecialType.System_UInt64, SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Char, SpecialType.System_UInt16 or SpecialType.System_Int32 or SpecialType.System_UInt32
                or SpecialType.System_Int64 or SpecialType.System_UInt64
                or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal) => true,
            (SpecialType.System_Single, SpecialType.System_Double) => true,
            _ => false,
        };
    }

public static ParseResult Parse(GeneratorAttributeSyntaxContext context, CancellationToken ct) {
        if (context.TargetSymbol is not INamedTypeSymbol typeSymbol) {
            return EmptyParseResult;
        }

        return Parse(typeSymbol, context.TargetNode, context.SemanticModel.Compilation, ct);
    }

public static ParseResult Parse(
        INamedTypeSymbol typeSymbol,
        SyntaxNode targetNode,
        Compilation compilation,
        CancellationToken ct) {
        if (ct.IsCancellationRequested) {
            return EmptyParseResult;
        }

        List<DiagnosticInfo> diagnostics = [];
        string filePath = GetFilePath(targetNode);
        Microsoft.CodeAnalysis.Text.LinePosition linePos = GetLinePosition(targetNode);

        // Validate type kind
        ValidateTypeKind(typeSymbol, targetNode, diagnostics, filePath, linePos);

        if (ct.IsCancellationRequested) {
            return EmptyParseResult;
        }

        // Extract type info
        string typeName = typeSymbol.Name;
        string ns = typeSymbol.ContainingNamespace?.IsGlobalNamespace == true
            ? string.Empty
            : typeSymbol.ContainingNamespace?.ToDisplayString() ?? string.Empty;

        // Parse attributes on the type
        string? boundedContext = ParseBoundedContext(typeSymbol, diagnostics, filePath, linePos, out string? boundedContextDisplayLabel);
        string? projectionRole = ParseProjectionRole(typeSymbol, diagnostics, filePath, linePos, out string? projectionRoleWhenState, out AttributeData? roleAttributeData);
        string? displayName = ParseDisplayAttribute(typeSymbol, out string? displayGroupName);
        string? emptyStateCtaCommandTypeName = ParseProjectionEmptyStateCta(typeSymbol);

        if (ct.IsCancellationRequested) {
            return EmptyParseResult;
        }

        // Parse properties
        ImmutableArray<PropertyModel>.Builder propertiesBuilder = ImmutableArray.CreateBuilder<PropertyModel>();

        var propertySymbols = typeSymbol.GetMembers()
            .OfType<IPropertySymbol>()
            .Where(static propertySymbol =>
                propertySymbol.DeclaredAccessibility == Accessibility.Public
                && !propertySymbol.IsStatic
                && !propertySymbol.IsIndexer)
            .ToImmutableArray();

        if (typeSymbol.DeclaringSyntaxReferences.Length > 1) {
            propertySymbols = propertySymbols
                .OrderBy(static propertySymbol => propertySymbol.Name, StringComparer.Ordinal)
                .ToImmutableArray();
        }

        for (int i = 0; i < propertySymbols.Length; i++) {
            if (ct.IsCancellationRequested) {
                return EmptyParseResult;
            }

            PropertyModel property = ParseProperty(propertySymbols[i], typeName, diagnostics, filePath, compilation);
            propertiesBuilder.Add(property);
        }

        EquatableArray<PropertyModel> parsedProperties = new(propertiesBuilder.ToImmutable());

        // Story 4-4 T6.5 / D15 — HFC1028 per-projection dedupe: fire once per projection that
        // declares ≥ 2 properties with the SAME explicit non-null [ColumnPriority] value.
        EmitColumnPriorityCollisionDiagnostic(typeSymbol, parsedProperties, diagnostics, filePath, linePos);

        // Story 4-5 T6.4 / D9 / D16 — HFC1030 per-projection dedupe: fire once per projection
        // that declares any [ProjectionFieldGroup] whose name case-insensitively matches the
        // reserved catch-all label. Information severity; fail-soft pass-through (the group
        // name is preserved on the IR so emit still renders the colliding accordion).
        EmitFieldGroupCatchAllCollisionDiagnostic(typeSymbol, parsedProperties, diagnostics, filePath, linePos);

        // Story 4-1 T1.4 — validate WhenState CSV against the projection's status-enum type.
        // Emits HFC1022 per unknown member. Unknown members still flow through to the IR
        // (fail-soft; runtime string compare silently never matches).
        ValidateWhenStateAgainstStatusEnum(
            typeSymbol,
            projectionRoleWhenState,
            parsedProperties,
            diagnostics,
            filePath,
            linePos);

        var model = new DomainModel(
            typeName,
            ns,
            boundedContext,
            boundedContextDisplayLabel,
            projectionRole,
            parsedProperties,
            projectionRoleWhenState,
            displayName,
            displayGroupName,
            filePath,
            linePos.Line,
            linePos.Character,
            emptyStateCtaCommandTypeName);

        return new ParseResult(
            model,
            new EquatableArray<DiagnosticInfo>(diagnostics.ToImmutableArray()));
    }

private static void ValidateTypeKind(
        INamedTypeSymbol typeSymbol,
        SyntaxNode targetNode,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        // Check partial keyword
        bool isPartial = targetNode is TypeDeclarationSyntax tds
            && tds.Modifiers.Any(m => m.IsKind(SyntaxKind.PartialKeyword));
        if (!isPartial) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1003",
                string.Format("[Projection] type '{0}' should be declared as partial for source generator to emit code", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        // Check for struct types
        if (typeSymbol.TypeKind == TypeKind.Struct) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Projection] attribute on '{0}' is not supported: structs are not supported. Only non-abstract, non-generic classes and records are supported", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        // Check for abstract types
        if (typeSymbol.IsAbstract) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Projection] attribute on '{0}' is not supported: abstract types are not supported. Only non-abstract, non-generic classes and records are supported", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        // Check for generic types
        if (typeSymbol.IsGenericType) {
            diagnostics.Add(new DiagnosticInfo(
                "HFC1004",
                string.Format("[Projection] attribute on '{0}' is not supported: generic types are not supported. Only non-abstract, non-generic classes and records are supported", typeSymbol.Name),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }

        // Check for nested class in non-partial outer
        if (typeSymbol.ContainingType is INamedTypeSymbol containingType) {
            SyntaxReference? outerRef = containingType.DeclaringSyntaxReferences.FirstOrDefault();
            bool outerIsPartial = outerRef?.GetSyntax() is TypeDeclarationSyntax outerTds
                && outerTds.Modifiers.Any(m => m.IsKind(SyntaxKind.PartialKeyword));

            if (!outerIsPartial) {
                diagnostics.Add(new DiagnosticInfo(
                    "HFC1004",
                    string.Format("[Projection] attribute on '{0}' is not supported: nested in non-partial type '{1}'. Only non-abstract, non-generic classes and records are supported", typeSymbol.Name, containingType.Name),
                    "Warning",
                    filePath,
                    linePos.Line,
                    linePos.Character));
            }
        }

    }

private static string? ParseBoundedContext(
        INamedTypeSymbol typeSymbol,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos,
        out string? displayLabel) {
        displayLabel = null;
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == BoundedContextAttributeName) {
                // Extract DisplayLabel from named arguments
                foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                    if (namedArg.Key == "DisplayLabel" && namedArg.Value.Value is string label
                        && !string.IsNullOrWhiteSpace(label)) {
                        displayLabel = label;
                    }
                }

                if (attr.ConstructorArguments.Length > 0) {
                    TypedConstant arg = attr.ConstructorArguments[0];
                    if (arg.Value is string name && !string.IsNullOrWhiteSpace(name)) {
                        return name.Trim();
                    }

                    // BoundedContext name is invalid — clear any captured DisplayLabel
                    displayLabel = null;
                    diagnostics.Add(new DiagnosticInfo(
                        "HFC1005",
                        string.Format("Invalid argument for attribute 'BoundedContext' on type '{0}': name must be a non-empty string", typeSymbol.Name),
                        "Warning",
                        filePath,
                        linePos.Line,
                        linePos.Character));
                }

                return null;
            }
        }

        return null;
    }

private static string? ParseProjectionRole(
        INamedTypeSymbol typeSymbol,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos,
        out string? whenState,
        out AttributeData? roleAttributeData) {
        whenState = null;
        roleAttributeData = null;
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == ProjectionRoleAttributeName) {
                roleAttributeData = attr;

                // Story 4-1 D2 / T1.3 — extract optional WhenState named argument (init-only).
                // Empty/whitespace → treated as absent (D3). Explicit null also treated as absent.
                foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                    if (namedArg.Key == "WhenState") {
                        if (namedArg.Value.Value is string raw && !string.IsNullOrWhiteSpace(raw)) {
                            whenState = raw;
                        }
                    }
                }

                string? parsedRole = null;
                if (attr.ConstructorArguments.Length > 0) {
                    TypedConstant arg = attr.ConstructorArguments[0];
                    if (arg.Value is int enumValue) {
                        if (TryResolveEnumMemberName(attr.AttributeClass!.ContainingAssembly, ProjectionRoleEnumName, enumValue, out string roleName)) {
                            parsedRole = roleName;
                        }
                        else {
                            // Story 4-1 D15 / T1.5 / AC7 — unknown numeric role value: emit HFC1024
                            // (Warning), carry the raw int as the role string so Transform falls
                            // back to Default rendering.
                            diagnostics.Add(new DiagnosticInfo(
                                "HFC1024",
                                string.Format(
                                    "Unknown ProjectionRole value '{0}' on {1} - falling back to Default rendering.",
                                    enumValue,
                                    typeSymbol.Name),
                                "Warning",
                                filePath,
                                linePos.Line,
                                linePos.Character));

                            parsedRole = enumValue.ToString(System.Globalization.CultureInfo.InvariantCulture);
                        }
                    }
                }

                return parsedRole;
            }
        }

        return null;
    }

private static void ValidateWhenStateAgainstStatusEnum(
        INamedTypeSymbol typeSymbol,
        string? whenState,
        EquatableArray<PropertyModel> properties,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        if (string.IsNullOrWhiteSpace(whenState)) {
            return;
        }

        // Find the status-enum property using D10/D11 tiebreaker: prefer enum-typed property
        // whose enum type declares any [ProjectionBadge]-annotated member; else first enum
        // property in declaration order.
        PropertyModel? statusProperty = null;
        foreach (PropertyModel property in properties) {
            if (property.EnumFullyQualifiedName is null) {
                continue;
            }

            if (property.BadgeMappings.Count > 0) {
                statusProperty = property;
                break;
            }

            statusProperty ??= property;
        }

        if (statusProperty is null) {
            return;
        }

        List<string> validMembers = [.. statusProperty.EnumMemberNames];

        if (validMembers.Count == 0) {
            return;
        }

        HashSet<string> validMemberSet = new(validMembers, StringComparer.Ordinal);

        // Split CSV: trim each entry, drop empties; unknown members emit HFC1022 per member.
        string[] tokens = whenState!.Split(',');
        foreach (string raw in tokens) {
            string trimmed = raw.Trim();
            if (trimmed.Length == 0) {
                continue;
            }

            if (validMemberSet.Contains(trimmed)) {
                continue;
            }

            string previewList = FormatValidMemberPreview(validMembers);
            diagnostics.Add(new DiagnosticInfo(
                "HFC1022",
                string.Format(
                    "ProjectionRole.WhenState on {0} references unknown enum member '{1}' - member will be treated as always-no-match at runtime. Valid members: {2}.",
                    typeSymbol.Name,
                    trimmed,
                    previewList),
                "Warning",
                filePath,
                linePos.Line,
                linePos.Character));
        }
    }

private static string FormatValidMemberPreview(List<string> members) {
        string[] sorted = [.. members];
        Array.Sort(sorted, StringComparer.Ordinal);
        if (sorted.Length <= 10) {
            return string.Join(", ", sorted);
        }

        int overflow = sorted.Length - 10;
        string head = string.Join(", ", sorted, 0, 10);
        return string.Format("{0}, ... and {1} more", head, overflow);
    }

private static PropertyModel ParseProperty(
        IPropertySymbol propertySymbol,
        string containingTypeName,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Compilation compilation,
        bool isCommandContext = false) {
        ITypeSymbol propertyType = propertySymbol.Type;
        bool isNullable = false;
        string fullyQualifiedTypeName;

        // Handle Nullable<T> for value types
        if (propertyType is INamedTypeSymbol namedType
            && namedType.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T
            && namedType.TypeArguments.Length == 1) {
            isNullable = true;
            propertyType = namedType.TypeArguments[0];
        }

        // Handle reference type nullability via annotation
        if (!isNullable && propertySymbol.NullableAnnotation == NullableAnnotation.Annotated) {
            isNullable = true;
        }

        // Handle nullable context disabled: treat reference types as nullable by default
        if (!isNullable
            && propertySymbol.NullableAnnotation == NullableAnnotation.None
            && propertyType.IsReferenceType) {
            isNullable = true;
        }

        bool isEnumType = propertyType.TypeKind == TypeKind.Enum;
        bool isEnum = IsSupportedEnumType(propertyType);
        string sourceTypeName = SourceTypeNameFormatter.Format(
            propertyType,
            compilation,
            out EquatableArray<string> requiredExternAliases);
        bool supportsStaticAssignment = SupportsStaticAssignment(propertySymbol, propertyType, compilation);

        // Get fully qualified type name for mapping
        if (propertyType is INamedTypeSymbol namedPropertyType && namedPropertyType.IsGenericType) {
            // Build constructed name for display
            fullyQualifiedTypeName = namedPropertyType.OriginalDefinition.ContainingNamespace?.ToDisplayString() + "." + namedPropertyType.OriginalDefinition.Name;
        }
        else {
            fullyQualifiedTypeName = propertyType.ToDisplayString(
                new SymbolDisplayFormat(
                    typeQualificationStyle: SymbolDisplayTypeQualificationStyle.NameAndContainingTypesAndNamespaces));
        }

        // Map the type
        string? irType = FieldTypeMapper.MapType(fullyQualifiedTypeName, isEnum);
        bool isUnsupported = irType is null;
        string? enumFqn = isEnum ? fullyQualifiedTypeName : null;
        string? unsupportedFqn = isUnsupported ? fullyQualifiedTypeName : null;

        // HFC1008 (command-only): [Flags] enum properties cannot be expressed by a single-select
        // FluentSelect. Route them through the unsupported path so FcFieldPlaceholder renders.
        // (See code-review 2026-04-15, Decision 3.)
        if (isCommandContext && isEnumType && HasFlagsAttribute(propertyType)) {
            Location flagsLocation = propertySymbol.Locations.FirstOrDefault() ?? Location.None;
            Microsoft.CodeAnalysis.Text.LinePosition flagsLinePos = flagsLocation.GetLineSpan().StartLinePosition;
            string flagsFilePath = flagsLocation.SourceTree?.FilePath ?? filePath;
            diagnostics.Add(new DiagnosticInfo(
                "HFC1008",
                string.Format(
                    "Property '{0}' on command '{1}' is a [Flags] enum, which cannot be expressed by a single-select control. The field will render as FcFieldPlaceholder; provide a custom multi-select renderer via the customization gradient.",
                    propertySymbol.Name,
                    containingTypeName),
                "Warning",
                flagsFilePath,
                flagsLinePos.Line,
                flagsLinePos.Character));
            isUnsupported = true;
            unsupportedFqn = fullyQualifiedTypeName;
            irType = propertyType.ToDisplayString();
            enumFqn = null;
        }

        if (isUnsupported) {
            Location location = propertySymbol.Locations.FirstOrDefault() ?? Location.None;
            Microsoft.CodeAnalysis.Text.LinePosition propLinePos = location.GetLineSpan().StartLinePosition;
            string propFilePath = location.SourceTree?.FilePath ?? filePath;
            string unsupportedType = DescribeUnsupportedType(propertyType, isEnumType);

            string newline = "\n";

            if (!HasSuppressMessage(propertySymbol, "HFC1002")) {
                diagnostics.Add(new DiagnosticInfo(
                    "HFC1002",
                    string.Format(
                        "What: Property '{0}' on type '{1}' is not supported for auto-generation.{3}Expected: One of: string, int, long, decimal, double, float, bool, DateTime, DateTimeOffset, DateOnly, TimeOnly, enum (backed by int), Guid, or nullable/collection variants.{3}Got: {2}{3}Fix: Use a supported type, or provide a custom renderer through the projection slot or command customization path.{3}DocsLink: https://hexalith.github.io/FrontComposer/diagnostics/HFC1002",
                        propertySymbol.Name,
                        containingTypeName,
                        unsupportedType,
                        newline),
                    "Warning",
                    propFilePath,
                    propLinePos.Line,
                    propLinePos.Character));
            }

            irType = propertyType.ToDisplayString();
        }

        string resolvedTypeName = irType ?? propertyType.ToDisplayString();

        // Parse display metadata
        (string? displayName, string? displayDescription) = ParseDisplayAttribute(propertySymbol);
        string? description = ParseDescriptionAttribute(propertySymbol) ?? displayDescription;

        // Parse [ProjectionBadge] from enum fields (if this property is an enum type)
        EquatableArray<BadgeMappingEntry> badgeMappings = ParseBadgeMappings(propertyType, isEnum, diagnostics, filePath);
        EquatableArray<string> enumMemberNames = GetEnumMemberNames(propertyType, isEnum);

        // Story 4-4 T6.1 / D14 — [ColumnPriority(N)] annotation; null when absent.
        int? columnPriority = ParseColumnPriority(propertySymbol);

        // Story 4-5 T6.4 / D9 — [ProjectionFieldGroup("Name")] annotation; null when absent.
        (string? fieldGroup, string? fieldGroupDescription) = ParseProjectionFieldGroup(propertySymbol);

        FieldDisplayFormat displayFormat = ParseDisplayFormat(
            propertySymbol,
            containingTypeName,
            resolvedTypeName,
            propertyType,
            diagnostics,
            filePath,
            out int? relativeTimeWindowDays);

        return new PropertyModel(
            propertySymbol.Name,
            resolvedTypeName,
            isNullable,
            isUnsupported,
            displayName,
            badgeMappings,
            enumFqn,
            unsupportedFqn,
            enumMemberNames,
            columnPriority,
            fieldGroup,
            description,
            displayFormat,
            relativeTimeWindowDays,
            propertySymbol.SetMethod is { DeclaredAccessibility: Accessibility.Public, IsInitOnly: false },
            sourceTypeName,
            requiredExternAliases,
            supportsStaticAssignment,
            fieldGroupDescription);
    }

private static bool ContainsPointerSyntax(ITypeSymbol typeSymbol)
        => typeSymbol switch {
            IPointerTypeSymbol => true,
            IFunctionPointerTypeSymbol => true,
            IArrayTypeSymbol arrayType => ContainsPointerSyntax(arrayType.ElementType),
            _ => false,
        };

private static bool ContainsNonSzArray(ITypeSymbol typeSymbol)
        => typeSymbol is IArrayTypeSymbol arrayType
            && ((arrayType.Rank == 1 && !arrayType.IsSZArray) || ContainsNonSzArray(arrayType.ElementType));

private static bool HasErrorObsoleteAttribute(ISymbol? symbol, Compilation compilation) {
        if (symbol is null) {
            return false;
        }

        INamedTypeSymbol? obsoleteAttribute = compilation.GetTypeByMetadataName("System.ObsoleteAttribute");
        if (obsoleteAttribute is null) {
            return false;
        }

        foreach (AttributeData attribute in symbol.GetAttributes()) {
            if (SymbolEqualityComparer.Default.Equals(attribute.AttributeClass, obsoleteAttribute)
                && attribute.ConstructorArguments.Length > 1
                && attribute.ConstructorArguments[1].Value is true) {
                return true;
            }
        }

        return false;
    }

private static bool HasExperimentalAttribute(ISymbol? symbol, Compilation compilation) {
        if (symbol is null) {
            return false;
        }

        INamedTypeSymbol? experimentalAttribute = compilation.GetTypeByMetadataName(
            "System.Diagnostics.CodeAnalysis.ExperimentalAttribute");
        return experimentalAttribute is not null
            && symbol.GetAttributes().Any(attribute =>
                SymbolEqualityComparer.Default.Equals(attribute.AttributeClass, experimentalAttribute));
    }

private static bool IsSourceNameableType(ITypeSymbol typeSymbol)
        => typeSymbol switch {
            IArrayTypeSymbol arrayType => IsSourceNameableType(arrayType.ElementType),
            IPointerTypeSymbol pointerType => IsSourceNameableType(pointerType.PointedAtType),
            IFunctionPointerTypeSymbol functionPointerType =>
                IsSourceNameableType(functionPointerType.Signature.ReturnType)
                && functionPointerType.Signature.Parameters.All(parameter => IsSourceNameableType(parameter.Type)),
            INamedTypeSymbol namedType => IsSourceNameableNamedType(namedType),
            ITypeParameterSymbol typeParameter => IsSourceNameableIdentifier(typeParameter.Name),
            _ => true,
        };

private static bool IsSourceNameableNamedType(INamedTypeSymbol namedType) {
        if (!IsSourceNameableIdentifier(namedType.Name)
            || (namedType.ContainingType is not null && !IsSourceNameableNamedType(namedType.ContainingType))
            || !IsSourceNameableNamespace(namedType.ContainingNamespace)) {
            return false;
        }

        return namedType.TypeArguments.All(IsSourceNameableType);
    }

private static bool IsSourceNameableNamespace(INamespaceSymbol? namespaceSymbol) {
        INamespaceSymbol? current = namespaceSymbol;
        while (current is not null && !current.IsGlobalNamespace) {
            if (!IsSourceNameableIdentifier(current.Name)) {
                return false;
            }

            current = current.ContainingNamespace;
        }

        return true;
    }

private static bool IsSourceNameableIdentifier(string identifier)
        => SyntaxFacts.IsValidIdentifier(identifier)
            || SyntaxFacts.GetKeywordKind(identifier) != SyntaxKind.None
            || SyntaxFacts.GetContextualKeywordKind(identifier) != SyntaxKind.None;

private static FieldDisplayFormat ParseDisplayFormat(
        IPropertySymbol propertySymbol,
        string containingTypeName,
        string resolvedTypeName,
        ITypeSymbol propertyType,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        out int? relativeTimeWindowDays) {
        relativeTimeWindowDays = null;
        int parsedRelativeTimeWindowDays = RelativeTimeWindowDefaultDays;
        bool relativeTimeWindowInvalid = false;
        string? invalidWindowDisplay = null;
        AttributeData? relativeTime = null;
        AttributeData? currency = null;

        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            string? attributeName = attr.AttributeClass?.ToDisplayString();
            if (attributeName == RelativeTimeAttributeName) {
                relativeTime = attr;
                // Story 6-1 review F1 — source generators read AttributeData, not the runtime
                // constructor, so the runtime 1..365 guard never fires at compile time. Mirror
                // the bound here and treat any non-int / out-of-range argument as invalid
                // metadata (HFC1032), then fall back to the default 7-day window per D5.
                if (attr.ConstructorArguments.Length > 0) {
                    TypedConstant ctorArg = attr.ConstructorArguments[0];
                    if (ctorArg.Value is int days
                        && days >= RelativeTimeWindowMinDays
                        && days <= RelativeTimeWindowMaxDays) {
                        parsedRelativeTimeWindowDays = days;
                    }
                    else {
                        relativeTimeWindowInvalid = true;
                        invalidWindowDisplay = ctorArg.Value is null
                            ? "null"
                            : ctorArg.Value.ToString() ?? ctorArg.Value.GetType().Name;
                    }
                }
            }
            else if (attributeName == CurrencyAttributeName) {
                currency = attr;
            }
        }

        if (relativeTime is null && currency is null) {
            return FieldDisplayFormat.Default;
        }

        if (relativeTime is not null && currency is not null) {
            EmitLevel1FormatDiagnostic(
                propertySymbol,
                containingTypeName,
                "[RelativeTime] + [Currency]",
                "at most one Level 1 format annotation",
                resolvedTypeName,
                "Remove one annotation so the field has a single format hint.",
                diagnostics,
                filePath);
            return FieldDisplayFormat.Default;
        }

        if (relativeTime is not null) {
            if (!IsRelativeTimeCompatible(resolvedTypeName)) {
                EmitLevel1FormatDiagnostic(
                    propertySymbol,
                    containingTypeName,
                    "[RelativeTime]",
                    "DateTime or DateTimeOffset",
                    DescribeUnsupportedType(propertyType, propertyType.TypeKind == TypeKind.Enum),
                    "Apply [RelativeTime] only to DateTime/DateTimeOffset fields or remove the annotation.",
                    diagnostics,
                    filePath);
                return FieldDisplayFormat.Default;
            }

            if (relativeTimeWindowInvalid) {
                EmitLevel1FormatDiagnostic(
                    propertySymbol,
                    containingTypeName,
                    "[RelativeTime(N)]",
                    "an int between " + RelativeTimeWindowMinDays + " and " + RelativeTimeWindowMaxDays,
                    invalidWindowDisplay ?? "non-int",
                    "Use [RelativeTime] (default 7) or pass an int between 1 and 365.",
                    diagnostics,
                    filePath);
                return FieldDisplayFormat.Default;
            }

            relativeTimeWindowDays = parsedRelativeTimeWindowDays;
            return FieldDisplayFormat.RelativeTime;
        }

        if (IsCurrencyCompatible(resolvedTypeName)) {
            return FieldDisplayFormat.Currency;
        }

        EmitLevel1FormatDiagnostic(
            propertySymbol,
            containingTypeName,
            "[Currency]",
            "decimal, double, or float",
            DescribeUnsupportedType(propertyType, propertyType.TypeKind == TypeKind.Enum),
            "Apply [Currency] only to decimal/double/float fields or remove the annotation.",
            diagnostics,
            filePath);
        return FieldDisplayFormat.Default;
    }

private static (string? GroupName, string? Description) ParseProjectionFieldGroup(IPropertySymbol propertySymbol) {
        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == ProjectionFieldGroupAttributeName
                && attr.ConstructorArguments.Length > 0
                && attr.ConstructorArguments[0].Value is string groupName
                && !string.IsNullOrWhiteSpace(groupName)) {
                string? description = attr.NamedArguments
                    .Where(argument => argument.Key == "Description")
                    .Select(argument => argument.Value.Value as string)
                    .FirstOrDefault();
                return (groupName.Trim(), string.IsNullOrWhiteSpace(description) ? null : description!.Trim());
            }
        }

        return (null, null);
    }

private static string? ParseProjectionEmptyStateCta(INamedTypeSymbol typeSymbol) {
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == ProjectionEmptyStateCtaAttributeName
                && attr.ConstructorArguments.Length > 0
                && attr.ConstructorArguments[0].Value is string commandTypeName
                && !string.IsNullOrWhiteSpace(commandTypeName)) {
                return commandTypeName.Trim();
            }
        }

        return null;
    }

private static void EmitFieldGroupCatchAllCollisionDiagnostic(
        INamedTypeSymbol typeSymbol,
        EquatableArray<PropertyModel> properties,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        SortedSet<string>? colliding = null;
        foreach (PropertyModel property in properties) {
            if (property.FieldGroup is not string group) {
                continue;
            }

            if (!string.Equals(group, FieldGroupCatchAllLabel, StringComparison.OrdinalIgnoreCase)) {
                continue;
            }

            colliding ??= new SortedSet<string>(StringComparer.Ordinal);
            _ = colliding.Add(group);
        }

        if (colliding is null) {
            return;
        }

        string payload = string.Join(", ", colliding);
        diagnostics.Add(new DiagnosticInfo(
            "HFC1030",
            string.Format(
                "ProjectionFieldGroup name '{0}' on {1} collides with the reserved catch-all group label \"{2}\" — rename the group to prevent visual confusion.",
                payload,
                typeSymbol.Name,
                FieldGroupCatchAllLabel),
            "Info",
            filePath,
            linePos.Line,
            linePos.Character));
    }

private static int? ParseColumnPriority(IPropertySymbol propertySymbol) {
        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == ColumnPriorityAttributeName
                && attr.ConstructorArguments.Length > 0
                && attr.ConstructorArguments[0].Value is int priority) {
                return priority;
            }
        }

        return null;
    }

private static void EmitColumnPriorityCollisionDiagnostic(
        INamedTypeSymbol typeSymbol,
        EquatableArray<PropertyModel> properties,
        List<DiagnosticInfo> diagnostics,
        string filePath,
        Microsoft.CodeAnalysis.Text.LinePosition linePos) {
        Dictionary<int, List<string>>? groups = null;
        foreach (PropertyModel property in properties) {
            if (property.ColumnPriority is not int priority) {
                continue;
            }

            groups ??= [];

            if (!groups.TryGetValue(priority, out List<string>? names)) {
                names = [];
                groups[priority] = names;
            }

            names.Add(property.Name);
        }

        if (groups is null) {
            return;
        }

        // Fire once per colliding priority value (per-projection dedupe on the HFC1028 code
        // itself — multiple distinct priorities colliding on the same projection surface as
        // multiple Information diagnostics carrying disjoint payload sets).
        foreach (KeyValuePair<int, List<string>> kvp in groups) {
            if (kvp.Value.Count < 2) {
                continue;
            }

            string[] sorted = [.. kvp.Value];
            Array.Sort(sorted, StringComparer.Ordinal);
            string payloadNames = string.Join(", ", sorted);
            diagnostics.Add(new DiagnosticInfo(
                "HFC1028",
                string.Format(
                    "[ColumnPriority] collision on {0} — properties [{1}] share priority {2}. Deterministic tiebreaker is declaration order.",
                    typeSymbol.Name,
                    payloadNames,
                    kvp.Key),
                "Info",
                filePath,
                linePos.Line,
                linePos.Character));
        }
    }

private static bool HasFlagsAttribute(ITypeSymbol typeSymbol) {
        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == "System.FlagsAttribute") {
                return true;
            }
        }

        return false;
    }

private static string? ParseDescriptionAttribute(IPropertySymbol propertySymbol) {
        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == DescriptionAttributeName
                && attr.ConstructorArguments.Length > 0
                && attr.ConstructorArguments[0].Value is string description) {
                return NormalizeOptionalString(description);
            }
        }

        return null;
    }

private static (string? DisplayName, string? Description) ParseDisplayAttribute(IPropertySymbol propertySymbol) {
        foreach (AttributeData attr in propertySymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() == DisplayAttributeName) {
                // DisplayAttribute uses named arguments: Name="...", Description="..."
                string? displayName = null;
                string? description = null;
                foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                    if (namedArg.Key == "Name" && namedArg.Value.Value is string name) {
                        displayName = name;
                    }
                    else if (namedArg.Key == "Description" && namedArg.Value.Value is string rawDescription) {
                        description = NormalizeOptionalString(rawDescription);
                    }
                }

                return (displayName, description);
            }
        }

        return (null, null);
    }

private static string? ParseDisplayAttribute(INamedTypeSymbol typeSymbol, out string? groupName) {
        groupName = null;

        foreach (AttributeData attr in typeSymbol.GetAttributes()) {
            if (attr.AttributeClass?.ToDisplayString() != DisplayAttributeName) {
                continue;
            }

            string? displayName = null;
            foreach (KeyValuePair<string, TypedConstant> namedArg in attr.NamedArguments) {
                if (namedArg.Key == "GroupName"
                    && namedArg.Value.Value is string rawGroupName
                    && !string.IsNullOrWhiteSpace(rawGroupName)) {
                    groupName = rawGroupName.Trim();
                }
                else if (namedArg.Key == "Name"
                    && namedArg.Value.Value is string rawDisplayName
                    && !string.IsNullOrWhiteSpace(rawDisplayName)) {
                    displayName = rawDisplayName.Trim();
                }
            }

            return displayName;
        }

        return null;
    }

private static EquatableArray<BadgeMappingEntry> ParseBadgeMappings(
        ITypeSymbol propertyType,
        bool isEnum,
        List<DiagnosticInfo> diagnostics,
        string filePath) {
        if (!isEnum) {
            return EmptyBadgeMappings;
        }

        if (propertyType is not INamedTypeSymbol enumType) {
            return EmptyBadgeMappings;
        }

        // Story 4-2 D10 / RF5 — [Flags] enums cannot be expressed as a single-value badge (a
        // bitmask may set multiple members simultaneously). Falling back to empty mappings
        // routes the column through the Story 1-5 plain-text path; adopters needing
        // compound rendering take the Epic 6 customization gradient. When the enum was
        // deliberately annotated with [ProjectionBadge] on at least one member we emit
        // HFC1008 so the ignored annotations surface in the Error List rather than being
        // silently dropped (RF5 review finding).
        if (HasFlagsAttribute(propertyType)) {
            EmitFlagsEnumBadgeDiagnosticIfAnnotated(enumType, diagnostics, filePath);
            return EmptyBadgeMappings;
        }

        ImmutableArray<BadgeMappingEntry>.Builder builder = ImmutableArray.CreateBuilder<BadgeMappingEntry>();

        foreach (ISymbol member in enumType.GetMembers()) {
            if (member is IFieldSymbol field && field.HasConstantValue) {
                foreach (AttributeData attr in field.GetAttributes()) {
                    if (attr.AttributeClass?.ToDisplayString() == ProjectionBadgeAttributeName
                        && attr.ConstructorArguments.Length > 0
                        && attr.ConstructorArguments[0].Value is int slotValue) {
                        if (TryResolveEnumMemberName(attr.AttributeClass!.ContainingAssembly, BadgeSlotEnumName, slotValue, out string slotName)) {
                            builder.Add(new BadgeMappingEntry(field.Name, slotName));
                        }
                        else {
                            Location location = field.Locations.FirstOrDefault() ?? Location.None;
                            Microsoft.CodeAnalysis.Text.LinePosition linePos = location.GetLineSpan().StartLinePosition;
                            string fieldFilePath = location.SourceTree?.FilePath ?? filePath;

                            diagnostics.Add(new DiagnosticInfo(
                                "HFC1005",
                                string.Format("Invalid argument for attribute 'ProjectionBadge' on enum member '{0}': slot must be a defined BadgeSlot value", field.Name),
                                "Warning",
                                fieldFilePath,
                                linePos.Line,
                                linePos.Character));
                        }
                    }
                }
            }
        }

        return new EquatableArray<BadgeMappingEntry>(builder.ToImmutable());
    }

private static void EmitFlagsEnumBadgeDiagnosticIfAnnotated(
        INamedTypeSymbol enumType,
        List<DiagnosticInfo> diagnostics,
        string filePath) {
        IFieldSymbol? annotatedMember = null;
        foreach (ISymbol member in enumType.GetMembers()) {
            if (member is not IFieldSymbol field || !field.HasConstantValue) {
                continue;
            }

            foreach (AttributeData attr in field.GetAttributes()) {
                if (attr.AttributeClass?.ToDisplayString() == ProjectionBadgeAttributeName) {
                    annotatedMember = field;
                    break;
                }
            }

            if (annotatedMember is not null) {
                break;
            }
        }

        if (annotatedMember is null) {
            return;
        }

        Location location = annotatedMember.Locations.FirstOrDefault() ?? Location.None;
        Microsoft.CodeAnalysis.Text.LinePosition linePos = location.GetLineSpan().StartLinePosition;
        string memberFilePath = location.SourceTree?.FilePath ?? filePath;

        diagnostics.Add(new DiagnosticInfo(
            "HFC1008",
            string.Format(
                "[Flags] enum '{0}' carries [ProjectionBadge] annotations that are ignored because a bitmask value can set multiple members simultaneously and the 6-slot palette cannot render compound state. Remove the annotations or supply a custom multi-badge renderer via the Epic 6 Slot-level customization gradient.",
                enumType.ToDisplayString()),
            "Warning",
            memberFilePath,
            linePos.Line,
            linePos.Character));
    }

private static EquatableArray<string> GetEnumMemberNames(ITypeSymbol propertyType, bool isEnum) {
        if (!isEnum || propertyType is not INamedTypeSymbol enumType) {
            return new EquatableArray<string>(ImmutableArray<string>.Empty);
        }

        ImmutableArray<string>.Builder builder = ImmutableArray.CreateBuilder<string>();
        foreach (ISymbol member in enumType.GetMembers()) {
            if (member is IFieldSymbol field && field.HasConstantValue) {
                builder.Add(field.Name);
            }
        }

        return new EquatableArray<string>(builder.ToImmutable());
    }

private static bool IsSupportedEnumType(ITypeSymbol propertyType) => propertyType is INamedTypeSymbol enumType
            && enumType.TypeKind == TypeKind.Enum
            && enumType.EnumUnderlyingType?.SpecialType == SpecialType.System_Int32;

private static bool HasSuppressMessage(ISymbol symbol, string diagnosticId) {
        foreach (AttributeData attribute in symbol.GetAttributes()) {
            string? attributeName = attribute.AttributeClass?.ToDisplayString();
            if (attributeName is not (SuppressMessageAttributeName or UnconditionalSuppressMessageAttributeName)
                || attribute.ConstructorArguments.Length < 2
                || attribute.ConstructorArguments[1].Value is not string checkId) {
                continue;
            }

            if (checkId.Equals(diagnosticId, StringComparison.OrdinalIgnoreCase)
                || checkId.StartsWith(diagnosticId + ":", StringComparison.OrdinalIgnoreCase)) {
                return true;
            }
        }

        return false;
    }

private static string DescribeUnsupportedType(ITypeSymbol propertyType, bool isEnumType) {
        if (isEnumType
            && propertyType is INamedTypeSymbol enumType
            && enumType.EnumUnderlyingType is ITypeSymbol underlyingType) {
            return string.Format("{0} (enum underlying type {1})", propertyType.ToDisplayString(), underlyingType.ToDisplayString());
        }

        return propertyType.ToDisplayString();
    }

private static bool TryResolveEnumMemberName(IAssemblySymbol assembly, string metadataName, int value, out string memberName) {
        INamedTypeSymbol? enumType = assembly.GetTypeByMetadataName(metadataName);
        if (enumType is not null) {
            foreach (ISymbol member in enumType.GetMembers()) {
                if (member is IFieldSymbol field
                    && field.HasConstantValue
                    && field.ConstantValue is int fieldValue
                    && fieldValue == value) {
                    memberName = field.Name;
                    return true;
                }
            }
        }

        memberName = string.Empty;
        return false;
    }

public static ColumnModel? ResolveStatusEnumColumn(RazorModel model) {
        ColumnModel? badgedEnum = null;
        ColumnModel? firstEnum = null;

        foreach (ColumnModel col in model.Columns) {
            if (col.TypeCategory != TypeCategory.Enum) {
                continue;
            }

            firstEnum ??= col;

            if (badgedEnum is null && col.BadgeMappings.Count > 0) {
                badgedEnum = col;
            }
        }

        return badgedEnum ?? firstEnum;
    }

public static ColumnModel? ResolveFirstDateTimeColumn(RazorModel model) {
        foreach (ColumnModel col in model.Columns) {
            if (col.TypeCategory == TypeCategory.DateTime) {
                return col;
            }
        }

        return null;
    }

public static ColumnModel? ResolveFirstTextColumn(RazorModel model) {
        foreach (ColumnModel col in model.Columns) {
            if (col.TypeCategory == TypeCategory.Text) {
                return col;
            }
        }

        return null;
    }

public static ColumnModel? ResolveTimelineLabelColumn(RazorModel model) {
        ColumnModel? preferred = null;
        ColumnModel? nonIdText = null;
        ColumnModel? idLikeText = null;

        foreach (ColumnModel col in model.Columns) {
            if (col.TypeCategory != TypeCategory.Text) {
                continue;
            }

            if (preferred is null && IsPreferredTimelineLabelProperty(col.PropertyName)) {
                preferred = col;
            }

            if (IsIdLikeProperty(model, col.PropertyName)) {
                idLikeText ??= col;
                continue;
            }

            nonIdText ??= col;
        }

        return preferred ?? nonIdText ?? idLikeText;
    }

public static string? ResolveAggregateIdProperty(RazorModel model) {
        foreach (ColumnModel col in model.Columns) {
            if (IsIdLikeProperty(model, col.PropertyName)) {
                return col.PropertyName;
            }
        }

        return null;
    }

public static ColumnModel? ResolveActionQueueSortColumn(RazorModel model) {
        ColumnModel? firstColumn = null;
        ColumnModel? badgedEnum = null;
        ColumnModel? firstDateTime = null;

        foreach (ColumnModel col in model.Columns) {
            firstColumn ??= col;

            if (badgedEnum is null
                && col.TypeCategory == TypeCategory.Enum
                && col.BadgeMappings.Count > 0) {
                badgedEnum = col;
            }

            if (firstDateTime is null && col.TypeCategory == TypeCategory.DateTime) {
                firstDateTime = col;
            }
        }

        return badgedEnum ?? firstDateTime ?? firstColumn;
    }

public static string? ResolveWhenStateFilterPredicate(RazorModel model) {
        if (model.WhenStates.Count == 0) {
            return null;
        }

        string? statusProperty = ResolveStatusEnumProperty(model);
        if (statusProperty is null) {
            return null;
        }

        List<string> comparisons = [];
        foreach (string state in model.WhenStates) {
            comparisons.Add(
                "x."
                + statusProperty
                + ".ToString() == \""
                + EscapeString(state)
                + "\"");
        }

        return comparisons.Count == 0 ? null : string.Join(" || ", comparisons);
    }

public static bool IsGridRenderingStrategy(ProjectionRenderStrategy strategy)
        => strategy is ProjectionRenderStrategy.Default
            or ProjectionRenderStrategy.ActionQueue
            or ProjectionRenderStrategy.StatusOverview
            or ProjectionRenderStrategy.Dashboard;

public static string ResolveItemKeyAccessorExpression(RazorModel model) {
        string? aggregateIdProp = null;
        string? idProp = null;
        string? keyProp = null;

        foreach (ColumnModel col in model.Columns) {
            if (aggregateIdProp is null
                && string.Equals(col.PropertyName, "AggregateId", StringComparison.Ordinal)) {
                aggregateIdProp = col.PropertyName;
            }
            else if (idProp is null
                && string.Equals(col.PropertyName, "Id", StringComparison.Ordinal)) {
                idProp = col.PropertyName;
            }
            else if (keyProp is null
                && string.Equals(col.PropertyName, "Key", StringComparison.Ordinal)) {
                keyProp = col.PropertyName;
            }
        }

        string? selected = aggregateIdProp ?? idProp ?? keyProp;
        return selected is null
            ? "(object)x"
            : "(object)x." + selected + "!";
    }

public static string ResolveViewKey(RazorModel model) {
        string bc = string.IsNullOrEmpty(model.BoundedContext)
            ? model.Namespace
            : model.BoundedContext!;
        string typeFqn = string.IsNullOrEmpty(model.Namespace)
            ? model.TypeName
            : model.Namespace + "." + model.TypeName;
        return bc + ":" + typeFqn;
    }

public static IReadOnlyList<FieldGroupBucket> ResolveFieldGroups(IReadOnlyList<ColumnModel> columns) {
        if (columns is null || columns.Count == 0) {
            return Array.Empty<FieldGroupBucket>();
        }

        // Detect whether ANY column declares a [ProjectionFieldGroup] annotation. When zero,
        // short-circuit to the legacy single-bucket form so 4-1 approval baselines stay green.
        bool anyAnnotated = false;
        for (int i = 0; i < columns.Count; i++) {
            if (columns[i].FieldGroup is not null) {
                anyAnnotated = true;
                break;
            }
        }

        if (!anyAnnotated) {
            return new[] { new FieldGroupBucket(null, columns) };
        }

        // Group-order discovery: walk in declaration order, emit a new bucket the first time
        // a non-null FieldGroup is seen, append subsequent same-name columns to that bucket.
        // Ungrouped columns go into a deferred catch-all that's appended at the end.
        Dictionary<string, List<ColumnModel>> grouped = new(StringComparer.Ordinal);
        List<string> orderedNames = [];
        List<ColumnModel> ungrouped = [];
        for (int i = 0; i < columns.Count; i++) {
            ColumnModel col = columns[i];
            if (col.FieldGroup is null) {
                ungrouped.Add(col);
                continue;
            }

            if (!grouped.TryGetValue(col.FieldGroup, out List<ColumnModel>? bucket)) {
                bucket = [];
                grouped.Add(col.FieldGroup, bucket);
                orderedNames.Add(col.FieldGroup);
            }

            bucket.Add(col);
        }

        List<FieldGroupBucket> result = new(orderedNames.Count + (ungrouped.Count > 0 ? 1 : 0));
        for (int i = 0; i < orderedNames.Count; i++) {
            string name = orderedNames[i];
            result.Add(new FieldGroupBucket(name, grouped[name]));
        }

        if (ungrouped.Count > 0) {
            result.Add(new FieldGroupBucket(null, ungrouped));
        }

        return result;
    }

private static bool IsIdLikeProperty(RazorModel model, string propertyName) {
        string typeIdCandidate = StripProjectionSuffix(model.TypeName) + "Id";
        return string.Equals(propertyName, "Id", StringComparison.OrdinalIgnoreCase)
            || string.Equals(propertyName, "AggregateId", StringComparison.OrdinalIgnoreCase)
            || string.Equals(propertyName, typeIdCandidate, StringComparison.OrdinalIgnoreCase);
    }

private static string StripProjectionSuffix(string typeName)
        => typeName.EndsWith("Projection", StringComparison.Ordinal)
            ? typeName.Substring(0, typeName.Length - "Projection".Length)
            : typeName;

private static readonly CSharpParseOptions ParseOptions =
        new CSharpParseOptions(LanguageVersion.Latest)
            .WithPreprocessorSymbols("DEBUG");

public static string AssignLiterals(string source) {
        if (string.IsNullOrEmpty(source) || source.IndexOf("++", StringComparison.Ordinal) < 0) {
            return source;
        }

        SyntaxTree tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
        SyntaxNode root = tree.GetRoot();

        // Fail safe on unparseable text: every edit below is a span into this tree, so an
        // error-recovered shape would silently relocate or truncate generated code.
        foreach (Diagnostic diagnostic in tree.GetDiagnostics()) {
            if (diagnostic.Severity == DiagnosticSeverity.Error) {
                return source;
            }
        }

        // Fail safe on any conditional region this parse cannot see (see the type remarks).
        if (HasUnseenConditionalRegion(root)) {
            return source;
        }

        List<CounterScope> scopes = CollectCounterScopes(root);
        if (scopes.Count == 0) {
            return source;
        }

        List<TextEdit> edits = [];
        foreach (CounterScope scope in scopes) {
            if (!scope.IsRewritable) {
                continue;
            }

            edits.Add(TextEdit.RemoveStatement(source, scope.Declaration));
            int next = scope.InitialValue;
            foreach (CounterReference reference in scope.References.OrderBy(static r => r.Position)) {
                if (reference.ResetValue.HasValue) {
                    next = reference.ResetValue.Value;
                    edits.Add(TextEdit.RemoveStatement(source, reference.Statement!));
                    continue;
                }

                edits.Add(new TextEdit(
                    reference.Span,
                    next.ToString(CultureInfo.InvariantCulture)));
                next++;
            }
        }

        return TextEdit.Apply(source, edits);
    }

public static string AssignLiteralsOrFail(string source) {
        string rewritten = AssignLiterals(source);
        string? survivingCallSite = FindRuntimeSequenceArgument(rewritten);
        if (survivingCallSite is null) {
            return rewritten;
        }

        throw new InvalidOperationException(
            "Render-tree sequence literal assignment failed safe and left a runtime sequence argument in generated output: "
            + survivingCallSite
            + ". Emitting it would raise ASP0006 in the consumer build, which has no control covering generated code.");
    }

internal static string? FindRuntimeSequenceArgument(string source) {
        // Cheap operator-presence gate only: it skips the parse for output that cannot hold a
        // surviving counter, and it deliberately over-matches (string, comment, and loop text)
        // because any narrower text rule reconstructs trivia and reopens the bypass this walk
        // closes. Both operators are tested here even though AssignLiterals rewrites only '++':
        // the walk below fails closed on decrements too, so aligning the two gates would silently
        // drop that arm.
        if (string.IsNullOrEmpty(source)
            || (source.IndexOf("++", StringComparison.Ordinal) < 0
                && source.IndexOf("--", StringComparison.Ordinal) < 0)) {
            return null;
        }

        SyntaxNode root = CSharpSyntaxTree.ParseText(source, ParseOptions).GetRoot();
        foreach (InvocationExpressionSyntax invocation in root.DescendantNodes().OfType<InvocationExpressionSyntax>()) {
            if (invocation.ArgumentList.Arguments.Count == 0) {
                continue;
            }

            string? invokedName = InvokedMemberName(invocation.Expression);
            if (invokedName is null || !SequenceMethodNames.Contains(invokedName)) {
                continue;
            }

            ExpressionSyntax sequenceArgument = invocation.ArgumentList.Arguments[0].Expression;
            foreach (SyntaxNode node in sequenceArgument.DescendantNodesAndSelf()) {
                if (node.IsKind(SyntaxKind.PostIncrementExpression)
                    || node.IsKind(SyntaxKind.PreIncrementExpression)
                    || node.IsKind(SyntaxKind.PostDecrementExpression)
                    || node.IsKind(SyntaxKind.PreDecrementExpression)) {
                    return invocation.ToString();
                }
            }
        }

        return null;
    }

private static string? InvokedMemberName(ExpressionSyntax expression) {
        SimpleNameSyntax? name = expression switch {
            MemberAccessExpressionSyntax memberAccess => memberAccess.Name,
            MemberBindingExpressionSyntax memberBinding => memberBinding.Name,
            SimpleNameSyntax simple => simple,
            _ => null,
        };

        return name?.Identifier.ValueText;
    }

private static bool HasUnseenConditionalRegion(SyntaxNode root) {
        if (!root.ContainsDirectives) {
            return false;
        }

        for (DirectiveTriviaSyntax? directive = root.GetFirstDirective();
            directive is not null;
            directive = directive.GetNextDirective()) {
            switch (directive) {
                case ElseDirectiveTriviaSyntax:
                case ElifDirectiveTriviaSyntax:
                    return true;
                case IfDirectiveTriviaSyntax ifDirective
                    when ifDirective.Condition is not IdentifierNameSyntax identifier
                        || !string.Equals(identifier.Identifier.ValueText, "DEBUG", StringComparison.Ordinal):
                    return true;
                default:
                    break;
            }
        }

        return false;
    }

private static string? CollectDisabledText(SyntaxNode root) {
        if (!root.ContainsDirectives) {
            return null;
        }

        StringBuilder? disabled = null;
        foreach (SyntaxTrivia trivia in root.DescendantTrivia(descendIntoTrivia: true)) {
            if (!trivia.IsKind(SyntaxKind.DisabledTextTrivia)) {
                continue;
            }

            disabled ??= new StringBuilder();
            _ = disabled.Append(trivia.ToFullString());
        }

        return disabled?.ToString();
    }

private static bool ContainsWholeWord(string text, string word) {
        int index = text.IndexOf(word, StringComparison.Ordinal);
        while (index >= 0) {
            bool leftBoundary = index == 0 || !IsIdentifierCharacter(text[index - 1]);
            int end = index + word.Length;
            bool rightBoundary = end >= text.Length || !IsIdentifierCharacter(text[end]);
            if (leftBoundary && rightBoundary) {
                return true;
            }

            index = text.IndexOf(word, index + 1, StringComparison.Ordinal);
        }

        return false;
    }

private static List<CounterScope> CollectCounterScopes(SyntaxNode root) {
        List<CounterScope> scopes = [];
        foreach (LocalDeclarationStatementSyntax statement in root.DescendantNodes().OfType<LocalDeclarationStatementSyntax>()) {
            if (statement.Declaration.Variables.Count != 1) {
                continue;
            }

            if (statement.Declaration.Type is not PredefinedTypeSyntax predefined
                || !predefined.Keyword.IsKind(SyntaxKind.IntKeyword)) {
                continue;
            }

            VariableDeclaratorSyntax declarator = statement.Declaration.Variables[0];
            if (declarator.Initializer is null
                || !TryGetIntLiteral(declarator.Initializer.Value, out int initialValue)) {
                continue;
            }

            if (statement.Parent is null) {
                continue;
            }

            scopes.Add(new CounterScope(
                declarator.Identifier.ValueText,
                statement,
                statement.Parent,
                initialValue));
        }

        if (scopes.Count == 0) {
            return scopes;
        }

        Dictionary<string, List<CounterScope>> byName = [];
        foreach (CounterScope scope in scopes) {
            if (!byName.TryGetValue(scope.Name, out List<CounterScope>? sameName)) {
                sameName = [];
                byName[scope.Name] = sameName;
            }

            sameName.Add(scope);
        }

        foreach (IdentifierNameSyntax identifier in root.DescendantNodes().OfType<IdentifierNameSyntax>()) {
            if (!byName.TryGetValue(identifier.Identifier.ValueText, out List<CounterScope>? candidates)) {
                continue;
            }

            CounterScope? owner = ResolveOwner(candidates, identifier);
            if (owner is null) {
                continue;
            }

            if (identifier.Parent is PostfixUnaryExpressionSyntax postfix
                && postfix.OperatorToken.IsKind(SyntaxKind.PlusPlusToken)
                && postfix.Parent is ArgumentSyntax argument
                && argument.RefKindKeyword.IsKind(SyntaxKind.None)) {
                owner.References.Add(CounterReference.Increment(postfix.Span));
                continue;
            }

            if (identifier.Parent is AssignmentExpressionSyntax assignment
                && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                && assignment.Left == identifier
                && assignment.Parent is ExpressionStatementSyntax resetStatement
                && TryGetIntLiteral(assignment.Right, out int resetValue)) {
                owner.References.Add(CounterReference.Reset(resetStatement, resetValue));
                continue;
            }

            owner.IsRewritable = false;
        }

        // Second layer over HasUnseenConditionalRegion: a counter whose name occurs in text this
        // configuration compiled out has references the syntax walk above never saw, so removing its
        // declaration could break the branch the other configuration compiles.
        string? disabledText = CollectDisabledText(root);
        foreach (CounterScope scope in scopes) {
            if (scope.References.Count == 0) {
                scope.IsRewritable = false;
                continue;
            }

            if (disabledText is not null && ContainsWholeWord(disabledText, scope.Name)) {
                scope.IsRewritable = false;
            }
        }

        return scopes;
    }

private static CounterScope? ResolveOwner(List<CounterScope> candidates, IdentifierNameSyntax identifier) {
        foreach (SyntaxNode ancestor in identifier.Ancestors()) {
            foreach (CounterScope scope in candidates) {
                if (scope.ScopeNode.RawKind == ancestor.RawKind
                    && scope.ScopeNode.FullSpan == ancestor.FullSpan
                    && scope.Declaration.SpanStart < identifier.SpanStart) {
                    return scope;
                }
            }
        }

        return null;
    }

private static bool TryGetIntLiteral(ExpressionSyntax expression, out int value) {
        if (expression is LiteralExpressionSyntax literal
            && literal.Token.IsKind(SyntaxKind.NumericLiteralToken)
            && literal.Token.Value is int parsed) {
            value = parsed;
            return true;
        }

        value = 0;
        return false;
    }

private CounterReference(int position, TextSpan span, StatementSyntax? statement, int? resetValue) {
            Position = position;
            Span = span;
            Statement = statement;
            ResetValue = resetValue;
        }

public static TextEdit RemoveStatement(string source, StatementSyntax statement) {
            int start = statement.SpanStart;
            int end = statement.Span.End;

            int lineStart = start;
            while (lineStart > 0 && source[lineStart - 1] != '\n') {
                lineStart--;
            }

            int lineEnd = end;
            while (lineEnd < source.Length && source[lineEnd] != '\n') {
                lineEnd++;
            }

            bool onlyContentOnLine =
                IsWhiteSpaceRange(source, lineStart, start)
                && IsWhiteSpaceRange(source, end, lineEnd);

            return onlyContentOnLine
                ? new TextEdit(TextSpan.FromBounds(lineStart, Math.Min(lineEnd + 1, source.Length)), string.Empty)
                : new TextEdit(statement.Span, string.Empty);
        }

public static string Apply(string source, List<TextEdit> edits) {
            if (edits is null) {
                throw new ArgumentNullException(nameof(edits));
            }

            if (edits.Count == 0) {
                return source;
            }

            List<TextEdit> ordered = [.. edits.OrderByDescending(static e => e.Span.Start)];
            for (int index = 1; index < ordered.Count; index++) {
                TextEdit later = ordered[index - 1];
                TextEdit earlier = ordered[index];
                if (earlier.Span.End > later.Span.Start) {
                    throw new InvalidOperationException(
                        "Render-tree sequence edits overlap: ["
                        + earlier.Span.Start.ToString(CultureInfo.InvariantCulture) + ", "
                        + earlier.Span.End.ToString(CultureInfo.InvariantCulture) + ") and ["
                        + later.Span.Start.ToString(CultureInfo.InvariantCulture) + ", "
                        + later.Span.End.ToString(CultureInfo.InvariantCulture) + ").");
                }
            }

            StringBuilder builder = new(source);
            foreach (TextEdit edit in ordered) {
                _ = builder.Remove(edit.Span.Start, edit.Span.Length);
                if (edit.Replacement.Length > 0) {
                    _ = builder.Insert(edit.Span.Start, edit.Replacement);
                }
            }

            return builder.ToString();
        }

private static bool IsWhiteSpaceRange(string source, int start, int end) {
            for (int index = start; index < end; index++) {
                if (!char.IsWhiteSpace(source[index])) {
                    return false;
                }
            }

            return true;
        }

