            return "<none>";
        }

        string trimmed = value.Trim();
        if (IsUnsafe(trimmed)) {
            return "<redacted>";
        }

        return trimmed.Length > 96 ? trimmed.Substring(0, 96) + "<truncated>" : trimmed;
    }

internal static string NormalizePath(string path) {
        if (string.IsNullOrWhiteSpace(path) || path == "<none>") {
            return "<none>";
        }

        string normalized = path.Replace('\\', '/');
        bool isAbsolute = LooksLikeWindowsDriveRoot(normalized) || normalized.StartsWith("/", StringComparison.Ordinal);
        if (isAbsolute) {
            int lastSlash = normalized.LastIndexOf('/');
            if (lastSlash < 0 || lastSlash + 1 >= normalized.Length) {
                return "<outside-project>";
            }

            normalized = normalized.Substring(lastSlash + 1);
        }
        else {
            normalized = normalized.TrimStart('/');
        }

        return string.IsNullOrWhiteSpace(normalized) ? "<none>" : normalized;
    }

private static bool ContainsAbsolutePath(string value) {
        // Windows drive root with forward OR backslash: a single ASCII letter, then ':',
        // then '\\' or '/'. The letter MUST sit at the start of `value` or after a non-
        // letter character so we don't misclassify URL schemes like "https://" — there
        // the 's' in "s:/" is preceded by a letter and is therefore part of the scheme,
        // not a drive root.
        for (int i = 0; i + 2 < value.Length; i++) {
            char c0 = value[i];
            if (c0 is not ((>= 'A' and <= 'Z') or (>= 'a' and <= 'z'))) {
                continue;
            }

            if (value[i + 1] != ':') {
                continue;
            }

            char sep = value[i + 2];
            if (sep is not '\\' and not '/') {
                continue;
            }

            char preceding = i == 0 ? ' ' : value[i - 1];
            if (!char.IsLetter(preceding)) {
                return true;
            }
        }

        return value.IndexOf("C__", StringComparison.OrdinalIgnoreCase) >= 0;
    }

private DriftOptions(
        bool enabled,
        string? configuredBaselinePath,
        int maxDiagnostics,
        int maxBaselineBytes,
        bool trimOrAotAdvisoryEnabled,
        DiagnosticSeverity driftSeverity) {
        Enabled = enabled;
        ConfiguredBaselinePath = configuredBaselinePath;
        MaxDiagnostics = maxDiagnostics;
        MaxBaselineBytes = maxBaselineBytes;
        TrimOrAotAdvisoryEnabled = trimOrAotAdvisoryEnabled;
        DriftSeverity = driftSeverity;
    }

internal static DriftOptionsResult Bind(AnalyzerConfigOptionsProvider provider) {
        AnalyzerConfigOptions options = provider.GlobalOptions;
        ImmutableArray<DriftDiagnosticFact>.Builder diagnostics = ImmutableArray.CreateBuilder<DriftDiagnosticFact>();

        bool enabled = TryReadBool(options, "build_property.HfcDriftDetectionEnabled")
            ?? TryReadBool(options, "build_property.FrontComposerDriftDetectionEnabled")
            ?? false;
        bool trimOrAotAdvisoryEnabled =
            (TryReadBool(options, "build_property.PublishTrimmed") ?? false)
            || (TryReadBool(options, "build_property.PublishAot") ?? false);

        string? configuredBaselinePath = TryReadString(options, "build_property.HfcDriftBaselinePath");

        int maxDiagnostics = ReadPositiveInt(
            options,
            "build_property.HfcDriftMaxDiagnostics",
            DriftConstants.DefaultMaxDiagnostics,
            minInclusive: 1,
            maxInclusive: 500,
            diagnostics);

        int maxBaselineBytes = ReadPositiveInt(
            options,
            "build_property.HfcDriftMaxBaselineBytes",
            DriftConstants.DefaultMaxBaselineBytes,
            minInclusive: 1,
            maxInclusive: 10 * 1024 * 1024,
            diagnostics);

        DiagnosticSeverity severity = DiagnosticSeverity.Warning;
        string? severityValue = TryReadString(options, "build_property.HfcDriftSeverity");
        if (severityValue is not null) {
            if (string.Equals(severityValue, "Warning", StringComparison.OrdinalIgnoreCase)) {
                severity = DiagnosticSeverity.Warning;
            }
            else if (string.Equals(severityValue, "Error", StringComparison.OrdinalIgnoreCase)) {
                severity = DiagnosticSeverity.Error;
            }
            else if (string.Equals(severityValue, "Info", StringComparison.OrdinalIgnoreCase)
                || string.Equals(severityValue, "Information", StringComparison.OrdinalIgnoreCase)) {
                severity = DiagnosticSeverity.Info;
            }
            else {
                diagnostics.Add(DriftDiagnosticFact.Configuration(
                    "HfcDriftSeverity",
                    "Warning, Error, or Info",
                    severityValue));
            }
        }

        return new DriftOptionsResult(
            new DriftOptions(
                enabled,
                configuredBaselinePath,
                maxDiagnostics,
                maxBaselineBytes,
                trimOrAotAdvisoryEnabled,
                severity),
            diagnostics.ToImmutable());
    }

private static int ReadPositiveInt(
        AnalyzerConfigOptions options,
        string key,
        int defaultValue,
        int minInclusive,
        int maxInclusive,
        ImmutableArray<DriftDiagnosticFact>.Builder diagnostics) {
        string? raw = TryReadString(options, key);
        if (raw is null) {
            return defaultValue;
        }

        // Story 9-1 P25: NumberStyles.Integer accepts a leading sign, so we explicitly enforce
        // the [minInclusive, maxInclusive] range below. NumberStyles.None previously rejected
        // valid signed forms ("+50") with a confusing diagnostic.
        if (int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed)
            && parsed >= minInclusive
            && parsed <= maxInclusive) {
            return parsed;
        }

        int lastDot = key.LastIndexOf('.');
        string optionDisplayName = lastDot >= 0 && lastDot + 1 < key.Length
            ? key.Substring(lastDot + 1)
            : key;
        diagnostics.Add(DriftDiagnosticFact.Configuration(
            optionDisplayName,
            minInclusive.ToString(CultureInfo.InvariantCulture) + ".." + maxInclusive.ToString(CultureInfo.InvariantCulture),
            raw));
        return defaultValue;
    }

private static bool? TryReadBool(AnalyzerConfigOptions options, string key) {
        string? raw = TryReadString(options, key);
        if (raw is null) {
            return null;
        }

        if (string.Equals(raw, "true", StringComparison.OrdinalIgnoreCase)) {
            return true;
        }

        if (string.Equals(raw, "false", StringComparison.OrdinalIgnoreCase)) {
            return false;
        }

        return null;
    }

private static string? TryReadString(AnalyzerConfigOptions options, string key) {
        // Story 9-1 P24: previously returned "" for both whitespace-only AND missing values
        // mixed with `null` for some paths, which caused empty <HfcDriftBaselinePath/>
        // properties to be treated as configured (and trigger a spurious HFC1059). Treat any
        // whitespace-only or absent value as "not configured" (null).
        if (!options.TryGetValue(key, out string? value)) {
            return null;
        }

        string trimmed = value?.Trim() ?? string.Empty;
        return trimmed.Length == 0 ? null : trimmed;
    }

internal Diagnostic ToDiagnostic(Compilation? compilation = null) {
        DiagnosticDescriptor descriptor = DriftDiagnosticDescriptors.GetDescriptor(Id, Severity);
        Location location = ToLocation(compilation);
        ImmutableDictionary<string, string?> properties = ImmutableDictionary<string, string?>.Empty
            .Add("BaselinePath", BaselinePath)
            .Add("DeclarationPath", DeclarationPath)
            .Add("DeclarationName", DeclarationName)
            .Add("MemberName", MemberName)
            .Add("DriftKind", DriftKind)
            .Add("ExpectedShapeHash", ExpectedShapeHash)
            .Add("ActualShapeHash", ActualShapeHash)
            .Add("SchemaVersion", SchemaVersion)
            .Add("AlgorithmVersion", AlgorithmVersion)
            .Add("BoundedContext", BoundedContext);

        return Diagnostic.Create(descriptor, location, properties, Message);
    }

internal static DriftDiagnosticFact Structural(
        string driftKind,
        DriftBaselineContract? baseline,
        DriftCurrentContract? current,
        string? memberName,
        string message,
        DiagnosticSeverity severity) {
        string boundedContext = current?.BoundedContext ?? baseline?.BoundedContext ?? "<none>";
        string declarationName = current?.Type ?? baseline?.Type ?? "<none>";
        string baselinePath = baseline?.SourcePath ?? "<none>";
        string declarationPath = current?.SourcePath ?? "<none>";
        // Story 9-1 P19: include schema+algorithm in hash material AND emit explicit
        // <none> sentinels for null sides so an "added declaration" and a "removed
        // declaration" hashing the same memberName cannot collide.
        string expectedHash = Hash(ComposeHashInput(
            baseline?.Type ?? "<none>",
            baseline?.BoundedContext ?? "<none>",
            memberName ?? "<none>",
            driftKind,
            discriminator: "expected"));
        string actualHash = Hash(ComposeHashInput(
            current?.Type ?? "<none>",
            current?.BoundedContext ?? "<none>",
            memberName ?? "<none>",
            driftKind,
            discriminator: "actual"));
        string sortKey = boundedContext + "|" + (current?.Family ?? baseline?.Family ?? "<none>") + "|" + declarationName + "|" + (memberName ?? "<none>") + "|" + driftKind;
        return new DriftDiagnosticFact(
            DriftConstants.StructuralDriftId,
            severity,
            DriftSanitizer.SafeMessage(message),
            DriftSanitizer.Safe(boundedContext),
            DriftSanitizer.Safe(declarationName),
            DriftSanitizer.Safe(memberName ?? "<none>"),
            driftKind,
            DriftSanitizer.NormalizePath(baselinePath),
            DriftSanitizer.NormalizePath(declarationPath),
            expectedHash,
            actualHash,
            DriftConstants.SchemaVersion,
            DriftConstants.Algorithm,
            sortKey,
            current?.SourcePath ?? string.Empty,
            current?.SourceLine ?? -1,
            current?.SourceColumn ?? -1);
    }

private Location ToLocation(Compilation? compilation) {
        if (string.IsNullOrWhiteSpace(SourcePath) || SourceLine < 0 || SourceColumn < 0) {
            return Location.None;
        }

        if (compilation is not null) {
            // Story 9-1 P21: Windows file paths compare case-insensitively; using ordinal
            // here used to leak through to the LinePosition fallback when adopters' build
            // produced a mixed-case `tree.FilePath`, which then leaked an absolute path into
            // IDE diagnostics.
            StringComparison pathComparison = System.IO.Path.DirectorySeparatorChar == '\\'
                ? StringComparison.OrdinalIgnoreCase
                : StringComparison.Ordinal;
            foreach (SyntaxTree tree in compilation.SyntaxTrees) {
                if (!string.Equals(tree.FilePath, SourcePath, pathComparison)) {
                    continue;
                }

                SourceText text = tree.GetText();
                if (SourceLine < text.Lines.Count) {
                    TextLine line = text.Lines[SourceLine];
                    int absolutePosition = Math.Min(line.End, line.Start + SourceColumn);
                    return Location.Create(tree, new TextSpan(absolutePosition, 0));
                }
            }
        }

        // Story 9-1 P21: sanitize the SourcePath before embedding it in Location.Create —
        // otherwise the absolute path leaks into IDE diagnostics, bypassing the message-level
        // sanitization. NormalizePath reduces absolute paths to filename / `<outside-project>`.
        string sanitizedPath = DriftSanitizer.NormalizePath(SourcePath);
        LinePosition position = new(SourceLine, SourceColumn);
        return Location.Create(sanitizedPath, new TextSpan(0, 0), new LinePositionSpan(position, position));
    }

private static string Hash(string? input) {
        SHA256 sha = Sha256Pool.Value!;
        byte[] bytes = Encoding.UTF8.GetBytes(input ?? "<none>");
        byte[] hash = sha.ComputeHash(bytes);
        StringBuilder sb = new(hash.Length * 2);
        foreach (byte b in hash) {
            _ = sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
        }

        return sb.ToString();
    }

internal static DriftCurrentSnapshot From(
        ImmutableArray<ParseResult> projections,
        ImmutableArray<CommandParseResult> commands) {
        ImmutableArray<DriftCurrentContract>.Builder contracts = ImmutableArray.CreateBuilder<DriftCurrentContract>();

        foreach (ParseResult result in projections) {
            if (result.Model is not DomainModel model) {
                continue;
            }

            ImmutableArray<DriftCurrentProperty>.Builder properties = ImmutableArray.CreateBuilder<DriftCurrentProperty>();
            foreach (PropertyModel property in model.Properties) {
                properties.Add(new DriftCurrentProperty(
                    property.Name,
                    property.TypeName,
                    property.IsNullable,
                    null,
                    property.DisplayName,
                    property.Description,
                    property.ColumnPriority,
                    property.FieldGroup,
                    // Story 9-1 P-D3: serialize Default as null so a baseline missing the
                    // displayFormat field aligns with a current property using Default.
                    property.DisplayFormat == FieldDisplayFormat.Default ? null : property.DisplayFormat.ToString(),
                    property.RelativeTimeWindowDays,
                    BuildBadgeSignature(property.BadgeMappings)));
            }

            contracts.Add(new DriftCurrentContract(
                "projection",
                QualifiedType(model.Namespace, model.TypeName),
                model.BoundedContext ?? string.Empty,
                model.DisplayName,
                model.DisplayGroupName,
                model.ProjectionRole,
                null,
                null,
                null,
                model.EmptyStateCtaCommandTypeName,
                properties.ToImmutable(),
                model.SourceFilePath,
                model.SourceLine,
                model.SourceColumn));
        }

        foreach (CommandParseResult result in commands) {
            if (result.Model is not CommandModel model) {
                continue;
            }

            ImmutableArray<DriftCurrentProperty>.Builder properties = ImmutableArray.CreateBuilder<DriftCurrentProperty>();
            HashSet<string> derivable = new(model.DerivableProperties.Select(static p => p.Name), StringComparer.Ordinal);
            foreach (PropertyModel property in model.Properties) {
                properties.Add(new DriftCurrentProperty(
                    property.Name,
                    property.TypeName,
                    property.IsNullable,
                    derivable.Contains(property.Name),
                    property.DisplayName,
                    property.Description,
                    property.ColumnPriority,
                    property.FieldGroup,
                    property.DisplayFormat == FieldDisplayFormat.Default ? null : property.DisplayFormat.ToString(),
                    property.RelativeTimeWindowDays,
                    BuildBadgeSignature(property.BadgeMappings)));
            }

            // Story 9-1 P22: thread CommandModel source path/line/column so command drift
            // diagnostics get IDE squiggles like projection drift does.
            contracts.Add(new DriftCurrentContract(
                "command",
                QualifiedType(model.Namespace, model.TypeName),
                model.BoundedContext ?? string.Empty,
                model.DisplayName,
                null,
                null,
                model.IconName,
                model.IsDestructive,
                model.AuthorizationPolicyName,
                emptyStateCtaCommandTypeName: null,
                properties.ToImmutable(),
                model.SourceFilePath,
                model.SourceLine,
                model.SourceColumn));
        }

        return new DriftCurrentSnapshot(contracts.ToImmutable());
    }

private static string? BuildBadgeSignature(EquatableArray<BadgeMappingEntry> mappings) {
        if (mappings.Count == 0) {
            return null;
        }

        List<string> entries = new(mappings.Count);
        foreach (BadgeMappingEntry entry in mappings) {
            entries.Add(entry.EnumMemberName + "=" + entry.Slot);
        }

        entries.Sort(StringComparer.Ordinal);
        return string.Join(",", entries);
    }

internal static DriftComparisonResult Compare(
        DriftCurrentSnapshot current,
        DriftBaselineSet baseline,
        int maxDiagnostics,
        DiagnosticSeverity severity) {
        ImmutableArray<DriftDiagnosticFact>.Builder facts = ImmutableArray.CreateBuilder<DriftDiagnosticFact>();
        Dictionary<string, DriftCurrentContract> currentByType = new(StringComparer.Ordinal);
        foreach (DriftCurrentContract contract in current.Contracts) {
            currentByType[contract.IdentityWithoutContext] = contract;
        }

        HashSet<string> baselineKeys = new(StringComparer.Ordinal);
        foreach (DriftBaselineContract baselineContract in baseline.Contracts) {
            _ = baselineKeys.Add(baselineContract.IdentityWithoutContext);
            if (!currentByType.TryGetValue(baselineContract.IdentityWithoutContext, out DriftCurrentContract? currentContract)) {
                facts.Add(DriftDiagnosticFact.Structural(
                    "RemovedDeclaration",
                    baselineContract,
                    null,
                    null,
                    "What: structural drift removed declaration. Expected: declaration " + DriftSanitizer.Safe(baselineContract.Type) + ". Got: declaration not found. Fix: restore the declaration or update the checked-in generated UI baseline. DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                    severity));
                continue;
            }

            CompareContract(baselineContract, currentContract, severity, facts);
        }

        foreach (DriftCurrentContract currentContract in current.Contracts) {
            if (baselineKeys.Contains(currentContract.IdentityWithoutContext)) {
                continue;
            }

            facts.Add(DriftDiagnosticFact.Structural(
                "AddedDeclaration",
                null,
                currentContract,
                null,
                "What: structural drift added declaration " + DriftSanitizer.Safe(currentContract.Type) + ". Expected: declaration from baseline. Got: new generated UI declaration. Fix: update the checked-in generated UI baseline if intentional. DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                severity));
        }

        var sorted = facts
            .OrderBy(static f => f.SortKey, StringComparer.Ordinal)
            .ToImmutableArray();

        if (sorted.Length <= maxDiagnostics) {
            return new DriftComparisonResult(sorted);
        }

        ImmutableArray<DriftDiagnosticFact>.Builder capped = ImmutableArray.CreateBuilder<DriftDiagnosticFact>();
        capped.AddRange(sorted.Take(maxDiagnostics));
        capped.Add(DriftDiagnosticFact.Truncation(sorted.Length - maxDiagnostics));
        return new DriftComparisonResult(capped.ToImmutable());
    }

private static void CompareContract(
        DriftBaselineContract baseline,
        DriftCurrentContract current,
        DiagnosticSeverity severity,
        ImmutableArray<DriftDiagnosticFact>.Builder facts) {
        if (!string.Equals(baseline.BoundedContext, current.BoundedContext, StringComparison.Ordinal)) {
            facts.Add(DriftDiagnosticFact.Structural(
                "BoundedContextChanged",
                baseline,
                current,
                null,
                "What: bounded context drift on " + DriftSanitizer.Safe(current.Type) + ". Expected: " + DriftSanitizer.Safe(baseline.BoundedContext) + ". Got: " + DriftSanitizer.Safe(current.BoundedContext) + ". Fix: reconcile the generated UI baseline; navigation grouping, generated registration, persisted session grouping, MCP resource grouping, and badge/action queue grouping may be affected. DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                severity));
        }

        CompareContractMetadata(baseline, current, severity, facts);

        var baselineProperties = baseline.Properties.ToDictionary(static p => p.Name, StringComparer.Ordinal);
        var currentProperties = current.Properties.ToDictionary(static p => p.Name, StringComparer.Ordinal);
        List<DriftBaselineProperty> removed = [.. baseline.Properties.Where(p => !currentProperties.ContainsKey(p.Name))];
        List<DriftCurrentProperty> added = [.. current.Properties.Where(p => !baselineProperties.ContainsKey(p.Name))];

        if (removed.Count == 1
            && added.Count == 1
            && string.Equals(removed[0].Category, added[0].Category, StringComparison.Ordinal)) {
            string id = DriftConstants.StructuralDriftId;
            string message = "Property '" + DriftSanitizer.Safe(removed[0].Name) + "' was expected on " + DriftSanitizer.Safe(baseline.Type) + " but not found. '" + DriftSanitizer.Safe(added[0].Name) + "' was added. If this is a rename, update the generated output. See " + id + ". Expected: " + DriftSanitizer.Safe(removed[0].Category) + ". Got: " + DriftSanitizer.Safe(added[0].Category) + ". Fix: update the checked-in generated UI baseline. DocsLink: " + Docs(id);
            facts.Add(DriftDiagnosticFact.Structural("Rename", baseline, current, added[0].Name, message, severity));
        }
        else {
            foreach (DriftBaselineProperty property in removed) {
                facts.Add(DriftDiagnosticFact.Structural(
                    "RemovedProperty",
                    baseline,
                    current,
                    property.Name,
                    "What: structural drift removed property. Expected: property '" + DriftSanitizer.Safe(property.Name) + "' on " + DriftSanitizer.Safe(baseline.Type) + ". Got: property not found. Fix: restore the member or update the checked-in generated UI baseline. Affected surface: " + SurfaceFor(baseline.Family, property.Category) + ". DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                    severity));
            }

            foreach (DriftCurrentProperty property in added) {
                facts.Add(DriftDiagnosticFact.Structural(
                    "AddedProperty",
                    baseline,
                    current,
                    property.Name,
                    "What: structural drift added property. Expected: no property '" + DriftSanitizer.Safe(property.Name) + "' in baseline. Got: property added on " + DriftSanitizer.Safe(current.Type) + ". Fix: update the checked-in generated UI baseline if intentional. Affected surface: " + SurfaceFor(current.Family, property.Category) + ". DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                    severity));
            }
        }

        foreach (KeyValuePair<string, DriftBaselineProperty> kvp in baselineProperties.OrderBy(static p => p.Key, StringComparer.Ordinal)) {
            if (!currentProperties.TryGetValue(kvp.Key, out DriftCurrentProperty? currentProperty)) {
                continue;
            }

            CompareProperty(baseline, current, kvp.Value, currentProperty, severity, facts);
        }
    }

private static void CompareContractMetadata(
        DriftBaselineContract baseline,
        DriftCurrentContract current,
        DiagnosticSeverity severity,
        ImmutableArray<DriftDiagnosticFact>.Builder facts) {
        AddIfChanged("Display.Name", baseline.DisplayName, current.DisplayName);
        AddIfChanged("Display.GroupName", baseline.DisplayGroupName, current.DisplayGroupName);
        AddIfChanged("ProjectionRole", baseline.Role, current.Role);
        AddIfChanged("Icon", baseline.Icon, current.Icon);
        AddIfChanged("RequiresPolicy", baseline.RequiresPolicy, current.RequiresPolicy);
        // Story 9-1 P6 (AC7): empty-state CTA drift is contract-level metadata.
        AddIfChanged("ProjectionEmptyStateCta", baseline.EmptyStateCtaCommandTypeName, current.EmptyStateCtaCommandTypeName);

        // Story 9-1 P9: symmetric Destructive comparison. Previously fired only when
        // baseline.Destructive was non-null, so adding a [Destructive] flag against a null
        // baseline (a fresh declaration becoming destructive) was silently ignored.
        if (baseline.Destructive != current.Destructive) {
            facts.Add(DriftDiagnosticFact.Metadata(
                "Destructive",
                baseline,
                current,
                null,
                "What: metadata drift changed Destructive on " + DriftSanitizer.Safe(current.Type)
                    + ". Expected: " + (baseline.Destructive?.ToString(CultureInfo.InvariantCulture) ?? "<none>")
                    + ". Got: " + (current.Destructive?.ToString(CultureInfo.InvariantCulture) ?? "<none>")
                    + ". Fix: update source metadata or the checked-in generated UI baseline. DocsLink: " + Docs(DriftConstants.MetadataDriftId),
                severity));
        }

        void AddIfChanged(string kind, string? expected, string? got) {
            // Story 9-1 P9: drop the `expected is null` short-circuit. A null→value transition
            // (new metadata added in source against a null baseline) IS drift; AC7 must alert
            // on metadata addition, not just removal/change.
            if (string.Equals(expected, got, StringComparison.Ordinal)) {
                return;
            }

            facts.Add(DriftDiagnosticFact.Metadata(
                kind,
                baseline,
                current,
                null,
                "What: metadata drift changed " + kind + " on " + DriftSanitizer.Safe(current.Type)
                    + ". Expected: " + DriftSanitizer.Safe(expected ?? "<none>")
                    + ". Got: " + DriftSanitizer.Safe(got ?? "<none>")
                    + ". Fix: update source metadata or the checked-in generated UI baseline. DocsLink: " + Docs(DriftConstants.MetadataDriftId),
                severity));
        }
    }

private static void CompareProperty(
        DriftBaselineContract baseline,
        DriftCurrentContract current,
        DriftBaselineProperty expected,
        DriftCurrentProperty got,
        DiagnosticSeverity severity,
        ImmutableArray<DriftDiagnosticFact>.Builder facts) {
        if (!string.Equals(expected.Category, got.Category, StringComparison.Ordinal)) {
            facts.Add(DriftDiagnosticFact.Structural(
                "TypeCategoryChanged",
                baseline,
                current,
                got.Name,
                "What: structural drift changed property category for '" + DriftSanitizer.Safe(got.Name) + "'. Expected: " + DriftSanitizer.Safe(expected.Category) + ". Got: " + DriftSanitizer.Safe(got.Category) + ". Fix: update source or reconcile the checked-in generated UI baseline. Affected surface: " + SurfaceFor(current.Family, got.Category) + ", form input, DataGrid column, filter, badge/format, MCP descriptor metadata, currency formatting. DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                severity));
        }

        if (expected.Nullable != got.Nullable) {
            string hint = expected.Nullable && !got.Nullable ? "required/breaking/tightened" : "nullable";
            facts.Add(DriftDiagnosticFact.Structural(
                "NullabilityChanged",
                baseline,
                current,
                got.Name,
                "What: structural drift changed nullability for '" + DriftSanitizer.Safe(got.Name) + "'. Expected: nullable=" + expected.Nullable.ToString(CultureInfo.InvariantCulture) + ". Got: nullable=" + got.Nullable.ToString(CultureInfo.InvariantCulture) + " (" + hint + "). Fix: update source or reconcile the checked-in generated UI baseline. Affected surface: form input, DataGrid column, filter behavior, MCP descriptor metadata. DocsLink: " + Docs(DriftConstants.StructuralDriftId),
                severity));
        }

        AddMetadataIfChanged("Display.Name", expected.DisplayName, got.DisplayName);
        AddMetadataIfChanged("Description", expected.Description, got.Description);
        AddMetadataIfChanged("ColumnPriority", expected.ColumnPriority?.ToString(CultureInfo.InvariantCulture), got.ColumnPriority?.ToString(CultureInfo.InvariantCulture));

        // Story 9-1 P20: previously emitted both ProjectionFieldGroup AND Display.GroupName for
        // the same source change, doubling the diagnostic count toward the 50-cap. Single
        // diagnostic now carries both surface labels in the message text.
        if (!string.Equals(expected.FieldGroup, got.FieldGroup, StringComparison.Ordinal)) {
            facts.Add(DriftDiagnosticFact.Metadata(
                "ProjectionFieldGroup",
                baseline,
                current,
                got.Name,
                "What: metadata drift changed ProjectionFieldGroup for '" + DriftSanitizer.Safe(got.Name)
                    + "' on " + DriftSanitizer.Safe(current.Type)
                    + ". Expected: " + DriftSanitizer.Safe(expected.FieldGroup ?? "<none>")
                    + ". Got: " + DriftSanitizer.Safe(got.FieldGroup ?? "<none>")
                    + ". Fix: update source metadata or reconcile the checked-in generated UI baseline. Affected surface: ProjectionFieldGroup, Display.GroupName, DataGrid grouping, detail field, MCP descriptor metadata. DocsLink: " + Docs(DriftConstants.MetadataDriftId),
                severity));
        }

        AddMetadataIfChanged("DisplayFormat", expected.DisplayFormat, got.DisplayFormat);

        // Story 9-1 P6 (AC7): drift coverage for relative-time window and badge mappings.
        AddMetadataIfChanged(
            "RelativeTime",
            expected.RelativeTimeWindowDays?.ToString(CultureInfo.InvariantCulture),
            got.RelativeTimeWindowDays?.ToString(CultureInfo.InvariantCulture));
        AddMetadataIfChanged("ProjectionBadge", expected.BadgeSignature, got.BadgeSignature);

        // Story 9-1 P9: symmetric Derivable comparison.
        if (expected.Derivable != got.Derivable) {
            AddMetadata(
                "Derivable",
                expected.Derivable?.ToString(CultureInfo.InvariantCulture) ?? "<none>",
                got.Derivable?.ToString(CultureInfo.InvariantCulture) ?? "<none>");
        }

        void AddMetadataIfChanged(string kind, string? expectedValue, string? gotValue) {
            // Story 9-1 P9: drop the `expectedValue is null` short-circuit.
            if (string.Equals(expectedValue, gotValue, StringComparison.Ordinal)) {
                return;
            }

            AddMetadata(kind, expectedValue, gotValue);
        }

        void AddMetadata(string kind, string? expectedValue, string? gotValue) => facts.Add(DriftDiagnosticFact.Metadata(
                kind,
                baseline,
                current,
                got.Name,
                "What: metadata drift changed " + kind + " for '" + DriftSanitizer.Safe(got.Name) + "' on " + DriftSanitizer.Safe(current.Type) + ". Expected: " + DriftSanitizer.Safe(expectedValue ?? "<none>") + ". Got: " + DriftSanitizer.Safe(gotValue ?? "<none>") + ". Fix: update source metadata or reconcile the checked-in generated UI baseline. Affected surface: renderer-impacting metadata, DataGrid, detail, MCP descriptor metadata. DocsLink: " + Docs(DriftConstants.MetadataDriftId),
                severity));
    }

private static string SurfaceFor(string family, string category) {
        if (family == "command") {
            return "generated form input and command registration";
        }

        if (category is "Collection" or "Unsupported") {
            return "unsupported placeholder, detail field, and MCP projection field metadata";
        }

        if (category == "Enum") {
            return "DataGrid column, filter behavior, badge/format behavior, detail field, and MCP projection field metadata";
        }

        if (category.Contains("Date", StringComparison.Ordinal) || category.Contains("Time", StringComparison.Ordinal)) {
            return "DataGrid column, detail field, filter behavior, format behavior, and MCP projection field metadata";
        }

        return "DataGrid column, detail field, filter behavior, and MCP projection field metadata";
    }

internal static DriftBaselineLoadResult Load(ImmutableArray<DriftBaselineInput> inputs, DriftOptions options) {
        ImmutableArray<DriftDiagnosticFact>.Builder diagnostics = ImmutableArray.CreateBuilder<DriftDiagnosticFact>();
        ImmutableArray<DriftBaselineContract>.Builder contracts = ImmutableArray.CreateBuilder<DriftBaselineContract>();

        var sorted = inputs
            .OrderBy(static i => i.Path, StringComparer.Ordinal)
            .ToImmutableArray();

        // Story 9-1 P8: when ConfiguredBaselinePath is set, narrow the eligible baselines to
        // matching candidates. If none match, surface HFC1059 against the configured path (it
        // is a trust failure for the configured path only — but per AC9 we still fail-closed
        // because there is no other authoritative input).
        ImmutableArray<DriftBaselineInput> eligible = sorted;
        if (options.ConfiguredBaselinePath is not null) {
            eligible = sorted
                .Where(i => PathsEqual(options.ConfiguredBaselinePath, i.Path))
                .ToImmutableArray();
            if (eligible.Length == 0) {
                diagnostics.Add(DriftDiagnosticFact.InvalidBaselinePath(options.ConfiguredBaselinePath));
                return EmptyResult(diagnostics, options.MaxDiagnostics);
            }
        }

        if (eligible.Length == 0) {
            // Story 9-1 P3 (AC2): the baseline-load path emits HFC1058 unconditionally when
            // drift detection is enabled and no matching baseline exists. Higher up the stack
            // the orchestrator already gates on options.Enabled so this only runs in the
            // opt-in case.
            diagnostics.Add(DriftDiagnosticFact.MissingBaseline());
            return EmptyResult(diagnostics, options.MaxDiagnostics);
        }

        HashSet<string> contractIdentities = new(StringComparer.Ordinal);
        HashSet<string> unsafeValues = new(StringComparer.Ordinal);
        bool trustFailed = false;

        foreach (DriftBaselineInput input in eligible) {
            // Story 9-1 P10: count UTF-8 bytes, not chars — option name is MaxBaselineBytes.
            int byteCount = Encoding.UTF8.GetByteCount(input.Text);
            if (byteCount > options.MaxBaselineBytes) {
                diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                    DriftConstants.BaselineBoundsExceededId,
                    "oversized baseline",
                    "at most " + options.MaxBaselineBytes.ToString(CultureInfo.InvariantCulture) + " bytes",
                    byteCount.ToString(CultureInfo.InvariantCulture),
                    input.Path));
                trustFailed = true;
                continue;
            }

            if (string.IsNullOrWhiteSpace(input.Text)) {
                diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                    DriftConstants.InvalidBaselineContentId,
                    "empty baseline",
                    "valid JSON baseline content",
                    "empty or whitespace",
                    input.Path));
                trustFailed = true;
                continue;
            }

            // Story 9-1 P11: strip a leading UTF-8 BOM so editors that save with a BOM (very
            // common on Windows) do not produce HFC1060 against an otherwise valid baseline.
            string textForParse = StripUtf8Bom(input.Text);

            JsonDocument document;
            try {
                document = JsonDocument.Parse(textForParse);
            }
            catch (JsonException) {
                diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                    DriftConstants.InvalidBaselineContentId,
                    "malformed baseline",
                    "valid JSON baseline content",
                    "malformed JSON",
                    input.Path));
                trustFailed = true;
                continue;
            }

            using (document) {
                JsonElement root = document.RootElement;
                // Story 9-1 P12: trim+ordinal compare and clamp displayed `Got` values through
                // the sanitizer so untrusted JSON cannot leak into the diagnostic property bag.
                string schemaVersion = (ReadString(root, "schemaVersion") ?? string.Empty).Trim();
                string algorithm = (ReadString(root, "algorithm") ?? string.Empty).Trim();

                if (!string.Equals(schemaVersion, DriftConstants.SchemaVersion, StringComparison.Ordinal)) {
                    diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                        DriftConstants.UnsupportedSchemaId,
                        "unsupported schema version",
                        DriftConstants.SchemaVersion,
                        schemaVersion,
                        input.Path,
                        schemaVersion,
                        algorithm));
                    trustFailed = true;
                    continue;
                }

                if (!string.Equals(algorithm, DriftConstants.Algorithm, StringComparison.Ordinal)) {
                    diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                        DriftConstants.UnsupportedAlgorithmId,
                        "unsupported algorithm",
                        DriftConstants.Algorithm,
                        algorithm,
                        input.Path,
                        schemaVersion,
                        algorithm));
                    trustFailed = true;
                    continue;
                }

                if (!root.TryGetProperty("contracts", out JsonElement contractArray)
                    || contractArray.ValueKind != JsonValueKind.Array) {
                    diagnostics.Add(Invariant(input.Path, "contracts array is missing"));
                    trustFailed = true;
                    continue;
                }

                if (contractArray.GetArrayLength() > DriftConstants.DefaultMaxDeclarations) {
                    diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                        DriftConstants.BaselineBoundsExceededId,
                        "declaration count exceeded",
                        DriftConstants.DefaultMaxDeclarations.ToString(CultureInfo.InvariantCulture),
                        contractArray.GetArrayLength().ToString(CultureInfo.InvariantCulture),
                        input.Path));
                    trustFailed = true;
                    continue;
                }

                foreach (JsonElement contractElement in contractArray.EnumerateArray()) {
                    DriftBaselineContract? contract = ParseContract(input.Path, contractElement, unsafeValues, diagnostics);
                    if (contract is null) {
                        trustFailed = true;
                        continue;
                    }

                    if (!contractIdentities.Add(contract.IdentityWithContext)) {
                        diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                            DriftConstants.DuplicateOrInvariantId,
                            "duplicate identity",
                            "unique contract identity",
                            contract.Type,
                            input.Path));
                        trustFailed = true;
                        continue;
                    }

                    contracts.Add(contract);
                }
            }
        }

        if (unsafeValues.Count > 0) {
            diagnostics.Add(DriftDiagnosticFact.RedactionSuppressed());
            trustFailed = true;
        }

        // Story 9-1 P29: when trust failed, drop the partially-parsed contracts so the
        // fail-closed contract is self-evident — even though `ComparisonEnabled=false` already
        // halts comparison, leaving the half-populated set in `Baseline` was misleading.
        if (trustFailed) {
            return EmptyResult(diagnostics, options.MaxDiagnostics);
        }

        return new DriftBaselineLoadResult(
            true,
            new DriftBaselineSet(contracts.ToImmutable()),
            CapLoadDiagnostics(diagnostics, options.MaxDiagnostics));
    }

private static ImmutableArray<DriftDiagnosticFact> CapLoadDiagnostics(
        ImmutableArray<DriftDiagnosticFact>.Builder diagnostics,
        int maxDiagnostics) {
        if (diagnostics.Count <= maxDiagnostics) {
            return diagnostics.ToImmutable();
        }

        ImmutableArray<DriftDiagnosticFact>.Builder capped = ImmutableArray.CreateBuilder<DriftDiagnosticFact>();
        capped.AddRange(diagnostics.Take(maxDiagnostics));
        capped.Add(DriftDiagnosticFact.Truncation(diagnostics.Count - maxDiagnostics));
        return capped.ToImmutable();
    }

private static string StripUtf8Bom(string text) {
        if (text.Length > 0 && text[0] == '﻿') {
            return text.Substring(1);
        }

        // Defensive: also strip the literal BOM byte sequence if it survived as UTF-8 chars.
        if (text.Length >= Utf8Bom.Length
            && (byte)text[0] == Utf8Bom[0]
            && (byte)text[1] == Utf8Bom[1]
            && (byte)text[2] == Utf8Bom[2]) {
            return text.Substring(Utf8Bom.Length);
        }

        return text;
    }

private static DriftBaselineContract? ParseContract(
        string path,
        JsonElement contractElement,
        HashSet<string> unsafeValues,
        ImmutableArray<DriftDiagnosticFact>.Builder diagnostics) {
        string family = ReadString(contractElement, "family") ?? string.Empty;
        string type = ReadString(contractElement, "type") ?? string.Empty;
        string boundedContext = ReadString(contractElement, "boundedContext") ?? string.Empty;

        TrackUnsafe(family, unsafeValues);
        TrackUnsafe(type, unsafeValues);
        TrackUnsafe(boundedContext, unsafeValues);

        if ((family != "projection" && family != "command" && family != "boundedContext")
            || string.IsNullOrWhiteSpace(type)) {
            diagnostics.Add(Invariant(path, "contract invariant violation"));
            return null;
        }

        if (!contractElement.TryGetProperty("properties", out JsonElement propertyArray)
            || propertyArray.ValueKind != JsonValueKind.Array) {
            propertyArray = default;
        }

        ImmutableArray<DriftBaselineProperty>.Builder properties = ImmutableArray.CreateBuilder<DriftBaselineProperty>();
        // Story 9-1 P13: dedupe by OrdinalIgnoreCase so a baseline declaring both "Foo" and
        // "foo" is rejected as an invariant violation here (rather than allowed through to
        // CompareContract.ToDictionary(Ordinal) which would silently keep both, then risk a
        // case-collision crash if downstream consumers normalize names).
        HashSet<string> propertyNames = new(StringComparer.OrdinalIgnoreCase);
        if (propertyArray.ValueKind == JsonValueKind.Array) {
            if (propertyArray.GetArrayLength() > DriftConstants.DefaultMaxPropertiesPerDeclaration) {
                diagnostics.Add(DriftDiagnosticFact.TrustFailure(
                    DriftConstants.BaselineBoundsExceededId,
                    "property count exceeded",
                    DriftConstants.DefaultMaxPropertiesPerDeclaration.ToString(CultureInfo.InvariantCulture),
                    propertyArray.GetArrayLength().ToString(CultureInfo.InvariantCulture),
                    path));
                return null;
            }

            foreach (JsonElement propertyElement in propertyArray.EnumerateArray()) {
                string name = ReadString(propertyElement, "name") ?? string.Empty;
                string category = ReadString(propertyElement, "category") ?? string.Empty;
                bool nullable = ReadBool(propertyElement, "nullable") ?? false;

                TrackUnsafe(name, unsafeValues);
                TrackUnsafe(category, unsafeValues);
                TrackUnsafe(ReadString(propertyElement, "displayName"), unsafeValues);
                TrackUnsafe(ReadString(propertyElement, "description"), unsafeValues);
                TrackUnsafe(ReadString(propertyElement, "fieldGroup"), unsafeValues);
                TrackUnsafe(ReadString(propertyElement, "displayFormat"), unsafeValues);

                if (string.IsNullOrWhiteSpace(name)
                    || string.IsNullOrWhiteSpace(category)
                    || !propertyNames.Add(name)
                    || (TryReadInt(propertyElement, "columnPriority") is int priority && priority < 0)) {
                    diagnostics.Add(Invariant(path, "property invariant violation"));
                    return null;
                }

                // Story 9-1 P6 (AC7): canonical badge signature + relative-time window so
                // ProjectionBadge / RelativeTime metadata changes produce drift diagnostics.
                string? badgeSignature = ReadBadgeSignature(propertyElement);
                TrackUnsafe(badgeSignature, unsafeValues);

                properties.Add(new DriftBaselineProperty(
                    name,
                    category,
                    nullable,
                    ReadBool(propertyElement, "derivable"),
                    ReadString(propertyElement, "displayName"),
                    ReadString(propertyElement, "description"),
                    TryReadInt(propertyElement, "columnPriority"),
                    ReadString(propertyElement, "fieldGroup"),
                    ReadString(propertyElement, "displayFormat"),
                    TryReadInt(propertyElement, "relativeTimeWindowDays"),
                    badgeSignature));
            }
        }

        string? displayName = ReadString(contractElement, "displayName");
        string? displayGroupName = ReadString(contractElement, "displayGroupName");
        string? role = ReadString(contractElement, "role");
        string? icon = ReadString(contractElement, "icon");
        string? requiresPolicy = ReadString(contractElement, "requiresPolicy");
        string? emptyStateCta = ReadString(contractElement, "emptyStateCtaCommandTypeName");

        TrackUnsafe(displayName, unsafeValues);
        TrackUnsafe(displayGroupName, unsafeValues);
        TrackUnsafe(role, unsafeValues);
        TrackUnsafe(icon, unsafeValues);
        TrackUnsafe(requiresPolicy, unsafeValues);
        TrackUnsafe(emptyStateCta, unsafeValues);

        return new DriftBaselineContract(
            path,
            family,
            type,
            boundedContext,
            displayName,
            displayGroupName,
            role,
            icon,
            ReadBool(contractElement, "destructive"),
            requiresPolicy,
            emptyStateCta,
            properties.ToImmutable());
    }

private static string? ReadBadgeSignature(JsonElement propertyElement) {
        if (propertyElement.ValueKind != JsonValueKind.Object
            || !propertyElement.TryGetProperty("badges", out JsonElement badges)
            || badges.ValueKind != JsonValueKind.Array
            || badges.GetArrayLength() == 0) {
            return null;
        }

        List<string> entries = [];
        foreach (JsonElement badge in badges.EnumerateArray()) {
            string? enumMember = ReadString(badge, "enumMember");
            string? slot = ReadString(badge, "slot");
            if (string.IsNullOrEmpty(enumMember) || string.IsNullOrEmpty(slot)) {
                continue;
            }

            entries.Add(enumMember + "=" + slot);
        }

        if (entries.Count == 0) {
            return null;
        }

        entries.Sort(StringComparer.Ordinal);
        return string.Join(",", entries);
    }

private static string? ReadString(JsonElement element, string propertyName) {
        if (element.ValueKind == JsonValueKind.Object
            && element.TryGetProperty(propertyName, out JsonElement value)
            && value.ValueKind == JsonValueKind.String) {
            return value.GetString();
        }

        return null;
    }

private static bool? ReadBool(JsonElement element, string propertyName) {
        if (element.ValueKind != JsonValueKind.Object
            || !element.TryGetProperty(propertyName, out JsonElement value)) {
            return null;
        }

        return value.ValueKind switch {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => null,
        };
    }

private static int? TryReadInt(JsonElement element, string propertyName) {
        if (element.ValueKind == JsonValueKind.Object
            && element.TryGetProperty(propertyName, out JsonElement value)
            && value.ValueKind == JsonValueKind.Number
            && value.TryGetInt32(out int result)) {
            return result;
        }

        return null;
    }

private static bool PathsEqual(string configured, string candidate) {
        string normConfigured = PathCompareNormalize(configured);
        string normCandidate = PathCompareNormalize(candidate);
        if (string.Equals(normConfigured, normCandidate, StringComparison.OrdinalIgnoreCase)) {
            return true;
        }

        if (IsSegmentAlignedSuffix(normConfigured, normCandidate)) {
            return true;
        }

        return IsSegmentAlignedSuffix(normCandidate, normConfigured);
    }

private static bool IsSegmentAlignedSuffix(string longer, string shorter) {
        if (longer.Length <= shorter.Length) {
            return false;
        }

        if (!longer.EndsWith(shorter, StringComparison.OrdinalIgnoreCase)) {
            return false;
        }

        char boundary = longer[longer.Length - shorter.Length - 1];
        return boundary == '/';
    }

private static void TrackUnsafe(string? value, HashSet<string> unsafeValues) {
        if (value is not null && DriftSanitizer.IsUnsafe(value)) {
            _ = unsafeValues.Add(value);
        }
    }

internal static bool IsCandidate(string path) {
        // Story 9-1 P5 (T5): enforce the documented baseline naming contract. Previously every
        // *.json AdditionalText was treated as a candidate baseline, so an unrelated config file
        // would produce HFC1060/HFC1064 errors. Accepted prefixes mirror the schemaVersion
        // family ("frontcomposer.generated-ui-baseline*") and the historic short form
        // ("frontcomposer.drift-baseline*").
        string fileName = System.IO.Path.GetFileName(path);
        if (string.IsNullOrEmpty(fileName)) {
            return false;
        }

        if (!fileName.EndsWith(".json", StringComparison.OrdinalIgnoreCase)) {
            return false;
        }

        return fileName.StartsWith("frontcomposer.drift-baseline", StringComparison.OrdinalIgnoreCase)
            || fileName.StartsWith("frontcomposer.generated-ui-baseline", StringComparison.OrdinalIgnoreCase);
    }

internal static DriftBaselineInput FromAdditionalText(AdditionalText text, CancellationToken cancellationToken) {
        SourceText? source = text.GetText(cancellationToken);
        return new DriftBaselineInput(text.Path, source?.ToString() ?? string.Empty);
    }

public override int GetHashCode() {
        unchecked {
            return (StringComparer.Ordinal.GetHashCode(Path) * 397)
                ^ StringComparer.Ordinal.GetHashCode(Text);
        }
    }

public HotReloadRebuildClassification(bool requiresRebuild, string? diagnosticId, string message) {
        RequiresRebuild = requiresRebuild;
        DiagnosticId = diagnosticId;
        Message = message;
    }

public static HotReloadRebuildClassification Classify(CustomizationHotReloadChangeKind changeKind) {
        if (changeKind is CustomizationHotReloadChangeKind.RazorBodyEdit
            or CustomizationHotReloadChangeKind.CssOnlyEdit) {
            return new HotReloadRebuildClassification(
                requiresRebuild: false,
                diagnosticId: null,
                message: "Hot reload may apply this customization body/style edit when Blazor supports it.");
        }

        string got = ChangeKindLabel(changeKind);
        string message =
            "What: A customization edit changed metadata that the running app cannot safely refresh through hot reload.\n"
            + "Expected: Razor body and CSS-only edits may hot reload; marker metadata, contracts, descriptors, and registrations require rebuild validation.\n"
            + $"Got: {got}.\n"
            + "Fix: Stop the running app, rebuild the project, and restart so SourceTools and Shell registries agree on the descriptor set.\n"
            + "Fallback: Existing generated rendering remains the safe path until the rebuild completes.\n"
            + "DocsLink: https://hexalith.github.io/FrontComposer/diagnostics/HFC1010";

        return new HotReloadRebuildClassification(
            requiresRebuild: true,
            diagnosticId: "HFC1010",
            message: message);
    }

private static string ChangeKindLabel(CustomizationHotReloadChangeKind changeKind)
        => changeKind switch {
            CustomizationHotReloadChangeKind.MarkerMetadataChanged => "marker metadata changed",
            CustomizationHotReloadChangeKind.ExpectedContractVersionChanged => "expected contract version changed",
            CustomizationHotReloadChangeKind.GenericContextTypeChanged => "generic context type changed",
            CustomizationHotReloadChangeKind.DescriptorSchemaChanged => "descriptor schema changed",
            CustomizationHotReloadChangeKind.RegistrationAddedOrRemoved => "slot or view registration was added or removed",
            CustomizationHotReloadChangeKind.DuplicateRegistrationIntroduced => "duplicate registration was introduced",
            CustomizationHotReloadChangeKind.GeneratedManifestVersionMismatch => "generated manifest version mismatches the loaded framework contract",
            _ => changeKind.ToString(),
        };

private static readonly HashSet<string> RegistrationCallNames = new(StringComparer.Ordinal) {
        "AddProjectionTemplate",
        "AddSlotOverride",
        "AddViewOverride",
    };

public override void Initialize(AnalysisContext context) {
        context.ConfigureGeneratedCodeAnalysis(GeneratedCodeAnalysisFlags.None);
        context.EnableConcurrentExecution();
        context.RegisterCompilationStartAction(OnCompilationStart);
    }

private static void OnCompilationStart(CompilationStartAnalysisContext compilationContext) {
        // P16 — collect component types referenced from registration calls. The set is
        // mutated by SyntaxNodeAction passes (one per InvocationExpression) and read at
        // compilation end so the registration collection is complete before analysis.
        // ConcurrentDictionary keyed by SymbolEqualityComparer prevents key conflation
        // across nested generic instantiations.
        ConcurrentDictionary<INamedTypeSymbol, byte> referencedComponents =
            new(SymbolEqualityComparer.Default);

        compilationContext.RegisterSyntaxNodeAction(
            ctx => CollectRegistrationReferences(ctx, referencedComponents),
            SyntaxKind.InvocationExpression);

        compilationContext.RegisterSymbolAction(
            AnalyzeProjectionTemplateType,
            SymbolKind.NamedType);

        compilationContext.RegisterCompilationEndAction(
            ctx => AnalyzeRegisteredTypes(ctx, referencedComponents));
    }

private static void CollectRegistrationReferences(
        SyntaxNodeAnalysisContext context,
        ConcurrentDictionary<INamedTypeSymbol, byte> referencedComponents) {
        if (context.Node is not InvocationExpressionSyntax invocation) {
            return;
        }

        // Identify the simple method name without resolving the symbol when the name does
        // not match — this short-circuits the vast majority of invocations cheaply.
        string? methodName = ExtractSimpleName(invocation.Expression);
        if (methodName is null || !RegistrationCallNames.Contains(methodName)) {
            return;
        }

        if (context.SemanticModel.GetSymbolInfo(invocation, context.CancellationToken).Symbol
            is not IMethodSymbol method) {
            return;
        }

        // The component type is the LAST type argument: AddProjectionTemplate<TComponent>,
        // AddSlotOverride<TProjection, TField, TComponent>, AddViewOverride<TProjection, TComponent>.
        if (method.TypeArguments.Length == 0) {
            return;
        }

        if (method.TypeArguments[method.TypeArguments.Length - 1] is INamedTypeSymbol componentType) {
            _ = referencedComponents.TryAdd(componentType, 0);
        }
    }

private static string? ExtractSimpleName(ExpressionSyntax expression) => expression switch {
        MemberAccessExpressionSyntax member => member.Name.Identifier.ValueText,
        IdentifierNameSyntax identifier => identifier.Identifier.ValueText,
        GenericNameSyntax generic => generic.Identifier.ValueText,
        _ => null,
    };

private static void AnalyzeProjectionTemplateType(SymbolAnalysisContext context) {
        var type = (INamedTypeSymbol)context.Symbol;
        if (!HasProjectionTemplateAttribute(type)) {
            return;
        }

        AnalyzeType(type, context.CancellationToken, context.ReportDiagnostic);
    }

private static void AnalyzeRegisteredTypes(
        CompilationAnalysisContext context,
        ConcurrentDictionary<INamedTypeSymbol, byte> referencedComponents) {
        foreach (INamedTypeSymbol type in referencedComponents.Keys) {
            if (HasProjectionTemplateAttribute(type)) {
                continue;
            }

            AnalyzeType(type, context.CancellationToken, context.ReportDiagnostic);
        }
    }

private static void AnalyzeType(
        INamedTypeSymbol type,
        CancellationToken cancellationToken,
        Action<Diagnostic> report) {
        string? source = GetDeclaredSource(type, cancellationToken);
        if (source is null || source.Length == 0) {
            return;
        }

        Location location = type.Locations.Length > 0 && type.Locations[0] != Location.None
            ? type.Locations[0]
            : Location.None;
        bool hasClick = Contains(source, "\"onclick\"") || Contains(source, "'onclick'");
        bool hasAccessibleName = Contains(source, "\"aria-label\"")
            || Contains(source, "\"aria-labelledby\"")
            || Contains(source, "\"title\"")
            || Contains(source, ".AddContent(");

        if (hasClick && !hasAccessibleName) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationAccessibleNameMissing,
                location,
                what: "A customization component renders an interactive element without an accessible name.",
                expected: "Interactive override roots expose visible text, aria-label, aria-labelledby, or an equivalent static name.",
                got: "The statically inspectable render tree adds an onclick handler but no name-bearing attribute or content.",
                fix: "Add visible text or an aria-label/aria-labelledby attribute to the interactive element.",
                docsId: "HFC1050");
        }

        if (Contains(source, "\"tabindex\", -1") || Contains(source, "\"tabindex\", \"-1\"")) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationKeyboardReachabilityIssue,
                location,
                what: "A customization component removes the only obvious keyboard path from an interactive element.",
                expected: "Clickable custom override elements stay keyboard reachable.",
                got: "The statically inspectable render tree sets tabindex=-1.",
                fix: "Remove tabindex=-1 or provide a reachable keyboard control.",
                docsId: "HFC1051");
        }

        if ((Contains(source, "outline: none") || Contains(source, "box-shadow: none")) && !Contains(source, "focus-visible")) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationFocusVisibilitySuppressed,
                location,
                what: "A customization component suppresses visible focus styling.",
                expected: "Custom override CSS preserves or replaces visible keyboard focus.",
                got: "The statically inspectable source disables outline or box-shadow without a replacement focus-visible rule.",
                fix: "Restore the framework focus style or add an explicit :focus-visible replacement.",
                docsId: "HFC1052");
        }

        if ((Contains(source, "data-fc-lifecycle") || Contains(source, "data-fc-status")) && !Contains(source, "\"aria-live\"")) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationAriaLiveParityMissing,
                location,
                what: "A customization component replaces lifecycle/status UI without aria-live parity.",
                expected: "Lifecycle, loading, empty, and status override surfaces preserve the framework polite/assertive announcement category.",
                got: "The statically inspectable source identifies a lifecycle/status surface but no aria-live attribute.",
                fix: "Add the same aria-live category used by the generated framework surface.",
                docsId: "HFC1053");
        }

        if ((Contains(source, "transition:") || Contains(source, "@keyframes") || Contains(source, "animation:"))
            && !Contains(source, "prefers-reduced-motion")) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationReducedMotionMissing,
                location,
                what: "A customization component defines motion without a reduced-motion fallback.",
                expected: "Custom override animations and transitions include @media (prefers-reduced-motion: reduce).",
                got: "The statically inspectable source contains motion CSS without the reduced-motion media query.",
                fix: "Add a reduced-motion media query that disables or reduces the animation/transition.",
                docsId: "HFC1054");
        }

        if ((Contains(source, "color:") || Contains(source, "background:") || Contains(source, "border-color:") || Contains(source, "fill:"))
            && !Contains(source, "forced-colors")) {
            Report(
                report,
                DiagnosticDescriptors.CustomizationForcedColorsMissing,
                location,
                what: "A customization component defines custom color styling without forced-colors evidence.",
                expected: "Override-owned color, border, and fill CSS includes a forced-colors path using system color keywords.",
                got: "The statically inspectable source contains custom color CSS without @media (forced-colors: active).",
                fix: "Add a forced-colors media query or move the color pair to framework tokens verified elsewhere.",
                docsId: "HFC1055");
        }
    }

private static bool HasProjectionTemplateAttribute(INamedTypeSymbol type) {
        // Level 2 — class-level attribute.
        foreach (AttributeData attribute in type.GetAttributes()) {
            if (attribute.AttributeClass?.ToDisplayString() == ProjectionTemplateAttributeName) {
                return true;
            }
        }

        return false;
    }

private static string? GetDeclaredSource(INamedTypeSymbol type, CancellationToken cancellationToken) {
        // P8 — bound the source-text scan size. Quadratic scans over partial classes that
        // sprawl across many files are the documented Roslyn analyzer perf trap.
        StringBuilder builder = new(capacity: 4 * 1024);
        foreach (SyntaxReference reference in type.DeclaringSyntaxReferences) {
            string fragment = reference.GetSyntax(cancellationToken).ToFullString();
            if (builder.Length + fragment.Length > MaxAnalyzedSourceBytes) {
                // Truncate at the cap; subsequent fragments are dropped silently. Adopters
                // with classes this large likely have bigger problems than partial coverage.
                int remaining = MaxAnalyzedSourceBytes - builder.Length;
                if (remaining > 0) {
                    _ = builder.Append(fragment, 0, remaining);
                }

                break;
            }

            _ = builder.Append(fragment).Append('\n');
        }

        // P9 — strip C# comments before the substring scans so commented-out code does not
        // produce false positives. String literals are preserved intentionally — the analyzer
        // matches call-site shape (`builder.AddAttribute(_, "onclick", _)`) where the attribute
        // name lives inside a string literal. CSS rules in companion .razor.css files are not
        // part of DeclaringSyntaxReferences and are unaffected.
        return StripComments(builder.ToString());
    }

private static string StripComments(string source) {
        if (source.Length == 0) {
            return source;
        }

        StringBuilder result = new(source.Length);
        int i = 0;
        while (i < source.Length) {
            char c = source[i];

            // Single-line comment.
            if (c == '/' && i + 1 < source.Length && source[i + 1] == '/') {
                int end = source.IndexOf('\n', i + 2);
                if (end < 0) {
                    break;
                }

                _ = result.Append('\n');
                i = end + 1;
                continue;
            }

            // Block comment.
            if (c == '/' && i + 1 < source.Length && source[i + 1] == '*') {
                int end = source.IndexOf("*/", i + 2, StringComparison.Ordinal);
                if (end < 0) {
                    break;
                }

                _ = result.Append(' ');
                i = end + 2;
                continue;
            }

            // String literal — copy through unchanged so analyzer detection on call-site
            // string-literal arguments still works.
            if (c == '"') {
                _ = result.Append('"');
                int j = i + 1;
                while (j < source.Length) {
                    char k = source[j];
                    _ = result.Append(k);
                    if (k == '\\' && j + 1 < source.Length) {
                        j++;
                        if (j < source.Length) {
                            _ = result.Append(source[j]);
                        }

                        j++;
                        continue;
                    }

                    if (k == '"') {
                        break;
                    }

                    if (k == '\n') {
                        break;
                    }

                    j++;
                }

                i = j < source.Length ? j + 1 : j;
                continue;
            }

            // Verbatim string @"..." — copy through unchanged.
            if (c == '@' && i + 1 < source.Length && source[i + 1] == '"') {
                _ = result.Append('@').Append('"');
                int j = i + 2;
                while (j < source.Length) {
                    char k = source[j];
                    _ = result.Append(k);
                    if (k == '"') {
                        if (j + 1 < source.Length && source[j + 1] == '"') {
                            _ = result.Append('"');
                            j += 2;
                            continue;
                        }

                        break;
                    }

                    j++;
                }

                i = j < source.Length ? j + 1 : j;
                continue;
            }

            _ = result.Append(c);
            i++;
        }

        return result.ToString();
    }

private static readonly JsonSerializerOptions _canonicalOptions = new() {
        WriteIndented = false,
        DefaultIgnoreCondition = JsonIgnoreCondition.Never,
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
        TypeInfoResolver = SchemaFingerprintJsonContext.Default,
    };

private static readonly System.Text.Json.Serialization.Metadata.JsonTypeInfo<SchemaContractDocument> _canonicalTypeInfo
#if NET11_0_OR_GREATER
        = _canonicalOptions.GetTypeInfo<SchemaContractDocument>();
#else
        = (System.Text.Json.Serialization.Metadata.JsonTypeInfo<SchemaContractDocument>)_canonicalOptions.GetTypeInfo(typeof(SchemaContractDocument));

public static SchemaCanonicalPayload CreatePayload(SchemaContractDocument document) {
#if NET10_0_OR_GREATER
        ArgumentNullException.ThrowIfNull(document);
#else
        if (document is null) {
            throw new ArgumentNullException(nameof(document));
        }
#endif
        SchemaMaterialValidationResult validation = ValidateDocument(document);
        if (!validation.IsValid) {
            throw new SchemaMaterialValidationException(validation);
        }

        SchemaContractDocument normalized = Normalize(document);
        string json = JsonSerializer.Serialize(normalized, _canonicalTypeInfo);
        // P-43: producer-side parser validation closes the AC25 / D16 emit-side gap.
        SchemaMaterialValidationResult roundTrip = ValidateCanonicalJson(json);
        if (!roundTrip.IsValid) {
            throw new SchemaMaterialValidationException(roundTrip);
        }
        string hash = Sha256Hex(json);
        return new SchemaCanonicalPayload(
            normalized,
            json,
            new SchemaFingerprint(SchemaFingerprintAlgorithm.Sha256CanonicalJsonV1, hash));
    }

[System.Diagnostics.CodeAnalysis.SuppressMessage("Style", "IDE0057:Use range operator", Justification = "Not supported in this context")]
    public static SchemaMaterialValidationResult ValidateCanonicalJson(string json) {
        if (string.IsNullOrWhiteSpace(json)) {
            return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.malformed", "$");
        }

        // P-31: strip a leading UTF-8 BOM before we hand bytes to Utf8JsonReader.
        string normalizedJson = json.Length == 0 || json[0] != '﻿' ? json : json.Substring(1);

        // P-33: bound payload size before allocating the UTF-8 byte array.
        int byteCount = Encoding.UTF8.GetByteCount(normalizedJson);
        if (byteCount > MaxCanonicalJsonBytes) {
            return new(false, SchemaMaterialValidationCategory.PayloadTooLarge, "schema.json.payload-too-large", "$");
        }

        try {
            var reader = new Utf8JsonReader(Encoding.UTF8.GetBytes(normalizedJson), new JsonReaderOptions {
                AllowTrailingCommas = false,
                CommentHandling = JsonCommentHandling.Disallow,
                MaxDepth = _maxDepth,
            });
            return ValidateJsonObject(ref reader, "$");
        }
        catch (JsonException ex) {
            // P-30: depth-exceeded is a distinct category so consumers get actionable remediation.
            bool depthExceeded = ex.Message?.IndexOf("depth", StringComparison.OrdinalIgnoreCase) >= 0;
            return depthExceeded
                ? new(false, SchemaMaterialValidationCategory.JsonDepthExceeded, "schema.json.depth-exceeded", "$")
                : new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.malformed", "$");
        }
    }

public static SchemaMaterialValidationResult ValidateDocument(SchemaContractDocument document) {
#if NET10_0_OR_GREATER
        ArgumentNullException.ThrowIfNull(document);
#else
        if (document is null) {
            throw new ArgumentNullException(nameof(document));
        }
#endif

        if (!string.Equals(document.RootDiscriminator, "frontcomposer.schema.contract.v1", StringComparison.Ordinal)) {
            return new(false, SchemaMaterialValidationCategory.UnknownRootDiscriminator, "schema.root.unknown", "$.RootDiscriminator");
        }

#if NET10_0_OR_GREATER
        if (!Enum.IsDefined(document.Family)) {
#else
        if (!Enum.IsDefined(typeof(SchemaContractFamily), document.Family)) {
#endif
            return new(false, SchemaMaterialValidationCategory.UnknownContractFamily, "schema.family.unknown", "$.Family");
        }

        foreach (SchemaCollectionContract collection in document.Collections) {
            if (string.IsNullOrWhiteSpace(collection.Name) || string.IsNullOrWhiteSpace(collection.StableIdField)) {
                return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.collection.invalid", "$.Collections");
            }
        }

        // P-29: field-name duplicates carry their own category distinct from collection-level
        // stable-id collisions so consumers can branch on validation feedback meaningfully.
        HashSet<string> fieldNames = new(StringComparer.Ordinal);
        foreach (SchemaFieldContract field in document.Fields) {
            if (!fieldNames.Add(field.Name)) {
                return new(false, SchemaMaterialValidationCategory.DuplicateFieldName, "schema.field.duplicate-name", "$.Fields." + field.Name);
            }
        }

        return SchemaMaterialValidationResult.Valid;
    }

private static SchemaContractDocument Normalize(SchemaContractDocument document)
        => document with {
            RootDiscriminator = NormalizeScalar(document.RootDiscriminator),
            ContractId = NormalizeScalar(document.ContractId),
            ContractSchemaVersion = NormalizeScalar(document.ContractSchemaVersion),
            BoundedContext = NormalizeOptional(document.BoundedContext),
            FullyQualifiedName = NormalizeOptional(document.FullyQualifiedName),
            ProtocolIdentifier = NormalizeOptional(document.ProtocolIdentifier),
            Fields = [.. document.Fields
                .OrderBy(f => f.Name, StringComparer.Ordinal)
                .Select(NormalizeField)],
            Collections = [.. document.Collections
                .OrderBy(c => c.Name, StringComparer.Ordinal)
                .Select(c => c with {
                    Name = NormalizeScalar(c.Name),
                    StableIdField = NormalizeScalar(c.StableIdField),
                })],
            Metadata = NormalizeDictionary(document.Metadata),
        };

private static SchemaFieldContract NormalizeField(SchemaFieldContract field)
            => field with {
                Name = NormalizeScalar(field.Name),
                TypeName = NormalizeScalar(field.TypeName),
                JsonType = NormalizeScalar(field.JsonType),
                Title = NormalizeOptional(field.Title),
                Description = NormalizeOptional(field.Description),
                EnumValues = field.EnumValues is null
                ? []
                : [.. field.EnumValues.Select(NormalizeScalar).OrderBy(v => v, StringComparer.Ordinal)],
                ValidationConstraints = NormalizeDictionary(field.ValidationConstraints),
                Metadata = NormalizeDictionary(field.Metadata),
            };

private static string? NormalizeOptional(string? value) {
        if (value is null) {
            return null;
        }

        string normalized = NormalizeScalar(value);
        return normalized.Length == 0 ? AbsentValueSentinel : normalized;
    }

private static string NormalizeScalar(string value) {
        if (string.IsNullOrEmpty(value)) {
            return string.Empty;
        }

        // P-8: strip a leading BOM and known zero-width characters that arrive from
        // YAML/markdown loaders; normalize Unicode line separators alongside the existing
        // CR/LF normalization so culturally identical strings produce identical hashes.
        var sb = new StringBuilder(value.Length);
        foreach (char c in value) {
            switch (c) {
                case '﻿': // BOM
                case '​': // zero-width space
                case '‌': // zero-width non-joiner
                case '‍': // zero-width joiner
                    continue;
                case '\r':
                    _ = sb.Append('\n');
                    continue;
                case '\u2028': // line separator
                case '\u2029': // paragraph separator
                    _ = sb.Append('\n');
                    continue;
                default:
                    _ = sb.Append(c);
                    continue;
            }
        }

        return sb.ToString().Replace("\r\n", "\n").Trim();
    }

private static string Sha256Hex(string value) {
#if NET10_0_OR_GREATER
        // Byte-identical to SHA256.Create().ComputeHash(...); the static one-shot avoids the
        // per-call algorithm instance. The canonical fingerprint bytes are unchanged.
        byte[] bytes = SHA256.HashData(Encoding.UTF8.GetBytes(value));
#else
        using var sha = SHA256.Create();
        byte[] bytes = sha.ComputeHash(Encoding.UTF8.GetBytes(value));
#endif
        char[] chars = new char[bytes.Length * 2];
        const string Hex = "0123456789abcdef";
        for (int i = 0; i < bytes.Length; i++) {
            chars[i * 2] = Hex[bytes[i] >> 4];
            chars[(i * 2) + 1] = Hex[bytes[i] & 0xF];
        }

        return new string(chars);
    }

private static SchemaMaterialValidationResult ValidateArray(ref Utf8JsonReader reader, string path) {
        int index = 0;
        while (reader.Read()) {
            if (reader.TokenType == JsonTokenType.EndArray) {
                return SchemaMaterialValidationResult.Valid;
            }

            SchemaMaterialValidationResult nested = ValidateJsonValue(ref reader, path + "[" + index.ToString(System.Globalization.CultureInfo.InvariantCulture) + "]");
            if (!nested.IsValid) {
                return nested;
            }

            index++;
        }

        return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.unclosed-array", path);
    }

private static SchemaMaterialValidationResult ValidateJsonObject(ref Utf8JsonReader reader, string path) {
        if (!reader.Read() || reader.TokenType != JsonTokenType.StartObject) {
            return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.root-object", path);
        }

        return ValidateObjectBody(ref reader, path);
    }

private static SchemaMaterialValidationResult ValidateJsonValue(ref Utf8JsonReader reader, string path)
        => reader.TokenType switch {
            JsonTokenType.StartObject => ValidateObjectBody(ref reader, path),
            JsonTokenType.StartArray => ValidateArray(ref reader, path),
            JsonTokenType.String or JsonTokenType.Number or JsonTokenType.True or JsonTokenType.False or JsonTokenType.Null
                => SchemaMaterialValidationResult.Valid,
            _ => new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.value-invalid", path),
        };

private static SchemaMaterialValidationResult ValidateObjectBody(ref Utf8JsonReader reader, string path) {
        HashSet<string> exact = new(StringComparer.Ordinal);
        HashSet<string> caseVariant = new(StringComparer.OrdinalIgnoreCase);
        while (reader.Read()) {
            if (reader.TokenType == JsonTokenType.EndObject) {
                return SchemaMaterialValidationResult.Valid;
            }

            if (reader.TokenType != JsonTokenType.PropertyName) {
                return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.property-expected", path);
            }

            string property = reader.GetString() ?? string.Empty;
            string propertyPath = path + "." + property;
            if (!exact.Add(property) || !caseVariant.Add(property)) {
                return new(false, SchemaMaterialValidationCategory.DuplicateJsonKey, "schema.json.duplicate-key", propertyPath);
            }

            if (!reader.Read()) {
                return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.value-expected", propertyPath);
            }

            SchemaMaterialValidationResult nested = ValidateJsonValue(ref reader, propertyPath);
            if (!nested.IsValid) {
                return nested;
            }
        }

        return new(false, SchemaMaterialValidationCategory.MalformedJson, "schema.json.unclosed-object", path);
    }

public SchemaBaselineProvenance(
        SchemaContractFamily contractFamily,
        string contractSchemaVersion,
        string fingerprintAlgorithm,
        string packageOwner,
        string fixtureId,
        bool requiresMigrationGuide,
        string canonicalizerVersion = SchemaFingerprintAlgorithm.CanonicalizerVersionV1,
        string testVectorId = SchemaFingerprintAlgorithm.TestVectorIdV1) {
        // Inline null/empty validation rather than `ArgumentException.ThrowIfNullOrEmpty` so the
        // record stays compatible with the netstandard2.0 target framework.
        ThrowIfNullOrEmpty(contractSchemaVersion, nameof(contractSchemaVersion));
        ThrowIfNullOrEmpty(fingerprintAlgorithm, nameof(fingerprintAlgorithm));
        ThrowIfNullOrEmpty(packageOwner, nameof(packageOwner));
        ThrowIfNullOrEmpty(fixtureId, nameof(fixtureId));
        ThrowIfNullOrEmpty(canonicalizerVersion, nameof(canonicalizerVersion));
        ThrowIfNullOrEmpty(testVectorId, nameof(testVectorId));

        if (!SafeIdentifier.IsMatch(packageOwner)) {
            throw new ArgumentException(
                "Package owner must match the safe-identifier pattern (alphanumerics with dot/dash/underscore, 1-128 chars).",
                nameof(packageOwner));
        }

        if (!SafeIdentifier.IsMatch(fixtureId)) {
            throw new ArgumentException(
                "Fixture id must match the safe-identifier pattern (alphanumerics with dot/dash/underscore, 1-128 chars). Path-traversal segments and untrusted lookup keys are rejected before resolution.",
                nameof(fixtureId));
        }

        ContractFamily = contractFamily;
        ContractSchemaVersion = contractSchemaVersion;
        FingerprintAlgorithm = fingerprintAlgorithm;
        PackageOwner = packageOwner;
        FixtureId = fixtureId;
        RequiresMigrationGuide = requiresMigrationGuide;
        CanonicalizerVersion = canonicalizerVersion;
        TestVectorId = testVectorId;
    }

private static void ThrowIfNullOrEmpty(string value, string paramName) {
        if (string.IsNullOrEmpty(value)) {
            throw new ArgumentException("Value cannot be null or empty.", paramName);
        }
    }

public static string Build(string? boundedContext, string commandTypeName) {
        if (string.IsNullOrWhiteSpace(commandTypeName)) {
            throw new ArgumentException("The command type name cannot be null, empty, or whitespace.", nameof(commandTypeName));
        }

        int lastDot = commandTypeName.LastIndexOf('.');
        string simpleTypeName = lastDot >= 0 ? commandTypeName.Substring(lastDot + 1) : commandTypeName;
        if (string.IsNullOrWhiteSpace(simpleTypeName)) {
            throw new ArgumentException("The command type name must contain a simple type-name segment.", nameof(commandTypeName));
        }

        if (boundedContext is not null && boundedContext.Length > 0 && string.IsNullOrWhiteSpace(boundedContext)) {
            throw new ArgumentException("The bounded context cannot be whitespace.", nameof(boundedContext));
        }

        string contextSegment = string.IsNullOrEmpty(boundedContext) ? DefaultBoundedContext : boundedContext!;
        string sanitizedContext = SanitizeSegment(contextSegment);
        string sanitizedCommand = SanitizeSegment(simpleTypeName);
        ValidateSafeSegment(sanitizedContext, nameof(boundedContext));
        ValidateSafeSegment(sanitizedCommand, nameof(commandTypeName));
        return "/commands/" + sanitizedContext + "/" + sanitizedCommand;
    }

private static string SanitizeSegment(string segment) {
        if (segment.Length == 0) {
            return "_";
        }

        StringBuilder builder = new(segment.Length);
        foreach (char character in segment) {
            _ = builder.Append(
                char.IsLetterOrDigit(character) || character == '.' || character == '-' || character == '_'
                    ? character
                    : '-');
        }

        return builder.ToString();
    }

private static void ValidateSafeSegment(string segment, string parameterName) {
        if (segment is "." or "..") {
            throw new ArgumentException("Route segments cannot be relative path markers.", parameterName);
        }
    }

public static bool IsSafeRelativePath(string? returnPath) {
        if (string.IsNullOrWhiteSpace(returnPath)) {
            return false;
        }

        string path = returnPath!;

        // Reject protocol-relative URLs (//host) and backslash variants that some browsers treat
        // as path separators on Windows-derived parsers.
        if (HasProtocolRelativePrefix(path)) {
            return false;
        }

        // Reject any form that the URI parser recognizes as absolute with a real (web/network)
        // scheme — http, https, javascript, mailto, file://host, etc.
        // NOTE: on Unix, Uri.TryCreate("/path", Absolute) SUCCEEDS with an implicit `file` scheme
        // (a leading-slash path is a valid absolute *file* path there; on Windows it returns false).
        // A leading-slash relative URL is exactly what the check below requires, so the implicit
        // `file` scheme must not be treated as "absolute" here — only real schemes are rejected.
        // Cross-origin `file://host/...` forms are still blocked: they do not start with `/`, so the
        // leading-slash requirement below rejects them.
        if (Uri.TryCreate(path, UriKind.Absolute, out Uri? absolute)
            && !string.Equals(absolute.Scheme, Uri.UriSchemeFile, StringComparison.Ordinal)) {
            return false;
        }

        // Require a leading slash so the value resolves under the application's base path
        // rather than relative to the current page.
        if (!StartsWithSlash(path)) {
            return false;
        }

        if (ContainsUnsafeCharacters(path)) {
            return false;
        }

        if (!IsWellFormedRootRelativePath(path)) {
            return false;
        }

        // Path-traversal defense: reject paths that contain a `..` segment anywhere. Under a
        // non-root base href, `/../admin` escapes the intended scope.
        if (HasUnsafePathShape(path)) {
            return false;
        }

        // Percent-encoding bypass defense: repeatedly decode a bounded number of times and
        // re-assert the security invariants after each pass. This catches double-encoded slash
        // and traversal payloads such as `/%252f/evil.example` and `/%252e%252e/admin`.
        // Malformed percent sequences are rejected up-front by HasInvalidPercentEncoding;
        // modern .NET's UnescapeDataString returns malformed sequences unchanged rather than
        // throwing, so the catch below is a fail-closed safety net for legacy netstandard2.0
        // runtimes only.
        string current = path;
        for (int i = 0; i < MaxDecodeIterations; i++) {
            string decoded;
            try {
                decoded = Uri.UnescapeDataString(current);
            }
            catch (UriFormatException) {
                return false;
            }

            if (string.Equals(decoded, current, StringComparison.Ordinal)) {
                return true;
            }

            if (!StartsWithSlash(decoded)
                || ContainsUnsafeCharacters(decoded)
                || HasUnsafePathShape(decoded)) {
                return false;
            }

            current = decoded;
        }

        return false;
    }

private static bool StartsWithSlash(string path)
#if NET10_0_OR_GREATER
        => path.StartsWith('/');
#else
        => path.StartsWith("/", StringComparison.Ordinal);

private static bool HasProtocolRelativePrefix(string path)
        => path.StartsWith("//", StringComparison.Ordinal)
            || path.StartsWith("/\\", StringComparison.Ordinal)
            || path.StartsWith("\\\\", StringComparison.Ordinal)
            || path.StartsWith("\\/", StringComparison.Ordinal);

private static bool ContainsBackslash(string path)
#if NET10_0_OR_GREATER
        => path.Contains('\\');
#else
        => path.IndexOf('\\') >= 0;

private static bool HasUnsafePathShape(string path)
        => HasProtocolRelativePrefix(path)
            || path.Contains(":/", StringComparison.Ordinal)
            || ContainsBackslash(path)
            || HasTraversalSegment(path)
            || path.Contains("//", StringComparison.Ordinal);

private static bool HasTraversalSegment(string path) {
#if NET10_0_OR_GREATER
        int queryIndex = path.AsSpan().IndexOfAny(_queryOrFragmentDelimiters);
#else
        int queryIndex = path.IndexOfAny(_queryOrFragmentDelimiters);
#endif
        string pathOnly = queryIndex >= 0 ? path.Substring(0, queryIndex) : path;
        return pathOnly == "/.."
            || pathOnly.StartsWith("/../", StringComparison.Ordinal)
            || pathOnly.EndsWith("/..", StringComparison.Ordinal)
            || pathOnly.Contains("/../", StringComparison.Ordinal);
    }

private static bool ContainsUnsafeCharacters(string path) {
        for (int i = 0; i < path.Length; i++) {
            char c = path[i];
            if (char.IsControl(c) || (char.IsWhiteSpace(c) && c != ' ') || IsForbiddenUriChar(c)) {
                return true;
            }

            if (char.IsHighSurrogate(c)) {
                if (i + 1 >= path.Length || !char.IsLowSurrogate(path[i + 1])) {
                    return true;
                }

                if (CharUnicodeInfo.GetUnicodeCategory(path, i) == UnicodeCategory.Format) {
                    return true;
                }

                i++;
                continue;
            }

            if (char.IsLowSurrogate(c)) {
                return true;
            }

            // Only non-ASCII code points can be in the Unicode "format" category, so skip the
            // category lookup on the ASCII fast path.
            if (c > (char)127 && CharUnicodeInfo.GetUnicodeCategory(path, i) == UnicodeCategory.Format) {
                return true;
            }
        }

        return false;
    }

private static bool IsWellFormedRootRelativePath(string path) {
        foreach (char c in path) {
            if (char.IsWhiteSpace(c) || IsForbiddenUriChar(c)) {
                return false;
            }
        }

        return !HasInvalidPercentEncoding(path)
            && Uri.TryCreate(path, UriKind.Relative, out _);
    }

private static bool HasInvalidPercentEncoding(string path) {
        for (int i = 0; i < path.Length; i++) {
            if (path[i] != '%') {
                continue;
            }

            if (i + 2 >= path.Length
                || !IsHexDigit(path[i + 1])
                || !IsHexDigit(path[i + 2])) {
                return true;
            }
        }

        return false;
    }

private static bool IsHexDigit(char c)
        => c is (>= '0' and <= '9')
            or (>= 'A' and <= 'F')
            or (>= 'a' and <= 'f');

public string RegistrationSource { get; } = string.IsNullOrWhiteSpace(RegistrationSource)
        ? "<unknown>"
        : RegistrationSource;

